var ZAIKA_EXTRA_AR={"beefpho":{"intro":"الفو هو أشهر حساء في فيتنام، وقلبه مرق صاف بطعم البصل والزنجبيل المحمرين واليانسون النجمي والقرفة والقرنفل وصلصة السمك، يغلي بلطف مع عظام اللحم حتى يصبح غنيا دون أن يصبح عكرا أبدا. والنودلز تطبخ بشكل منفصل، ولحم البقر يقطع شرائح رفيعة كالورق ويطبخ في المرق الساخن عند سكبه فوقه، ويتم الوعاء على الطاولة ببراعم الفاصوليا والريحان التايلاندي والكزبرة والليمون والفلفل الحار. ويستغرق وقتا، لكن العمل في الغالب انتظار وإزالة رغوة، والنتيجة وعاء خفيف وعطري ومريح بعمق، لا يشبه يخنة ثقيلة.","ing":["عظام لحم بقر 1.5 كغ","عظام نخاع أو مفصل","صدر أو ساق لحم بقر 500 غرام","نودلز أرز 500 غرام (مسطحة)","بصل 2","زنجبيل 1 قطعة كبيرة","يانسون نجمي 3","عود قرفة 1","قرنفل 4","بذور كزبرة 1 ملعقة صغيرة","بذور شمر 1 ملعقة صغيرة","صلصة سمك 4 ملاعق كبيرة","سكر صخري 1 ملعقة كبيرة","براعم فاصوليا وريحان تايلاندي وكزبرة وليمون وفلفل حار للتقديم"],"steps":["اسلق العظام في ماء مغلي لمدة 5 دقائق، وصفها، واشطفها، وأعدها إلى قدر نظيف مع ماء بارد طازج.","احمر نصفي البصل والزنجبيل فوق لهب مفتوح أو تحت شواية ساخنة حتى يسودا في بقع، ثم أضفهما إلى القدر.","حمص اليانسون النجمي والقرفة والقرنفل والكزبرة والشمر في مقلاة جافة لمدة دقيقتين حتى تفوح رائحتها، واربطها في قماش موسلين أو أضفها سائبة وصفها لاحقا.","اترك المرق يغلي بلطف شديد لمدة ساعتين ونصف، مع إزالة الرغوة كثيرا، وأضف الصدر لآخر 60 دقيقة حتى يلين.","ارفع الصدر، وبرده قليلا، وقطعه شرائح رفيعة، وصف المرق عبر مصفاة ناعمة حتى يصبح صافيا.","تبل المرق بصلصة السمك والسكر الصخري، وتذوق أثناء العمل، حتى يصبح مالحا وعطريا وحلوا قليلا فقط.","اطبخ نودلز الأرز بشكل منفصل، وصفها، وقسمها بين الأوعية مع شرائح الصدر وشرائح لحم البقر النيئة الرفيعة.","اسكب المرق المغلي فوق كل وعاء، حتى ينضج لحم البقر النيئ في الحرارة، وقدمه مع الأعشاب والبراعم والليمون والفلفل الحار."],"tip":"أبق الغليان هادئا وأزل الرغوة كثيرا. فالغليان القوي يجعل المرق عكرا ودهنيا، بينما الغليان الهادئ يبقيه صافيا ونظيف الطعم.","notes":["تحمير البصل والزنجبيل يضيف حلاوة مدخنة ضرورية للفو. ولا تتخطها، ولا تقشر البصل بالكامل، فقشره يضيف لونا.","السكر الصخري يوازن صلصة السمك دون أن يجعل المرق حلو الطعم. والسكر العادي يعمل، لكن استخدم قليلا أقل.","قطع لحم البقر النيئ وهو مجمد جزئيا. فهو يقطع رفيعا وبالتساوي، وينضج في ثوان في المرق الساخن.","نودلز الأرز يجب أن تنقع أو تطبخ حتى تصبح طرية فقط، ثم تصفى جيدا، حتى لا تمتص كل المرق في الوعاء."],"variations":["فو الدجاج: استخدم دجاجة كاملة وعظام دجاج، واتركها تغلي لمدة 60 إلى 75 دقيقة، وفتت اللحم للأوعية.","فو نباتي: استخدم مرق فطر وخضار مع التوابل نفسها والبصل والزنجبيل المحمرين، وتوفو وفطر في الأعلى.","فو أكثر حرارة: أضف شرائح فلفل حار طازج وصلصة فلفل حار على الطاولة، بدلا من المرق، حتى يتحكم كل شخص في الحرارة."],"serving":"يكفي 6 أشخاص، في أوعية عميقة، مع الأعشاب والبراعم والليمون والفلفل الحار في أوعية منفصلة في وسط الطاولة. وكل شخص يضيف أعشابه وعصرة ليمون، ويأكل بعيدان الطعام وملعقة، النودلز أولا، ثم المرق. والفو يقدم ساخنا بالبخار ويؤكل فورا، بينما الأعشاب ما زالت طازجة ولحم البقر ناضج للتو.","storage":"يبقى المرق في الثلاجة لمدة تصل إلى 4 أيام ويتجمد جيدا لمدة تصل إلى 3 أشهر. واحفظ المرق والنودلز والإضافات بشكل منفصل، واجمعها طازجة. وأعد تسخين المرق حتى يغلي، واطبخ نودلز طازجة، وقطع لحم البقر قبل التقديم مباشرة. وصدر البقر المطهو المتبقي يبقى لمدة يومين في الثلاجة. ولا تحفظ الأوعية المجمعة.","mistakes":["غلي المرق بقوة. يصبح عكرا ويستحلب الدهن في الحساء، لذلك أبقه على غليان خفيف جدا.","عدم إزالة الرغوة. فالرغوة والدهن المتروكان في القدر يبهتان النكهة والصفاء.","الإفراط في طهي النودلز. تمتص المرق وتصبح عجينية، لذلك اطبخها بشكل منفصل وصفها جيدا.","نسيان تذوق التتبيل. فيجب موازنة صلصة السمك والسكر في النهاية، لذلك تبل بكميات صغيرة وتذوق كثيرا."],"faq":[["هل يمكنني تحضير الفو في قدر الضغط؟","نعم. اطبخ العظام تحت الضغط لمدة 60 إلى 75 دقيقة، ثم صفها وتبلها. والنكهة قريبة جدا، وإن كان المرق أقل صفاء قليلا."],["أي لحم بقر هو الأفضل للشرائح النيئة؟","لحم الخاصرة أو عين المستديرة، مقطع رفيعا جدا وهو مجمد جزئيا. وهو ينضج في المرق الساخن في ثوان."],["هل الفو خال من الغلوتين؟","نودلز الأرز ومعظم صلصة السمك خالية من الغلوتين طبيعيا، لكن تحقق من ملصقات صلصة السمك والهويسن للإضافات."],["هل يمكنني تحضير المرق مسبقا؟","نعم، ويتحسن طوال الليل. احفظه في الثلاجة، وأزل الدهن المتصلب، وأعد تسخينه حتى يغلي."]]},"biryani":{"intro":"البرياني هو الطبق الذي تحتفظ به معظم البيوت للضيوف والاحتفالات، ويشتهر الطراز الكراتشي بالتوابل القوية وحبات الأرز المنفصلة ورائحة الدم التي تملأ البيت قبل رفع الغطاء. والطريقة أدناه تحافظ على طراوة الدجاج وعطر الأرز دون أن تتحول الطبقات إلى كتلة طرية واحدة. والتتبيلة تقوم بالعمل الأكبر في النكهة، لذلك فإن الطبخ نفسه هو في الغالب ترتيب الطبقات والانتظار. قدمه مباشرة من القدر مع الرايتا والسلطة، ودع الناس يأخذون حصة ثانية وهو ما زال يتصاعد منه البخار.","ing":["دجاج 750 غرام","زبادي 1 كوب","أرز بسمتي 3 أكواب (منقوع)","بهارات برياني 3 ملاعق كبيرة","معجون الزنجبيل والثوم 2 ملعقة كبيرة","بصل 3 (محمر)","طماطم 2","فلفل أخضر حار 4","كزبرة طازجة","نعناع","ليمون","زعفران / لون طعام","سمن 3 ملاعق كبيرة","ملح","أوراق غار","هيل وقرنفل (لماء الأرز)"],"steps":["اغسل الأرز حتى يصبح الماء صافيا، وانقعه لمدة 30 دقيقة، ثم صفه. اخلط الزبادي وبهارات البرياني ومعجون الزنجبيل والثوم والملح مع الدجاج وتبل لمدة 30 دقيقة.","اغل قدرا كبيرا من الماء مع الملح والبهارات الكاملة. أضف الأرز واطبخه حتى ينضج بنسبة 70 بالمئة ويبقى متماسكا في الوسط، ثم صفه فورا.","سخن السمن، وحمر البصل حتى يصبح ذهبيا غامقا، وأزل نصفه للطبقات. وأبق الباقي في المقلاة.","أضف الطماطم والدجاج المتبل، واقله على نار متوسطة عالية لمدة 10 إلى 12 دقيقة، حتى تتكاثف الماسالا وينفصل الزيت.","افرد ماسالا الدجاج في قدر ثقيل. أضف نصف الأرز، ثم رش الكزبرة والنعناع والبصل المحمر والليمون والزعفران.","أضف باقي الأرز وغطه بباقي البصل والأعشاب والزعفران وملعقة من السمن. وأحكم إغلاق الغطاء بقطعة قماش أو ورق قصدير.","اطبخ على نار هادئة على الدم لمدة 20 دقيقة دون فتح الغطاء، ثم اتركه يرتاح لمدة 10 دقائق بعيدا عن النار.","افتح الغطاء، وحرك الأرز بلطف من الجوانب بشوكة، واخلطه بخفة حتى تبقى الألوان ظاهرة، وقدمه ساخنا."],"tip":"لا تبالغ في سلق الأرز. فسيكمل طهيه على الدم. ضع قطعة قماش فوق الغطاء على الدم حتى لا يخرج البخار، وتذوق ماء الأرز. يجب أن يكون طعمه مالحا قليلا، لأن الأرز السادة يحتاج إلى ذلك التتبيل.","notes":["الدجاج بالعظم يبقى أطرى أثناء الدم. استخدم قطع الفخذ وأزل الدهن الزائد.","الأرز البسمتي القديم يعطي حبات منفصلة. والأرز الجديد يصبح طريا بسهولة أكبر، لذلك راقب وقت السلق.","الزبادي كامل الدسم يجعل التتبيلة تلتصق بالدجاج. والزبادي قليل الدسم قد يتكتل عند ملامسته الحرارة.","بهارات البرياني تختلف باختلاف العلامة التجارية. تذوق الماسالا قبل إضافة فلفل حار إضافي، وعدل في المرة القادمة، وليس الآن."],"variations":["برياني الخضار: استبدل الدجاج بالبطاطس والقرنبيط والبازلاء والجزر، وتبل الخضار لفترة قصيرة، وقصر مدة الدم إلى 15 دقيقة.","برياني لحم الضأن: استخدم 750 غراما من لحم الضأن، واطبخ الماسالا حتى يكاد اللحم ينضج قبل ترتيب الطبقات، واتركه 30 دقيقة على الدم.","أقل حرارة: قلل الفلفل الأخضر الحار إلى النصف، وتخط الفلفل الأحمر الإضافي، وقدمه مع رايتا إضافية."],"serving":"يكفي 4 أشخاص بسخاء مع الرايتا وسلطة الكاتشومبر وشرائح الليمون. ضع القدر في وسط الطاولة وافتحه هناك، حتى يحصل الجميع على رائحة الدم. والنان اختياري، لأن الأرز هو الطبق الرئيسي. وكوب من اللاسي أو مشروب النعناع يوازن التوابل جيدا.","storage":"برده خلال ساعة واحدة واحفظه في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى يومين. أعد تسخينه في مقلاة مغطاة على نار هادئة مع ملعقتين كبيرتين من الماء، أو في الميكروويف مغطى، حتى يصبح ساخنا بالبخار في كل أجزائه. ولا تعيد تسخينه أكثر من مرة واحدة. جمده في حصص لمدة تصل إلى شهر واحد، وأذبه في الثلاجة طوال الليل قبل إعادة التسخين.","mistakes":["سلق الأرز بالكامل قبل الدم. فإنه يتحول إلى عجين في القدر.","فتح الغطاء أثناء الدم. يخرج البخار ويبقى الأرز غير مطهو.","استخدام القليل جدا من الملح في ماء الأرز. فتصبح الطبقات بلا طعم.","التقليب بقوة بعد الدم. تتكسر الحبات وتختلط الألوان في لون واحد."],"faq":[["هل يمكنني تحضير البرياني دون زعفران؟","نعم. استخدم رشة من لون الطعام الأصفر مذابة في حليب دافئ، أو تخطها. فالنكهة تأتي من الماسالا والدم، وليس من اللون وحده."],["كم يجب أن يتبل الدجاج؟","30 دقيقة هي الحد الأدنى. ومن ساعتين إلى أربع ساعات في الثلاجة أفضل. أبقه في الثلاجة، ولا تترك الدجاج المتبل في درجة حرارة الغرفة."],["لماذا أصبح أرزي لزجا؟","لأن الأرز سلق أكثر من اللازم، أو لم يصف فورا، أو حرك القدر بقوة. صفه عند نضج بنسبة 70 بالمئة واترك القدر يرتاح قبل تفكيكه."],["هل يمكنني استخدام دجاج دون عظم؟","نعم. استخدم قطع الفخذ وقلل طهي الماسالا بمقدار 3 إلى 4 دقائق، حتى لا يجف الدجاج."]]},"bobotie":{"intro":"البوبوتي هو طبق اللحم المفروم المخبوز المحبوب في جنوب أفريقيا، بجذور في طبخ كيب الملايو، حيث يطبخ اللحم المفروم المتبل محلى بالفاكهة ومغنى بخبز منقوع، ويخبز تحت طبقة كاسترد بيض ذهبية مع أوراق الغار. والنكهة دافئة وحلوة بلطف، مسحوق الكاري والكركم والتشاتني والزبيب والمشمش تعمل معا، والقوام طري ومريح، بين خبز مالح وخبز لحم خفيف. وقدمه مع أرز أصفر وتشاتني وسلطة بسيطة، ودع توازن الحلو والمالح يتكلم. وهو طبق مثالي يحضر مسبقا لحشد، لأنه يسخن بشكل جميل ويصبح طعمه أفضل في اليوم التالي.","ing":["لحم بقر أو ضأن مفروم 750 غراما","بصل 1","ثوم 2 فص","زنجبيل 1 ملعقة صغيرة","مسحوق كاري 2 ملعقة كبيرة","كركم 1 ملعقة صغيرة","خبز أبيض 2 شريحة","حليب 250 مل","بيض 3","أوراق غار 4","تشاتني 3 ملاعق كبيرة","زبيب 3 ملاعق كبيرة","مشمش مجفف 4 (مفروم)","عصير ليمون 1 ملعقة كبيرة","لوز 2 ملعقة كبيرة (مقشر)","ملح وفلفل"],"steps":["انقع الخبز في 125 مل من الحليب حتى يلين، ثم اعصر الحليب الزائد وفتت الخبز.","اقل البصل والثوم والزنجبيل في الزيت لمدة 5 دقائق حتى يلين، ثم أضف مسحوق الكاري والكركم واقله لمدة دقيقة واحدة.","أضف اللحم المفروم واقله، مع تفتيته، حتى يتحمر في كل أجزائه ويتبخر السائل.","حرك الخبز المنقوع والتشاتني والزبيب والمشمش وعصير الليمون والتتبيل، واطبخه لمدة 5 دقائق. وتذوق وعدل التوازن بين الحلو والحامض.","ضع اللحم المفروم بالملعقة في طبق خبز مدهون بالزبدة، واضغطه بالتساوي، وأدخل أوراق الغار في الأعلى.","اخفق باقي الحليب مع بيضتين ورشة ملح، واسكبه بلطف فوق اللحم المفروم.","اخبزه على 180 درجة مئوية لمدة 35 إلى 40 دقيقة، حتى تتماسك الطبقة العلوية وتصبح ذهبية، وتغلي الحواف.","اتركه يرتاح لمدة 10 دقائق، وانثر اللوز المقشر، وقدمه مع الأرز الأصفر وتشاتني إضافية."],"tip":"تذوق اللحم المفروم قبل الخبز. فيجب أن يكون التوازن بين الحلو والحامض والحار صحيحا في هذه المرحلة، لأن الخبز لن يصلحه.","notes":["الخبز المنقوع يبقي اللحم المفروم طريا وخفيفا. وبدونه، يمكن أن يصبح البوبوتي كثيفا وجافا.","مسحوق الكاري يختلف كثيرا. استخدم مسحوق كاري خفيفا على طراز كيب الملايو إذا استطعت، وأضف المزيد فقط بعد التذوق.","التشاتني تضيف حلاوة وحموضة. وتشاتني الفاكهة تقليدية، وتشاتني المانجو تعمل جيدا أيضا.","أوراق الغار توضع في الأعلى، ولا تخلط، حتى تنكه الكاسترد وتبدو جميلة عند التقديم."],"variations":["مع العدس: استبدل نصف اللحم المفروم بعدس بني مطهو، لنسخة أخف بالتوابل نفسها.","بوبوتي نباتي: استخدم العدس والفطر مع الفاكهة والتشاتني وطبقة البيض نفسها.","نسخة أكثر حرارة: أضف حبة فلفل حار طازجة مفرومة مع البصل، وقدمها مع تشاتني إضافية وسامبال على الجانب."],"serving":"يكفي 6 أشخاص، مع أرز أصفر وتشاتني فاكهة وسلطة خضراء مقرمشة أو سلطة طماطم وبصل مقطع. وقدمه مباشرة من طبق الخبز، في مربعات سخية، مع الطبقة الذهبية وورقة غار على كل حصة. والبوبوتي طبق عائلي، لذلك ضع الطبق في وسط الطاولة، مع الأرز والتشاتني بجانبه، ودع الجميع يخدمون أنفسهم.","storage":"يبقى البوبوتي في الثلاجة لمدة تصل إلى 3 أيام، مغطى، ويسخن جيدا في الفرن على 160 درجة مئوية حتى يسخن تماما. وهو يتجمد جيدا أيضا لمدة تصل إلى 3 أشهر، ويذاب طوال الليل في الثلاجة. وطبقة البيض يمكن أن تدمع قليلا عند إعادة التسخين، لذلك أعد تسخينه بلطف ومغطى بورق قصدير. والأرز الأصفر يبقى بشكل منفصل لمدة يومين.","mistakes":["استخدام لحم مفروم خال جدا من الدهن دون خبز. يصبح جافا ويتفتت، لذلك أبق الخبز المنقوع فيه.","المبالغة في خبز الطبقة العلوية. تصبح مطاطية، لذلك أخرجه بمجرد أن تتماسك وتصبح ذهبية.","تخطي الراحة. يتفكك البوبوتي عند تقطيعه ساخنا، لذلك اتركه يرتاح لمدة 10 دقائق قبل التقديم.","جعله حلوا جدا. تذوق اللحم المفروم، ووازن التشاتني والفاكهة بعصير الليمون، وليس بمزيد من السكر."],"faq":[["هل يمكنني تحضير البوبوتي مسبقا؟","نعم. اجمعه بالكامل، واحفظه في الثلاجة لمدة تصل إلى يوم واحد، واخبزه عند الحاجة، مع إضافة 10 دقائق إلى وقت الخبز."],["هل البوبوتي حار؟","هو متبل بدفء، وليس حارا. ومسحوق الكاري يعطي نكهة، والفاكهة والتشاتني تبقيه لطيفا."],["ما هو الأرز الأصفر؟","أرز مطهو مع الكركم والزبيب وأحيانا القرفة، يقدم مع البوبوتي في جنوب أفريقيا. والأرز العادي يعمل أيضا."],["هل يمكنني استخدام لحم ضأن مفروم؟","نعم. لحم الضأن يصنع بوبوتي أغنى. وصف أي دهن زائد بعد التحمير، حتى لا يكون الخبز دهنيا."]]},"bouillabaisse":{"intro":"البويابيس يأتي من مرسيليا، حيث صنع الصيادون حساء من السمك الذي لم يبع، وهو الآن من أكثر أطباق الاحتفال المحبوبة في فرنسا. والمرق هو النجم، مبني من مرق السمك والطماطم والشمر وقشر البرتقال والزعفران وزيت الزيتون، والسمك والمحار يطبخان فيه لبضع دقائق فقط، حتى يبقيا طريين. وقدمه في جزأين إذا استطعت، مرق مصفى في أوعية وسمك على طبق، مع الروي، وهو مايونيز ثوم بالزعفران، مدهون على خبز محمص. ويبدو فخما، لكن الطريقة بسيطة، حضر مرقا جيدا، وأضف السمك بالترتيب الصحيح، ولا تبالغ في طهيه.","ing":["سمك أبيض متماسك مشكل 800 غرام (مقطع إلى قطع)","روبيان 300 غرام","بلح البحر 300 غرام (منظف)","مرق سمك 1.5 لتر","طماطم 400 غرام (مفرومة)","معجون طماطم 2 ملعقة كبيرة","شمر 1 بصلة","بصل 1","كراث 1","زعفران 1 رشة كبيرة","قشر برتقال 1 شريط","ثوم 4 فصوص","زيت زيتون 4 ملاعق كبيرة","زعتر","خبز مقرمش وروي وبقدونس وليمون للتقديم"],"steps":["سخن زيت الزيتون في قدر كبير، واقل البصل والكراث والشمر والثوم لمدة 8 دقائق حتى يلين ويصبح حلوا.","أضف معجون الطماطم والطماطم المفرومة، واطبخ لمدة 5 دقائق حتى تبدأ الطماطم في التفكك.","اسكب مرق السمك، وأضف الزعفران وقشر البرتقال والزعتر ورشة ملح، واتركه يغلي على نار هادئة لمدة 20 دقيقة.","صف المرق عبر مصفاة، مع الضغط على الخضار للحصول على كل النكهة، ثم أعد المرق إلى القدر.","أعد المرق إلى غليان هادئ ولطيف، وأضف السمك الأكثر تماسكا أولا، واطبخه لمدة 3 دقائق.","أضف باقي السمك والروبيان، واطبخه لمدة 3 إلى 4 دقائق إضافية، حتى ينضج تماما.","أضف بلح البحر، وغطه، واطبخه لمدة 3 دقائق حتى ينفتح. وتخلص من أي بلح يبقى مغلقا.","اسكب المرق والمأكولات البحرية في أوعية دافئة، وقدمها مع خبز محمص مدهون بالروي وبقدونس وليمون."],"tip":"لا تبالغ في طهي السمك. أضف القطع الأكثر تماسكا أولا والقطع الرقيقة أخيرا، وأبعد القدر عن النار بمجرد أن يتقشر السمك.","notes":["الزعفران غال، لكن رشة تحوله المرق باللون والرائحة. وانقعه في ملعقة من المرق الساخن لمدة 10 دقائق قبل إضافته.","استخدم مزيجا من السمك، مثل سمك الراهب والقاروص والبوري الأحمر إذا وجدتها. فسمك واحد وحده يصنع حساء أرق.","قشر البرتقال يضيف نكهة مشرقة وعطرة كلاسيكية في مرسيليا. استخدم شريطا عريضا دون لب أبيض، وأزله قبل التقديم.","الروي يصنع بخفق صفار البيض والثوم والزعفران والليمون وزيت الزيتون حتى يصبح مايونيزا. والأيولي الجاهز بالزعفران اختصار مقبول."],"variations":["مع المحار: أضف محارا منظفا مع بلح البحر، وتخلص من أي محار لا ينفتح.","نسخة أبسط لأيام الأسبوع: استخدم الروبيان فقط وسمكا أبيض متماسكا واحدا، مع المرق نفسه، وقدمه مع الخبز.","مع البطاطس: أضف بطاطس مقطعة إلى المرق واتركها تغلي حتى تلين قبل إضافة السمك، لحساء أكثر إشباعا."],"serving":"يكفي 6 أشخاص، في أوعية دافئة عميقة، مع السمك والمحار مرتبين في الأعلى، وطبق من خبز محمص مغطى بالروي في وسط الطاولة. وكل شخص يضع الروي بالملعقة في المرق أو يدهنه على الخبز، ويعصر الليمون فوق السمك. وقدمه مع سلطة خضراء وكوب من النبيذ الأبيض الجاف، وأبق الخبز يأتي، لأن المرق جيد جدا ليترك.","storage":"البويابيس يؤكل طازجا أفضل، في اليوم الذي يصنع فيه. والمرق وحده يبقى في الثلاجة لمدة تصل إلى يومين ويتجمد جيدا لمدة شهر واحد. والسمك المتبقي لا يسخن جيدا ويمكن أن يصبح مطاطيا، لذلك احفظ المرق بشكل منفصل وأضف سمكا طازجا عند إعادة التسخين. أعد تسخين المرق حتى يغلي، ثم اطبخ المأكولات البحرية طازجة فيه.","mistakes":["المبالغة في طهي المأكولات البحرية. فالسمك والروبيان يتحولان من طري إلى قاس في دقيقة، لذلك راقب القدر عن قرب.","تخطي خطوة التصفية. يبقى المرق متكتلا والنكهة أقل وضوحا، لذلك صف واضغط الخضار.","استخدام سمك دهني. فالسلمون والماكريل يطغيان على المرق الرقيق، لذلك استخدم سمكا أبيض متماسكا.","إضافة كل السمك دفعة واحدة. يتفتت السمك الرقيق بينما السمك المتماسك ما زال يطبخ، لذلك أضفه على مراحل."],"faq":[["هل يمكنني استخدام مرق سمك جاهز من المتجر؟","نعم. اختر مرقا ذا جودة جيدة، واتركه يغلي مع الخضار والزعفران كما هو مكتوب. وسيظل طعمه غنيا."],["ما هو الروي؟","مايونيز زعفران وثوم من بروفانس، يدهن على الخبز المحمص ويحرك في الحساء. وهو يضيف غنى ولونا."],["هل يمكنني تحضير البويابيس دون محار؟","نعم، استخدم السمك فقط، وأضف قليلا إضافيا من مرق السمك. والحساء ما زال ممتازا، وإن كان أقل تنوعا."],["هل الزعفران ضروري؟","هو يعطي اللون والرائحة الكلاسيكيين. وبدونه، الحساء ما زال جيدا، لكنه ليس بويابيس تماما."]]},"bunkebab":{"intro":"بن كباب هو طعام شارع كراتشي الذي له أتباع مخلصون، خبز طري، وكباب شامي مقلي، وبصل وطماطم مقطعان، وتشاتني تجلب الحرارة والحموضة والانتعاش في كل لقمة. وهو طعام سريع يصنع في البيت في 25 دقيقة، بشرط أن تكون كباب الشامي جاهزة، وأفضل ما يؤكل ساخنا، مباشرة من الطاوة، مع خبز محمص قليلا وما زال طريا. والتوازن أهم من أي مكون واحد. فالكثير من التشاتني يغرق الكباب، والقليل جدا يترك الخبز جافا، والخبز المحمص جيدا يجمع كل شيء دون أن يتفكك في يديك.","ing":["كباب شامي 8","خبز 4","بصل","طماطم","تشاتني خضراء","تشاتني تمر هندي","زبادي","فلفل أخضر حار","كزبرة طازجة","زبدة لتحميص الخبز"],"steps":["قطع البصل إلى حلقات رفيعة، وقطع الطماطم، وأبق التشاتني والفلفل الحار والكزبرة جاهزة في أوعية صغيرة.","سخن قليلا من الزيت على طاوة على نار متوسطة. اقل كباب الشامي لمدة 2 إلى 3 دقائق لكل جانب، حتى يسخن تماما ويصبح مقرمشا قليلا عند الحواف.","أبعد الكباب وأبقه دافئا. امسح الطاوة بخفة، وأضف الزبدة، وحمص الجوانب المقطوعة من الخبز حتى تصبح ذهبية قليلا، حوالي دقيقة واحدة.","ادهن التشاتني الخضراء على الخبز السفلي وتشاتني التمر الهندي على الخبز العلوي. وطبقة رفيعة تكفي، فالكباب يجب أن يبقى هو النجم.","ضع كبابين على كل خبز سفلي. وإذا كان الكباب صغيرا، تداخله قليلا حتى تحتوي كل لقمة على كباب.","أضف حلقات البصل وشرائح الطماطم والفلفل الأخضر الحار والكزبرة. وأضف ملعقة من الزبادي المخفوق إذا أردت لقمة أبرد وأكثر كريمية.","أغلق الخبز واضغط بلطف. ويجب أن تصل التشاتني إلى الحواف فقط، دون أن تتقطر.","قدمه ساخنا فورا، مع تشاتني إضافية على الجانب ومشروب بارد. وكله بكلتا يديك، على طراز كراتشي."],"tip":"لا تبالغ في تحميص الخبز. فالذهبي الخفيف يكفي، وإلا سيصبح صلبا ويتفتت، وسينزلق الكباب خارجا بدلا من أن يجلس مريحا في الداخل.","notes":["يجب أن يكون كباب الشامي طريا من الداخل ومقرمشا قليلا من الخارج. وإذا كان طريا جدا، برده لمدة 15 دقيقة قبل القلي، حتى يحافظ على شكله.","استخدم خبز برغر طريا، وليس لفائف مقرمشة. فالخبز يجب أن ينضغط بلطف حول الكباب، لا أن يقاومه.","تشاتني التمر الهندي تعطي النكهة الحلوة الحامضة. وتذوقها أولا، لأن بعضها حلو جدا ويحتاج إلى أقل.","حلقات البصل تبقى مقرمشة إذا قطعت قبل التقديم مباشرة. والبصل المقطوع المتروك يصبح طريا وحادا."],"variations":["بن كباب بالدجاج: استخدم كباب شامي بالدجاج وأضف قليلا إضافيا من التشاتني الخضراء، لأن الدجاج أخف من اللحم البقري.","بن كباب بالبيض: أضف بيضة مقلية فوق الكباب، مع صفار متماسك فقط، لنسخة شارع أغنى.","بن كباب حار: أضف شرائح فلفل أخضر حار وملعقة من صلصة الفلفل الحار بالثوم، وتخط الزبادي."],"serving":"يكفي 4 أشخاص، مع بن كباب واحد لكل شخص، وتشاتني إضافية، وسلطة بسيطة أو بطاطس مقلية على الجانب. وبن كباب طعام شارع، لذلك قدمه ملفوفا في ورق أو على طبق، ساخنا من الطاوة، وكله فورا. ويتناسب جيدا مع لاسي بارد، أو مشروب غازي، أو شاي. ولحشد أكبر، ضع الخبز والكباب والتشاتني ودع الناس يبنون خاصتهم.","storage":"بن كباب يؤكل طازجا أفضل ولا يحفظ جيدا بعد تجميعه، لأن الخبز يمتص التشاتني. أبق الأجزاء منفصلة. وكباب الشامي المطهو يبقى في الثلاجة لمدة تصل إلى يومين ويسخن على طاوة. والتشاتني تبقى في الثلاجة لمدة تصل إلى 4 أيام في برطمانات محكمة. وحمص وجمع قبل التقديم مباشرة، حتى يبقى الخبز طريا والكباب ساخنا.","mistakes":["المبالغة في تحميص الخبز. يصبح صلبا ويتشقق، وتسقط الحشوة.","إغراق الكباب في التشاتني. يضيع التوازن ويصبح الخبز مبللا في دقائق.","قلي الكباب على نار عالية جدا. يحترق الخارج بينما يبقى الوسط باردا.","التجميع مبكرا جدا. يمتص الخبز الرطوبة وتلين الحواف المقرمشة قبل أن يأكل أحد."],"faq":[["ما هو كباب الشامي؟","كباب طري مصنوع من لحم مفروم وعدس، يطبخ ويطحن ويشكل، ثم يقلى. وهو طري بما يكفي لينضغط في الخبز، على عكس كباب سيخ متماسك."],["هل يمكنني استخدام كباب شامي مجمد؟","نعم. اقله مباشرة من المجمد على نار متوسطة، مع إعطاء دقيقة إلى دقيقتين إضافيتين لكل جانب، حتى يسخن تماما. ولا تذبه أولا، لأن الكباب الطري يتكسر."],["أي خبز هو الأفضل؟","خبز برغر طري وسادة. وخبز السمسم يعمل أيضا. وتجنب اللفائف الصلبة، لأنها تتشقق وتسقط الحشوة."],["هل يمكنني تحضيره دون تشاتني التمر الهندي؟","نعم. استخدم تشاتني خضراء إضافية وعصرة ليمون للحموضة. والنكهة مختلفة، لكنها ما زالت تعمل جيدا."]]},"carbonara":{"intro":"الكاربونارا الحقيقية لا تحتوي على كريمة. وهي تأتي من روما، وصلصتها تصنع فقط من البيض وجبن بيكورينو والفلفل الأسود والدهن من الغوانشيالي أو البانشيتا، مخلوطة مع باستا ساخنة حتى تصبح لامعة وحريرية. والحيلة هي التحكم في الحرارة. يجب أن تكون المقلاة ساخنة بما يكفي لطهي البيض بلطف حتى يصبح صلصة، لكن دون أن تكون ساخنة جدا فيتخثر. واعمل بسرعة، واستخدم ماء الباستا لتخفيف الصلصة، وقدمها فورا. وبمجرد أن تتعلم التوقيت، يصبح هذا من أسرع أطباق الباستا وأكثرها راحة، بمكونات قليلة وعمق نكهة يبدو أكثر تعقيدا بكثير مما هو عليه.","ing":["سباغيتي 400 غرام","غوانشيالي أو بانشيتا 150 غراما (مقطعة)","صفار بيض 4","بالإضافة إلى بيضة كاملة واحدة","بيكورينو رومانو 60 غراما (مبشور ناعما)","فلفل أسود 2 ملعقة صغيرة (مجروش طازجا)","ملح لماء الباستا","بيكورينو وفلفل إضافيان للتقديم"],"steps":["اسلق السباغيتي في ماء مملح جيدا حتى تصبح ألدينتي فقط، واحتفظ بكوب واحد من ماء الباستا قبل تصفيتها.","اقل الغوانشيالي أو البانشيتا في مقلاة جافة على نار متوسطة لمدة 6 إلى 8 دقائق حتى تصبح مقرمشة عند الحواف ويذوب الدهن.","اخفق الصفار والبيضة الكاملة والبيكورينو ومعظم الفلفل الأسود حتى تصبح عجينة سميكة. وأضف ملعقة من ماء الباستا إذا كانت قاسية جدا.","أبعد المقلاة عن النار واتركها تبرد لمدة دقيقة واحدة، حتى لا يتخثر البيض عندما يلامس المقلاة.","أضف السباغيتي المصفاة إلى المقلاة وقلبها جيدا في الدهن المذاب لمدة 30 ثانية.","اسكب خليط البيض والجبن وقلب بسرعة وباستمرار، مع إضافة ماء الباستا رشة في كل مرة حتى تصبح الصلصة لامعة وتغطي كل خيط.","تذوق، وأضف المزيد من الفلفل، وأضف الملح فقط إذا لزم الأمر، لأن البيكورينو والبانشيتا مالحان أصلا.","قدمها فورا في أوعية دافئة، مع بيكورينو وفلفل أسود إضافيين في الأعلى."],"tip":"أبعد المقلاة عن النار قبل إضافة البيض. فالحرارة المتبقية تصنع الصلصة، والحرارة المباشرة تصنع بيضا مخفوقا.","notes":["بيكورينو رومانو حاد ومالح، وهو الجبن التقليدي. والبارميزان يعمل، لكنه أخف، لذلك استخدم قليلا أكثر وتذوق قبل إضافة الملح.","الغوانشيالي هو خد خنزير معالج ويعطي النكهة الكلاسيكية. والبانشيتا هي أقرب بديل سهل، ولحم الخنزير المقدد مقبول، وإن كان أكثر تدخينا.","ماء الباستا مليء بالنشا. وهو يساعد صلصة البيض على الالتصاق بالسباغيتي بدلا من الانزلاق عنها.","الفلفل الأسود المجروش طازجا مهم هنا. فهو نكهة رئيسية، وليس مجرد تزيين، لذلك اجرشه خشنا واستخدم الكثير منه."],"variations":["مع البازلاء: أضف حفنة من البازلاء إلى ماء الباستا في الدقيقة الأخيرة، للون والحلاوة.","على الطراز النباتي: استبدل لحم الخنزير بفطر مقلي في الزبدة وزيت الزيتون، وأضف قليلا من البابريكا المدخنة، وإن كانت النتيجة طبقا مختلفا.","نسخة أخف: استخدم بيضتين كاملتين وصفارين بدلا من 4 صفار، وقليلا أقل من الجبن، لصلصة ما زالت حريرية."],"serving":"يكفي 4 أشخاص كطبق رئيسي، في أوعية دافئة، مع سلطة خضراء بسيطة وخبز مقرمش على الجانب. والكاربونارا وجبة وعاء واحد، لذلك أبق الأطباق الجانبية خفيفة ودع الباستا تكون النجمة. وقدمها في اللحظة التي تقلب فيها، لأن الصلصة تتكاثف عندما تبرد وتفقد حريريتها.","storage":"الكاربونارا تؤكل طازجة أفضل ولا تسخن جيدا، لأن صلصة البيض تتكاثف ويمكن أن تنفصل. وإذا اضطررت للاحتفاظ بها، احفظها في الثلاجة لمدة تصل إلى يوم واحد وأعد تسخينها بلطف شديد في مقلاة مع رشة من الماء، مع التحريك المستمر. ولا تجمدها. والباستا المطبوخة وحدها تبقى لمدة يومين، لكن حضر الصلصة طازجة.","mistakes":["إضافة البيض إلى مقلاة ما زالت على النار. يتخثر البيض وتصبح الصلصة متكتلة.","استخدام الكريمة. تصنع صلصة مختلفة وأثقل وتخفي نكهة البيكورينو.","تصفية كل ماء الباستا. وبدونه، تكون الصلصة سميكة جدا ولن تغطي الباستا.","إضافة الملح قبل التذوق. فالبيكورينو ولحم الخنزير المعالج مالحان، لذلك تذوق أولا."],"faq":[["هل يمكنني استخدام لحم الخنزير المقدد بدلا من الغوانشيالي؟","نعم. اقله حتى يصبح مقرمشا، وصف قليلا من الدهن إذا كان كثيرا. والنكهة أكثر تدخينا، لكن الطريقة هي نفسها."],["لماذا تخثرت صلصتي؟","كانت المقلاة ساخنة جدا. أبعدها عن النار، وبردها لمدة دقيقة، وقلب بسرعة مع ماء الباستا في المرة القادمة."],["هل يمكنني تحضير الكاربونارا دون لحم خنزير؟","نعم، مع الفطر أو البازلاء، لكنها لن يكون طعمها مثل الكاربونارا الكلاسيكية. وأبق صلصة البيض والبيكورينو كما هي."],["كيف أعرف كمية ماء الباستا؟","ابدأ برشة صغيرة وأضف المزيد أثناء التقليب. ويجب أن تبدو الصلصة لامعة وسائلة، وليست سميكة وعجينية."]]},"chapli":{"intro":"كباب تشابلي هو بيشاور في طبق، مسطح وطري وغني بالتوابل، ويقلى على طاوة حتى تصبح حوافه مقرمشة. والاسم يأتي من شكله المسطح، والنكهة تأتي من الطماطم وبذور الرمان والكزبرة الكاملة المجروشة والفلفل الأخضر الحار المخلوط مباشرة في اللحم المفروم. وهو طعام شارع وطعام احتفال في آن واحد، يؤكل مع النان والبصل والتشاتني الخضراء، وأفضل ما يصنع بلحم مفروم بارد وأيد لطيفة. اقله على نار متوسطة هادئة حتى ينضج الوسط دون أن يحترق الخارج، واضغط قطعة طماطم في الوسط، كما يفعل صانعو الكباب.","ing":["لحم بقر مفروم 500 غرام","طماطم 1 مفرومة ناعما","بصل 1","بذور رمان 1 ملعقة كبيرة","كزبرة كاملة مجروشة","فلفل أخضر حار 3","زنجبيل","ملح","دقيق ذرة 2 ملعقة كبيرة","زيت للقلي"],"steps":["افرم البصل والطماطم ناعما جدا واعصر عصير الطماطم الزائد، حتى يبقى الخليط متماسكا بما يكفي لتشكيله.","ضع اللحم المفروم في وعاء مع الطماطم والبصل وبذور الرمان والكزبرة المجروشة والفلفل الحار والزنجبيل والملح ودقيق الذرة. واخلط بيديك حتى يمتزج فقط.","غطه واترك الخليط يرتاح في الثلاجة لمدة 20 دقيقة. فاللحم المفروم البارد يحافظ على شكله ويقلى أفضل.","بلل يديك بماء بارد. خذ حصة، وسطحها إلى قرص رفيع عرضه حوالي 4 بوصات، واضغط قطعة طماطم صغيرة في الوسط.","سخن طبقة سخية من الزيت على طاوة على نار متوسطة. يجب أن يكون الزيت ساخنا بما يكفي ليصدر صوتا، لكن دون أن يدخن.","أدخل الكباب مع ترك مسافة بينها. واقلها لمدة 4 إلى 5 دقائق على الجانب الأول دون الضغط عليها.","اقلبها بلطف بملعقة عريضة واقلها لمدة 4 إلى 5 دقائق إضافية، حتى تصبح ذهبية على الجانبين وتنضج تماما.","ارفعها، وصفها لفترة قصيرة، وقدمها ساخنة مع التشاتني الخضراء والبصل المقطع والنان."],"tip":"لا تضغط الكباب كثيرا. اقلبها بلطف وإلا ستتكسر. واللحم المفروم البارد يصنع كبابا أفضل، لذلك أبق الخليط في الثلاجة حتى تشكل كل دفعة.","notes":["استخدم لحما مفروما فيه بعض الدهن، حوالي 15 إلى 20 بالمئة. فاللحم المفروم الخالي جدا من الدهن يصنع كبابا جافا يتفتت.","دقيق الذرة يربط الخليط ويعطي القوام الكلاسيكي. ودقيق القمح يعمل، لكن الكباب يكون أكثر كثافة.","بذور الرمان تعطي نكهة حامضة مفاجئة. اسحقها بخفة، ولا تطحنها إلى عجينة.","الطماطم المفرومة ناعما تضيف رطوبة ونكهة، لكن العصير الكثير يجعل الكباب يتفكك، لذلك صفها أولا."],"variations":["كباب تشابلي بالدجاج: استخدم لحم دجاج مفروم، وأضف ملعقة كبيرة إضافية من دقيق الذرة، واقله لمدة 3 إلى 4 دقائق لكل جانب، لأن الدجاج يطبخ أسرع.","أكثر حرارة: أضف ملعقة صغيرة من الفلفل الأحمر المجروش وحبة فلفل أخضر حار إضافية، وقدمه مع تشاتني إضافية.","برغر تشابلي: ضع كبابا في خبز محمص مع البصل والطماطم والتشاتني وبيضة مقلية، لبرغر على طراز بيشاور."],"serving":"يكفي 4 أشخاص كطبق رئيسي مع النان والتشاتني الخضراء والبصل المقطع والليمون والسلطة. وقدم كبابين لكل شخص مع كثير من التشاتني، وأبق نانا إضافيا دافئا. وكباب تشابلي يعمل أيضا كمقبلات، كباب واحد لكل شخص مع التشاتني والليمون، قبل الطبق الرئيسي. ورايتا النعناع تبرد الحرارة بلطف.","storage":"برده واحفظ الكباب المطهو في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى يومين. أعد تسخينه على طاوة على نار متوسطة حتى يسخن تماما، أو في الفرن على 180 درجة مئوية لمدة 8 إلى 10 دقائق. والخليط غير المطهو يبقى في الثلاجة لمدة تصل إلى يوم واحد. جمد الكباب المشكل وغير المطهو بين أوراق ورق الخبز لمدة تصل إلى شهر واحد، واقله من المجمد، مع إضافة دقيقتين لكل جانب.","mistakes":["تشكيل كباب سميك. يحترق الخارج قبل أن ينضج الوسط، لذلك أبقه رفيعا ومتساويا.","القلي على نار عالية جدا. تحترق التوابل ويتكسر الكباب عند قلبه.","الضغط بالملعقة. يعصر العصارة ويجعل الكباب جافا.","استخدام لحم مفروم دافئ مباشرة من المتجر. فهو طري ولزج وصعب التشكيل، لذلك برده أولا."],"faq":[["لماذا يتكسر كباب التشابلي؟","كان الخليط رطبا جدا، أو كان الكباب سميكا جدا، أو قلب مبكرا جدا. صف الطماطم، وبرد الخليط، وأبق الكباب رفيعا، ودع الجانب الأول يتماسك قبل القلب."],["هل يمكنني خبز كباب التشابلي؟","نعم. ادهنه بالزيت واخبزه على 200 درجة مئوية لمدة 15 إلى 18 دقيقة، مع قلبه مرة واحدة. وهو أقل قرمشة من الكباب المقلي، لكنه ما زال لذيذا."],["ما فائدة بذور الرمان؟","بذور الرمان تعطي نكهة حامضة وفاكهية توازن اللحم المفروم الغني. وإذا لم تجدها، استخدم ملعقة صغيرة من عصير الليمون وقليلا من التوت البري المجفف المجروش، لكن النكهة مختلفة."],["هل يمكنني تحضير الخليط مسبقا؟","نعم. اخلطه واحفظه في الثلاجة لمدة تصل إلى يوم واحد، مغطى. وشكله قبل القلي مباشرة، حتى يحافظ الكباب على شكله."]]},"coqauvin":{"intro":"الكوك أو فان هو طعام فرنسي مريح كلاسيكي، دجاج يطبخ ببطء في نبيذ أحمر حتى يسقط من العظم، مع فطر وبصل لؤلؤي ولحم خنزير مقدد في صلصة بطعم النبيذ دون أن يكون طعمها كحوليا. وهو يأتي من بورغندي، حيث النبيذ جزء من الطبخ، وليس مجرد مرافق، والطبخ البطيء اللطيف هو ما يجعل الدجاج طريا والصلصة غنية. وحمر الدجاج جيدا أولا، لأن ذلك اللون يصبح نكهة، ثم دع القدر يقوم بالعمل في الفرن. وقدمه مع بطاطس مهروسة أو خبز مقرمش، وأعط الصلصة تذوقا أخيرا للملح وقليلا من الزبدة لتجعلها تلمع.","ing":["أفخاذ وأرجل دجاج 1 كغ (بالعظم)","نبيذ أحمر 500 مل (على طراز بورغندي إن أمكن)","لحم خنزير مقدد مقطع 150 غراما","فطر 250 غراما","بصل لؤلؤي 12","جزر 1","ثوم 3 فصوص","زعتر 3 أغصان","مرق دجاج 250 مل","معجون طماطم 1 ملعقة كبيرة","دقيق 2 ملعقة كبيرة","زبدة 2 ملعقة كبيرة","بقدونس للتقديم","ملح وفلفل"],"steps":["تبل الدجاج جيدا، ورشه بخفة بالدقيق، وحمره على دفعات في قدر ساخن يصلح للفرن حتى يصبح ذهبيا عميقا على الجانبين. وضعه جانبا.","اقل لحم الخنزير المقدد في القدر نفسه حتى يصبح مقرمشا، وارفعه، وحمر الفطر والبصل اللؤلؤي في دهن لحم الخنزير.","أضف الجزر والثوم ومعجون الطماطم، واطبخه لمدة دقيقتين، مع التحريك، حتى تفوح رائحته.","اسكب النبيذ، مع كشط قاع القدر لرفع كل النكهة المحمرة، واتركه يغلي على نار هادئة لمدة 3 دقائق.","أعد الدجاج ولحم الخنزير المقدد إلى القدر، وأضف المرق والزعتر، واتركه يغلي غليانا هادئا. ويجب أن يصل السائل إلى منتصف الدجاج.","غطه واطبخه في الفرن على 160 درجة مئوية لمدة 75 إلى 90 دقيقة، حتى يصبح الدجاج طريا جدا.","ارفع الدجاج، واترك الصلصة تغلي على الموقد لمدة 10 دقائق حتى تغطي الملعقة. واخفق الزبدة في النهاية.","أعد الدجاج إلى الصلصة، ودفئه تماما، وقدمه منثورا بالبقدونس."],"tip":"حمر الدجاج جيدا قبل الطبخ البطيء. فالدجاج الشاحب يصنع صلصة شاحبة، بينما الدجاج الذهبي العميق يصنع صلصة غنية وكاملة النكهة.","notes":["الدجاج بالعظم يبقى طريا خلال طبخ بطيء طويل. والدجاج دون عظم يطبخ أسرع ويمكن أن يجف، لذلك قلل وقت الفرن إذا استخدمته.","استخدم نبيذا تشربه. فنبيذ الطبخ الرخيص يصنع صلصة قاسية، بينما النبيذ الأحمر الفاكهي يعطي عمقا ولونا.","البصل اللؤلؤي صغير وحلو. وإذا لم تجده، استخدم كراثا مقطعا إلى أرباع.","الزبدة المخفوقة في النهاية تعطي الصلصة لمعانا ناعما وتكمل النبيذ. ولا تغل الصلصة بعد إضافتها."],"variations":["نسخة النبيذ الأبيض: استخدم نبيذا أبيض جافا وأضف كريمة في النهاية، لكوك أو فان بلان أخف.","مع البطاطس: أضف بطاطس جديدة صغيرة إلى القدر لآخر 40 دقيقة، حتى تطبخ في الصلصة.","نسخة الطباخ البطيء: حمر كل شيء أولا، ثم اطبخه على نار هادئة لمدة 5 إلى 6 ساعات، وقلل الصلصة على الموقد في النهاية."],"serving":"يكفي 4 أشخاص، في أوعية ضحلة، مع بطاطس مهروسة كريمية أو نودلز بالزبدة أو خبز مقرمش لالتقاط الصلصة. ويجب أن يقدم الدجاج مع مغرفة سخية من الصلصة والفطر والبصل ورشة من البقدونس. وهذا طبق يوم أحد، لذلك قدمه على الطاولة من القدر، مع سلطة خضراء بسيطة على الجانب وباقي النبيذ، إذا أردت، في أكواب.","storage":"يبقى الكوك أو فان في الثلاجة لمدة تصل إلى 3 أيام، ويصبح طعمه أفضل في اليوم التالي. أعد تسخينه بلطف على الموقد حتى يغلي، مع إضافة رشة من المرق إذا كانت الصلصة سميكة جدا. وهو يتجمد جيدا لمدة تصل إلى 3 أشهر، ويذاب طوال الليل في الثلاجة. واحفظ الدجاج في صلصته، حتى لا يجف.","mistakes":["تخطي التحمير. ستفتقر الصلصة إلى اللون والعمق، لذلك خذ الوقت لتحمر على دفعات.","غلي الطبخ البطيء بقوة. يقسو الدجاج وتنخفض الصلصة بسرعة كبيرة، لذلك أبق غليانا هادئا وفرنا منخفضا.","استخدام الكثير من النبيذ ودون مرق. تصبح الصلصة حادة، لذلك وازن النبيذ بالمرق وتذوق قبل التقديم.","إضافة الزبدة مبكرا جدا. تنفصل في غليان طويل، لذلك اخفقها في النهاية تماما، بعيدا عن الغليان."],"faq":[["هل يمكنني تحضير الكوك أو فان دون كحول؟","نعم، استبدل النبيذ بمرق إضافي بالإضافة إلى ملعقتين كبيرتين من خل النبيذ الأحمر وقليل من عصير العنب. والنكهة مختلفة، لكن الطبخ البطيء ما زال يعمل."],["هل يمكنني استخدام صدر الدجاج؟","يمكنك، لكن أضفه لآخر 30 دقيقة فقط، وإلا سيجف. والأفخاذ والأرجل أفضل بكثير لهذا الطبق."],["أي نبيذ يجب أن أستخدم؟","نبيذ أحمر جاف وفاكهي، ويفضل من بورغندي. وتجنب النبيذ شديد العفص أو البلوط، الذي يمكن أن يصبح مرا في طبخ بطيء طويل."],["هل يمكنني تحضيره مسبقا؟","نعم، ويتحسن. اطبخه بالكامل، وبرده، واحفظه في الثلاجة، وأعد تسخينه بلطف في اليوم التالي."]]},"daal":{"intro":"دال فراي هو الطبق اليومي الذي يثبت أن الطعام البسيط يمكن أن يبقى لا ينسى، بشرط أن تطبخ الدال طرية وأن تسكب التادكا ساخنة وتغطى فورا. فالعدس الأحمر والمونغ يطبخان بسرعة ويصبحان كريميين دون أي كريمة، والسمن والثوم والكمون والفلفل الأحمر الكامل في الأعلى يعطي الرائحة التي تصل إلى الطاولة قبل الوعاء. وهذا طعام مريح مع الأرز أو الروتي، لأمسيات أيام الأسبوع المزدحمة وللأيام التي لا حاجة فيها إلى شيء فاخر. والوصفة كلها تستغرق حوالي 35 دقيقة، ومعظم ذلك هو الدال تغلي بهدوء.","ing":["عدس أحمر / مونغ دال 1½ كوب","كركم 1/2 ملعقة صغيرة","ملح","ثوم 4 فصوص","كمون 1 ملعقة صغيرة","فلفل أحمر كامل 3","سمن 3 ملاعق كبيرة","فلفل أخضر حار","كزبرة طازجة","ليمون"],"steps":["اغسل الدال في عدة تغييرات من الماء حتى يصبح الماء صافيا في الغالب، ثم صفها جيدا.","ضع الدال في قدر مع الكركم و4 أكواب من الماء. اتركها تغلي، وأزل الرغوة، وخفض الحرارة.","اتركها تغلي على نار هادئة لمدة 20 إلى 25 دقيقة، مع التحريك بين الحين والآخر، حتى تصبح الدال طرية تماما وكريمية. أضف ماء ساخنا إذا أصبحت سميكة جدا.","تذوق وأضف الملح. يجب أن تكون الدال قابلة للسكب، وليست صلبة، لأنها تتكاثف عندما تبرد.","قطع الثوم إلى شرائح رفيعة. سخن السمن في مقلاة صغيرة على نار متوسطة وأضف الكمون. وعندما يصدر صوتا، أضف الثوم.","اقله حتى يصبح الثوم ذهبيا، وليس بنيا. أضف الفلفل الأحمر الكامل، وعد إلى عشرة، وأبعد المقلاة عن النار فورا.","اسكب التادكا الساخنة فوق الدال دفعة واحدة، واستمع لصوت الأزيز، وغط القدر لمدة دقيقتين حتى تبقى الرائحة في الداخل.","حرك الفلفل الأخضر الحار والكزبرة، واعصر الليمون فوقها، وقدمها ساخنة مع الأرز أو الروتي."],"tip":"غط الدال بمجرد سكب التادكا. فهذا يبقي الرائحة داخل الدال بدلا من تركها تهرب إلى المطبخ، ويسمح لنكهة الثوم بالانتشار في القدر كله.","notes":["العدس الأحمر يطبخ أسرع ويصبح كريميا. ودال المونغ تحتفظ بقوام أكثر قليلا. وكلاهما يعمل، وخليط النصف والنصف جيد أيضا.","الكركم للون والنكهة اللطيفة. والكثير منه يجعل الدال مرة، لذلك قسه.","قطع الثوم إلى شرائح، ولا تسحقه للتادكا. فالشرائح تتحول إلى اللون الذهبي بالتساوي وتبقى مقرمشة.","السمن يحمل نكهة التادكا أفضل. والزيت يعمل، لكن أضف فص ثوم إضافيا لتعويضه."],"variations":["دال السبانخ: حرك كوبين من السبانخ المقطعة في الدال المطبوخة واتركها تغلي على نار هادئة لمدة 5 دقائق قبل التادكا.","دال الطماطم: أضف حبة طماطم مقطعة واحدة مع الدال في البداية، لنتيجة حامضة وأسمك قليلا.","ثوم أكثر: ضاعف الثوم في التادكا وأضف نصف ملعقة صغيرة من الفلفل الأحمر المجروش معه."],"serving":"يكفي 4 أشخاص مع أرز مطهو على البخار أو روتي، وشريحة ليمون، وسلطة بسيطة أو مخلل على الجانب. والدال تقدم أفضل وهي سائلة وساخنة، في أوعية عميقة، مع التادكا ظاهرة في الأعلى. وإذا قدمتها مع الأرز، اسكب الدال فوق الأرز على الطاولة. وبيضة مقلية أو قطعة باباد تحولها إلى وجبة أكمل.","storage":"بردها واحفظها في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى 3 أيام. وتتكاثف الدال في الثلاجة، لذلك حرك فيها رشة من الماء الساخن عند إعادة التسخين. أعد تسخينها على نار هادئة، مع التحريك، حتى تصبح ساخنة بالبخار، وأضف كزبرة طازجة بعد إعادة التسخين. جمدها لمدة تصل إلى شهر واحد في حصص، وأذبها في الثلاجة، وحضر تادكا طازجة لأفضل رائحة.","mistakes":["عدم طهي الدال جيدا. فالدال الحبيبية لا تصبح كريمية أبدا، مهما كانت التادكا جيدة.","حرق الثوم. فالثوم البني يصبح مرا ويفسد القدر كله، لذلك أبعد المقلاة عن النار مبكرا.","ترك القدر غير مغطى بعد التادكا. تهرب الرائحة وتصبح الدال بلا طعم.","إضافة الملح في البداية في مناطق الماء العسر يمكن أن تبطئ التليين، لذلك تبل بعد أن تلين الدال إذا بقيت دالك متماسكة."],"faq":[["أي دال هي الأفضل لتادكا دال؟","العدس الأحمر هو الأسرع والأكثر كريمية. ودال المونغ قريبة منه في المرتبة الثانية. ودال التور تعمل أيضا، لكنها تحتاج إلى طهي أطول وقدر الضغط يساعد."],["هل يمكنني تحضير دال فراي دون سمن؟","نعم. استخدم الزيت وأضف فص ثوم إضافيا. والنتيجة أخف، والتادكا ما زالت تعمل، لكن الرائحة أقل غنى."],["لماذا دالي مائية؟","لأنها لم تغل لمدة كافية، أو لأن الكثير من الماء استخدم. اتركها تغلي دون غطاء لبضع دقائق لتتكاثف، وتذكر أنها تتكاثف أكثر عندما تبرد."],["هل يمكنني طهي الدال في قدر الضغط؟","نعم. اطبخها لصفرتين أو حوالي 8 دقائق تحت الضغط، واترك الضغط يخرج طبيعيا، ثم أكمل مع التادكا في قدر مفتوح."]]},"dimsum":{"intro":"ديم سم يعني طعاما يلمس القلب، وهو مخصص للمشاركة، أوعية بخار خيزران صغيرة تصل إلى الطاولة واحدة تلو الأخرى، كل منها فيه لقمة مختلفة في الداخل. وهذه النسخة المنزلية تصنع صنفين كلاسيكيين، هار غاو بالروبيان بأغلفة شفافة، وسيو ماي بلحم الخنزير والروبيان بأعلى مفتوحة، وكلاهما يبخر حتى ينضج تماما ويقدم ساخنا. والأغلفة تحتاج إلى لمسة خفيفة وقليل من الصبر، لكن الحشوة بسيطة، والتبخير سريع. واصنعها بمساعدة، شخص يملأ وآخر يطوي، وأبق الزلابية المكتملة مغطاة حتى لا تجف. وقدمها مع الشاي، كما في يوم تشا الكانتونية، ودع الوجبة تمتد ببطء.","ing":["روبيان 300 غرام (مفروم ناعما)","لحم خنزير مفروم 200 غرام","نشا قمح 120 غراما","نشا تابيوكا 60 غراما (لهار غاو)","أغلفة وونتون 20 (لسيو ماي)","زنجبيل 1 ملعقة كبيرة (مبشور)","بصل أخضر 2","صلصة صويا 2 ملعقة كبيرة","زيت سمسم 1 ملعقة صغيرة","فلفل أبيض","سكر 1 ملعقة صغيرة","نبيذ شاوشينغ 1 ملعقة كبيرة","زيت فلفل حار وصلصة صويا وخل أسود للتقديم"],"steps":["اخلط الروبيان ولحم الخنزير والزنجبيل والبصل الأخضر والصويا وزيت السمسم والسكر والنبيذ والفلفل الأبيض في حشوة، وبردها لمدة 20 دقيقة.","لأغلفة هار غاو، اخلط نشا القمح ونشا التابيوكا مع 180 مل من الماء المغلي للتو، واعجنها حتى تصبح عجينة ناعمة، واتركها مغطاة ترتاح لمدة 15 دقيقة.","لف عجينة هار غاو إلى أسطوانة، وقطعها إلى قطع صغيرة، واضغط كل واحدة إلى قرص رفيع بجانب ساطور أو شوبك.","ضع ملعقة من الحشوة في كل غلاف، واطوها إلى هلال، واثن الحافة بإحكام، وأغلق الأعلى.","لسيو ماي، ضع ملعقة من الحشوة في وسط كل غلاف وونتون، واجمع الحواف لأعلى حول الحشوة، واضغط بلطف حتى يبقى الأعلى مفتوحا.","بطن أوعية بخار الخيزران بورق خبز فيه ثقوب، أو أوراق ملفوف، ورتب الزلابية مع مسافة بينها.","بخر هار غاو لمدة 6 إلى 7 دقائق وسيو ماي لمدة 8 دقائق، حتى تصبح الأغلفة شفافة أو متماسكة وتنضج الحشوة.","قدمها فورا في الأوعية، مع زيت الفلفل الحار وصلصة الصويا والخل الأسود للتغميس، وشاي ساخن على الجانب."],"tip":"لا تفرط في ملء الزلابية. فملعقة صغيرة مستوية من الحشوة تغلق بشكل مرتب، بينما الحشوة الكثيرة تفجر الغلاف في جهاز البخار.","notes":["نشا القمح يجعل أغلفة هار غاو شفافة ورقيقة. والدقيق العادي لن يعطي النتيجة نفسها، لذلك اشتر نشا القمح من متجر آسيوي.","أبق العجينة مغطاة في كل الأوقات. فهي تجف في دقائق وتتشقق عندما تحاول طيها.","برد الحشوة قبل التشكيل. فالحشوة الباردة أسهل في التقسيم وتحافظ على شكلها في الغلاف.","بخر على دفعات إذا لزم الأمر. فأوعية البخار المزدحمة تلتصق معا، والزلابية تتمزق عندما ترفعها."],"variations":["ديم سم بالخضار: استبدل اللحم بفطر وملفوف وجزر وتوفو مفروم ناعما، متبلة بالطريقة نفسها.","ديم سم بالدجاج: استخدم لحم دجاج مفروم مع الروبيان، وأضف كستناء الماء للقرمشة.","مع أغلفة جاهزة من المتجر: استخدم أغلفة زلابية مستديرة لكلا النوعين، مطوية ومغلقة، لنسخة أسهل ما زالت لذيذة جدا."],"serving":"يكفي 4 أشخاص، كجزء من وجبة مشتركة، مع 5 إلى 6 زلابيات لكل شخص، بالإضافة إلى الشاي، وسلطة خيار بسيطة أو خضار مقلية على الجانب. وقدم الأوعية مباشرة إلى الطاولة، والغطاء عليها، حتى تبقى الزلابية ساخنة ومبخرة حتى لحظة أكلها. وديم سم طعام بطيء في لقمات صغيرة، لذلك أعد ملء الشاي، وأحضر الأوعية على دفعات، ولا تستعجل.","storage":"الزلابية غير المطبوخة تتجمد جيدا لمدة تصل إلى شهر واحد على صينية، ثم في أكياس. وبخرها من المجمدة لمدة 3 إلى 4 دقائق أطول. والزلابية المطبوخة تبقى في الثلاجة لمدة يوم واحد، وتسخن بالتبخير لمدة 3 دقائق، وليس في الميكروويف، الذي يقسي الأغلفة. والحشوة المتبقية تبقى لمدة يوم واحد في الثلاجة، مغطاة.","mistakes":["استخدام أغلفة سميكة جدا. تبقى عجينية بعد التبخير، لذلك لفها أو اضغطها رفيعة.","التبخير على جهاز بخار جاف. تلتصق الزلابية وتتمزق، لذلك بطن جهاز البخار وادهنه بخفة.","فتح الغطاء باستمرار. يهرب البخار وتطبخ الزلابية بشكل غير متساو، لذلك أبق الغطاء حتى ينتهي الوقت.","تحضير الزلابية قبل وقت طويل. تجف الأغلفة وتتشقق، لذلك شكلها قبل التبخير مباشرة، أو أبقها مغطاة بقطعة قماش رطبة."],"faq":[["هل يمكنني تحضير ديم سم دون جهاز بخار خيزران؟","نعم. استخدم جهاز بخار معدني أو مصفاة فوق قدر، أو طبقا على رف في مقلاة مغطاة. وبطنها جيدا حتى لا يلتصق شيء."],["لماذا تتشقق أغلفة هار غاو؟","جفت العجينة، أو بردت كثيرا. أبقها مغطاة، واعمل بقطع صغيرة، واعجنها لفترة قصيرة إذا تصلبت."],["هل يمكنني استخدام روبيان مجمد؟","نعم. أذبه بالكامل، وجففه بالتربيت، وافرمه قبل الخلط مباشرة. فالروبيان الرطب يصنع حشوة سائبة."],["أي صلصة تذهب مع ديم سم؟","زيت الفلفل الحار وصلصة الصويا الخفيفة والخل الأسود، مخلوطة حسب الذوق. وقليل من الزنجبيل المبشور في الخل تقليدي."]]},"falafel":{"intro":"الفلافل الحقيقية تصنع من حمص نيئ منقوع، وليس حمصا معلبا أو مطهوا أبدا، وهذا ما يعطيها داخلا خفيفا وهشا وقشرة مقرمشة ووعرة. ويطحن الحمص خشنا مع البصل والثوم والبقدونس والكزبرة والكمون، ويرتاح حتى يتماسك الخليط معا، ثم يشكل ويقلى حتى يصبح ذهبيا عميقا. وقدمه في خبز بيتا دافئ مع سلطة وصلصة طحينة، أو كجزء من طبق مزة مع الحمص. ويمكن تحضير الخليط مسبقا وتبريده، والفلافل تقلى في دقائق، لذلك هي مثالية لحشد، طالما أنك لا تزدحم المقلاة.","ing":["حمص مجفف 250 غراما (منقوع طوال الليل)","بصل 1","ثوم 3 فصوص","بقدونس 1 حزمة كبيرة","كزبرة 1 حزمة","كمون 2 ملعقة صغيرة","مسحوق كزبرة 1 ملعقة صغيرة","مسحوق خبز 1/2 ملعقة صغيرة","دقيق 2 ملعقة كبيرة","ملح 1 ملعقة صغيرة","فلفل أسود","رقائق فلفل حار","زيت للقلي","بيتا وسلطة وصلصة طحينة للتقديم"],"steps":["انقع الحمص في كثير من الماء البارد طوال الليل، ثم صفه جيدا جدا. ولا تطبخه.","ضع الحمص والبصل والثوم والأعشاب والتوابل والملح والفلفل في محضرة طعام، وانبض حتى يصبح خشنا ومتفتتا، وليس عجينة.","انقله إلى وعاء، وحرك الدقيق ومسحوق الخبز فيه، وغطه، واحفظه في الثلاجة لمدة 30 دقيقة ليتماسك.","اختبر فلافل واحدة أولا، وشكل كرة صغيرة، واقلها، وتأكد من أنها تتماسك وتنضج تماما.","شكل الباقي إلى كرات صغيرة أو أقراص، بحجم حبة جوز تقريبا، بأيد مبللة.","سخن الزيت إلى 175 درجة مئوية، واقل على دفعات لمدة 3 إلى 4 دقائق، مع قلبه مرة واحدة، حتى يصبح ذهبيا عميقا ومقرمشا في كل أجزائه.","صفه على رف سلكي، وليس على ورق، حتى تبقى القشرة مقرمشة، ورش قليلا من الملح.","قدمه ساخنا في بيتا مع سلطة وطماطم وخيار وصلصة طحينة، أو على طبق مزة مع الحمص."],"tip":"استخدم حمصا نيئا منقوعا، وليس حمصا مطهوا أبدا. فالحمص المطهو يصنع فلافل طرية وعجينية تتفكك في الزيت.","notes":["النقع طوال الليل ضروري. فالحمص غير المنقوع بما يكفي يبقى صلبا من الداخل، لذلك أعطه 12 ساعة كاملة في ماء بارد.","انبض، ولا تهرس. فالقوام الخشن مع قطع أعشاب ظاهرة يعطي الفلافل لقمته الخفيفة والهشة.","تبريد الخليط يساعده على الحفاظ على شكله. وإذا شعرت أنه رطب، أضف ملعقة من الدقيق، لكن لا تضف الكثير وإلا أصبح الفلافل ثقيلا.","حرارة الزيت مهمة. فالبارد جدا يجعل الفلافل يمتص الزيت، والساخن جدا يحمر الخارج بينما يبقى الداخل نيئا."],"variations":["فلافل مخبوزة: ادهنها بالزيت واخبزها على 200 درجة مئوية لمدة 20 إلى 25 دقيقة، مع قلبها مرة واحدة، لنسخة أخف.","مع الفول العريض: استبدل نصف الحمص بفول عريض مقسوم منقوع، لطعمية على الطراز المصري.","فلافل حارة: أضف حبة فلفل حار طازجة مفرومة وكمونا إضافيا إلى الخليط، وقدمها مع صلصة فلفل حار."],"serving":"يكفي 4 أشخاص، مع 4 إلى 5 حبات فلافل لكل شخص، في بيتا دافئة مع سلطة وطحينة، أو كجزء من طبق مزة. وقدمها في اللحظة التي تخرج فيها من الزيت، بينما القشرة مقرمشة والداخل ساخن وهش، مع شرائح ليمون وطحينة إضافية على الجانب. والفلافل طعام أصابع، لذلك ضع الكثير من البيتا والسلطة والصلصات، ودع الجميع يبنون خاصتهم.","storage":"يبقى خليط الفلافل غير المطهو في الثلاجة لمدة تصل إلى يومين، مغطى. والفلافل المطهو يبقى لمدة يومين في الثلاجة، ويسخن في فرن ساخن حتى يصبح مقرمشا، حوالي 8 دقائق. ولا تستخدم الميكروويف، فهو يصبح طريا. والفلافل المشكل غير المطهو يتجمد جيدا لمدة شهر واحد، ويقلى من المجمد لمدة دقيقة أطول.","mistakes":["استخدام حمص معلب. فهو مطهو أصلا، لذلك يصبح الفلافل عجينيا ويتفكك.","الإفراط في معالجة الخليط. فالعجينة الناعمة تصنع فلافل كثيفا وثقيلا، لذلك انبض لفترة قصيرة وأبقه خشنا.","القلي في زيت بارد جدا. يمتص الفلافل الزيت ويصبح دهنيا، لذلك سخن الزيت جيدا أولا.","تشكيلها كبيرة جدا. فالفلافل الكبير يبقى نيئا من الداخل، لذلك أبقها بحجم حبة الجوز."],"faq":[["هل يمكنني خبز الفلافل بدلا من قليها؟","نعم. وهي أقل قرمشة، لكنها ما زالت لذيذة. ادهنها بالزيت، واخبزها على 200 درجة مئوية، واقلبها مرة واحدة في منتصف المدة."],["لماذا تفكك الفلافل الخاص بي؟","كان الخليط رطبا جدا، أو كان الزيت باردا جدا. برد الخليط، وأضف قليلا من الدقيق، واختبر واحدة أولا."],["هل يمكنني استخدام حمص معلب إذا أضفت دقيقا؟","لا ينصح به. فحتى مع الدقيق، الحمص المطهو يصنع فلافل كثيفا. والحمص النيئ المنقوع ضروري."],["أي صلصة تذهب مع الفلافل؟","صلصة طحينة مخففة بالليمون والماء، بالإضافة إلى سلطة في بيتا. وصلصة الفلفل الحار والمخللات تقليدية أيضا."]]},"feijoada":{"intro":"الفيجوادا هي الطبق الوطني للبرازيل، يخنة فاصوليا سوداء غنية مع مزيج من لحم الخنزير والسجق واللحوم المدخنة، تطبخ ببطء حتى تصبح الفاصوليا كريمية واللحوم طرية. وتقدم تقليديا يوم السبت، كغداء عائلي طويل، مع أرز أبيض وخضار كولارد مقلية وفاروفا، دقيق كسافا محمص، وشرائح برتقال لتقطع الغنى. وتستغرق وقتا، وتطعم حشدا، لذلك اطبخ قدرا كبيرا، وأبق المرافقات بسيطة، ودع الوجبة تمتد. وانقع الفاصوليا طوال الليل، وحمر اللحوم جيدا، وأعط القدر غليانا طويلا ولطيفا، والنتيجة مرضية بعمق.","ing":["فاصوليا سوداء مجففة 500 غرام (منقوعة طوال الليل)","كتف خنزير 500 غرام (مكعبات)","سجق مدخن 300 غرام (مقطع)","لحم خنزير مقدد أو لحم خنزير مملح 200 غرام (مقطع)","بصل 1","ثوم 4 فصوص","أوراق غار 3","كمون 1 ملعقة صغيرة","أوريغانو 1 ملعقة صغيرة","برتقال 1 (للتقديم)","أرز وخضار كولارد","فاروفا أو فتات خبز محمص للتقديم (اختياري)"],"steps":["انقع الفاصوليا طوال الليل في ماء بارد، وصفها، واشطفها.","حمر لحم الخنزير والسجق ولحم الخنزير المقدد على دفعات في قدر كبير، ثم ضعها جانبا، مع إبقاء الدهن في القدر.","اقل البصل والثوم في القدر نفسه حتى يلينا، ثم أضف الكمون والأوريغانو.","أعد اللحوم إلى القدر، وأضف الفاصوليا وأوراق الغار وما يكفي من الماء لتغطيتها بمقدار 3 سم.","اتركه يغلي، وأزل الرغوة، ثم خفض إلى غليان هادئ جدا، مغطى جزئيا، لمدة ساعتين إلى ساعتين ونصف.","حرك من حين لآخر، مع إضافة ماء ساخن إذا لزم الأمر، حتى تصبح الفاصوليا كريمية واللحوم طرية.","تذوق وتبل بالملح والفلفل. فاللحوم تضيف ملحا، لذلك تذوق قبل إضافة المزيد.","قدمها في أوعية عميقة مع أرز أبيض وخضار كولارد مقلية وفاروفا وشرائح برتقال على الجانب."],"tip":"انقع الفاصوليا طوال الليل واتركها تغلي بلطف. فالفاصوليا المتسرعة تبقى صلبة، والغليان القوي يكسرها إلى عجين بدلا من فاصوليا كريمية.","notes":["الفاصوليا السوداء ضرورية. فهي تصبح كريمية وداكنة، وتلون اليخنة كلها. وفاصوليا الكلى تصنع طبقا مختلفا.","مزيج اللحوم يعطي الفيجوادا عمقها. استخدم ما تجده، لكن أدرج شيئا مدخنا، للنكهة الكلاسيكية.","أوراق الغار يجب أن تزال قبل التقديم. فهي تنكه اليخنة، لكنها ليست لطيفة للأكل.","شرائح البرتقال ليست تزيينا. فحموضتها تقطع غنى لحم الخنزير والفاصوليا، لذلك قدمها بسخاء."],"variations":["مع الدجاج: استبدل نصف لحم الخنزير بأفخاذ دجاج، تضاف لآخر 45 دقيقة، لنسخة أخف.","فيجوادا نباتية: استخدم الفطر والتوفو المدخن وفاصوليا إضافية مع مرق خضار، مع إبقاء التتبيل نفسه.","نسخة قدر الضغط: اطبخ الفاصوليا المنقوعة واللحوم تحت الضغط لمدة 35 دقيقة، ثم اتركها تغلي دون غطاء لمدة 15 دقيقة لتتكاثف."],"serving":"يكفي 8 أشخاص، كغداء عائلي طويل، مع أرز أبيض وخضار كولارد مقلية مع الثوم وفاروفا وشرائح برتقال في وسط الطاولة. وكل شخص يخدم نفسه فاصوليا ولحما فوق الأرز، ويضيف خضارا وفاروفا، ويأكل البرتقال بين اللقمات لينعش الحنك. وقدمها مع مشروب بارد وأبق القدر على الموقد، لأن الحصص الثانية متوقعة.","storage":"تبقى الفيجوادا في الثلاجة لمدة تصل إلى 4 أيام، وتتحسن النكهة طوال الليل. أعد تسخينها بلطف حتى تغلي، مع إضافة رشة من الماء إذا تكاثفت. وهي تتجمد جيدا جدا لمدة تصل إلى 3 أشهر، في حصص، وتذاب طوال الليل في الثلاجة. والأرز والخضار والفاروفا يجب أن تحضر طازجة، أو تحفظ بشكل منفصل لمدة يومين.","mistakes":["تخطي النقع طوال الليل. تأخذ الفاصوليا وقتا أطول بكثير وتطبخ بشكل غير متساو.","الغليان بقوة. تتكسر الفاصوليا وتصبح اليخنة عجينية، لذلك أبق غليانا هادئا.","إضافة الملح مبكرا جدا. يمكن للملح أن يقسي الفاصوليا، لذلك تبل جيدا في النهاية، بعد التذوق.","التقديم دون المرافقات. فالأرز والخضار والفاروفا والبرتقال جزء من الطبق، وليست إضافات."],"faq":[["هل يمكنني استخدام فاصوليا سوداء معلبة؟","نعم، عند الحاجة. أضفها لآخر 30 دقيقة مع اللحوم المحمرة، وقلل الماء، لكن اليخنة ستكون أقل غنى."],["هل الفيجوادا دهنية جدا؟","هي يخنة غنية، مصنوعة من لحم الخنزير والسجق. استخدم قطعا أقل دهنا وصف الدهن الزائد بعد التحمير إذا فضلت نسخة أخف."],["ما هي الفاروفا؟","دقيق كسافا محمص، غالبا مع البصل ولحم الخنزير المقدد، يرش فوق الفاصوليا والأرز. وفتات الخبز المحمص بديل مقبول."],["هل يمكنني تحضير الفيجوادا مسبقا؟","نعم، وهي أفضل في اليوم التالي. اطبخها بالكامل، وبردها، واحفظها في الثلاجة، وأعد تسخينها بلطف."]]},"gajarhalwa":{"intro":"غاجر كا حلوى هو الشتاء في وعاء، جزر أحمر يطبخ ببطء في الحليب حتى يختفي الحليب، ثم يقلى في السمن مع السكر وينهى بالخويا والهيل والمكسرات. وهو ليس حلوى سريعة، وهذه هي النقطة. فالطبخ الطويل واللطيف يحول الجزر المبشور إلى شيء طري وغني وعميق النكهة، دون اختصارات تعطي الطعم نفسه. استخدم الجزر الأحمر عندما تجده، وابشره ناعما، وأبق الحرارة هادئة. وقدمه دافئا، مع ملعقة من الخويا في الأعلى، واحفظ بعضه لليوم التالي، لأنه يصبح ألذ حينها.","ing":["جزر أحمر 1 كغ (مبشور)","حليب 1 لتر","سكر 1 كوب","سمن 4 ملاعق كبيرة","خويا 150 غراما","هيل 4","لوز / فستق"],"steps":["اغسل الجزر وقشره وابشره ناعما. فالبشر الناعم مهم، لأن القطع السميكة تأخذ وقتا أطول وتبقى خشنة.","ضع الجزر والحليب في قدر ثقيل. اتركه يغلي، ثم خفض إلى نار هادئة.","اطبخه دون غطاء على نار هادئة لمدة 35 إلى 45 دقيقة، مع التحريك كل بضع دقائق، حتى يجف الحليب تقريبا.","أضف السمن واقل الجزر، مع التحريك، لمدة 8 إلى 10 دقائق، حتى يصبح الخليط لامعا ويترك الجوانب.","أضف السكر واطبخه لمدة 8 إلى 10 دقائق إضافية، مع التحريك، حتى يذوب السكر وتتكاثف الحلوى مرة أخرى.","اسحق الهيل وأضفه مع الخويا. واطبخه لمدة 5 دقائق، مع التحريك، حتى تذوب الخويا في الحلوى.","تذوق وعدل. وإذا كان حلوا جدا، فإن عصرة ليمون ليست تقليدية، لذلك قدم حصصا أصغر مع شاي دون سكر بدلا من ذلك.","قدمه دافئا، مغطى بلوز وفستق مفرومين وقليل إضافي من الخويا."],"tip":"ابشر الجزر ناعما. فالجزر السميك يأخذ وقتا أطول في الطبخ وتبقى الحلوى خشنة، مهما حركت طويلا، لذلك خذ الوقت لتبشر جيدا في البداية.","notes":["الجزر الأحمر أحلى ويعطي اللون العميق. والجزر البرتقالي يعمل، لكن الحلوى تكون أشحب وتحتاج إلى قليل أكثر من السكر.","الحليب كامل الدسم يعطي نتيجة أغنى. والحليب قليل الدسم يأخذ وقتا أطول لينخفض ويكون طعمه أخف.","الخويا في النهاية تضيف غنى وقواما. ويستحق شراء خويا جيدة، أو تفتيت البانير كبديل عند الحاجة.","الهيل يجب أن يسحق طازجا. فالهيل المطحون مسبقا يفقد رائحته بسرعة."],"variations":["حلوى مسحوق الحليب: استبدل نصف الحليب بكوب واحد من مسحوق الحليب مخلوطا في الجزر، لنسخة أسرع وأغنى.","حلوى المكسرات: أضف كاجو مفروما وزبيبا مع الخويا، وحمص المكسرات في السمن أولا.","حلوى أقل حلاوة: قلل السكر إلى 3/4 كوب. فالحلوى ما زالت حلوة من الجزر، وتناسب التقديم مع الآيس كريم."],"serving":"يكفي 5 أشخاص، في أوعية صغيرة، دافئا، مع مكسرات مفرومة وملعقة من الخويا في الأعلى. وغاجر كا حلوى حلوى شتوية، تقدم بعد العشاء أو مع شاي العصر. ومغرفة من آيس كريم الفانيليا على حلوى دافئة تقديم حديث شائع، وتباين الساخن والبارد يعمل بشكل جميل. وأبق الحصص صغيرة، لأنها غنية.","storage":"بردها واحفظها في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى 4 أيام. أعد تسخينها في مقلاة على نار هادئة مع رشة من الحليب، مع التحريك، حتى تدفأ تماما. وهي تسخن جيدا أيضا في الميكروويف على دفعات قصيرة. وجمدها لمدة تصل إلى شهر واحد في حصص، وأذبها في الثلاجة، وأعد تسخينها مع قليل من الحليب. وأضف مكسرات طازجة عند التقديم، لأن المكسرات المخزنة تلين.","mistakes":["الطبخ على نار عالية. يلتصق الحليب ويحترق، وتصبح الحلوى محروقة الطعم.","إضافة السكر مبكرا جدا. يسحب الماء ويغلي الجزر بدلا من أن ينخفض، لذلك أضفه بعد أن يجف الحليب.","البشر السميك. تبقى الحلوى خيطية وخشنة، مهما طال طهيها.","تخطي مرحلة قلي السمن. وبدونها، يكون طعم الحلوى مسلوقا، وليس غنيا ولامعا."],"faq":[["هل يمكنني استخدام جزر برتقالي؟","نعم. الحلوى أشحب وأقل حلاوة قليلا، لذلك تذوق وأضف ملعقة إلى ملعقتين كبيرتين إضافيتين من السكر إذا لزم الأمر. والجزر الأحمر تقليدي لحلوى الشتاء."],["كيف أعرف أن الحليب انخفض بما يكفي؟","يبدو الخليط جافا، والجزر يتماسك معا، وترى السمن يبدأ في الانفصال عند الحواف عندما تحرك. وذلك هو وقت إضافة السمن والقلي."],["هل يمكنني تحضيرها دون خويا؟","نعم. ما زالت جيدة، فقط أقل غنى. أضف ملعقتين كبيرتين إضافيتين من السمن وملعقتين كبيرتين من مسحوق الحليب في النهاية، أو فتت بانيرا طريا."],["هل تقدم غاجر كا حلوى ساخنة أم باردة؟","الدافئة أفضل، مباشرة من القدر أو مسخنة بلطف. وحلوى الثلاجة الباردة متماسكة وأقل عطرا، لذلك دفئها قبل التقديم."]]},"gulabjamun":{"intro":"غلاب جامن هي الحلوى التي تنهي معظم الاحتفالات، طرية ودافئة ومغمورة في شراب معطر بالورد حتى تصبح ثقيلة به. والسر ليس قائمة طويلة من المكونات. بل خويا طازجة وطرية، وعجينة تعامل بلطف، وقلي على نار هادئة حتى ينضج الجامن تماما دون أن يغمق بسرعة، وشراب دافئ، وليس مغليا، عندما يدخل فيه. واستعجل أي جزء وسيصبح الجامن صلبا أو متشققا أو جافا من الداخل. وخذ وقتك، وسيتورم ويلين ويلمع. وقدمه دافئا، مع الشراب المسكوب فوقه، وشاهده يختفي.","ing":["خويا 250 غراما","دقيق 3 ملاعق كبيرة","مسحوق هيل 1/2 ملعقة صغيرة","سكر 2 كوب","ماء 2 كوب","ماء ورد 1 ملعقة صغيرة","قطرتان من الليمون","زيت / سمن للقلي"],"steps":["فتت الخويا واعجنها مع الدقيق والهيل حتى تتكون عجينة طرية وناعمة. ولا تبالغ في العجن، وإلا أصبح الجامن كثيفا.","غط العجينة واتركها ترتاح لمدة 15 دقيقة. ويجب أن تكون طرية بما يكفي لتلف دون أن تتشقق.","حضر الشراب بتسخين السكر والماء وعصير الليمون حتى يذوب السكر. واتركه يغلي على نار هادئة لمدة 5 دقائق، وأضف الهيل وماء الورد، وأبقه دافئا، وليس مغليا.","ادهن راحتيك بخفة بالسمن. ولف كرات صغيرة وناعمة، بحجم حبة جوز تقريبا، دون شقوق على السطح.","سخن الزيت أو السمن على نار هادئة إلى متوسطة هادئة. ويجب أن يكون الزيت دافئا بما يكفي ليصدر صوتا بلطف، وليس ساخنا بما يكفي ليتحمر فورا.","أضف الجامن على دفعات، مع التحريك بلطف بالملعقة حتى يتدحرج ويتحمر بالتساوي، لمدة 6 إلى 8 دقائق، حتى يصبح ذهبيا خفيفا.","ارفع الجامن وضعه مباشرة في الشراب الدافئ. وسيصدر صوتا خفيفا ويبدأ في التورم.","اتركه يرتاح لمدة ساعة على الأقل، مع قلبه مرة واحدة، حتى يشرب الجامن الشراب بالتساوي. وقدمه دافئا، مع الشراب المسكوب فوقه."],"tip":"يجب ألا تكون في الجامن شقوق. ادهن يديك بخفة بالسمن أثناء تشكيل الكرات. ويجب ألا يكون الشراب ساخنا جدا، وإلا سيتصلب الجامن بدلا من أن يمتص، ويجب ألا يكون باردا، وإلا لن يمتصه.","notes":["الخويا الطازجة والطرية تصنع جامنا طريا. والخويا الجافة والمتفتتة تحتاج إلى ملعقة من الحليب لتجمع العجينة.","الدقيق مادة رابطة فقط. والكثير من الدقيق يصنع جامنا صلبا، لذلك قسه ولا تضف المزيد لإصلاح عجينة لزجة، بل اتركها ترتاح بدلا من ذلك.","عصير الليمون في الشراب يمنعه من التبلور عندما يبرد، لذلك يبقى الشراب صافيا وناعما.","ماء الورد يضاف بعيدا عن النار، حتى تبقى رائحته مشرقة بدلا من أن تغلي وتختفي."],"variations":["كيسار جامن: انقع رشة من الزعفران في حليب دافئ، وأضفها إلى الشراب، وزينها بالفستق.","جامن محشو: اضغط قطعة صغيرة من خليط الفاكهة المجففة والمكسرات في وسط كل كرة قبل القلي.","جامن مع الآيس كريم: قدم الجامن الدافئ فوق آيس كريم الفانيليا، مع شراب دافئ مسكوب في الأعلى، لحلوى ساخنة وباردة."],"serving":"يكفي 6 أشخاص، مع 3 إلى 4 حبات جامن لكل شخص في أوعية صغيرة، مع كثير من الشراب. وقدمه دافئا، مزينا بفستق مفروم إذا أردت، وأبق شرابا إضافيا في إبريق لحصص ثانية. وغلاب جامن يناسب العيد وحفلات الزفاف وعشاءات، وأفضل ما يؤكل بملعقة، مباشرة من الوعاء. وكوب من الشاي بعده هو اللمسة الكلاسيكية.","storage":"احتفظ به في الشراب في وعاء مغطى في الثلاجة لمدة تصل إلى 4 أيام. أعد تسخينه بلطف في الشراب على نار هادئة، أو في الميكروويف لمدة 20 إلى 30 ثانية، حتى يدفأ، وليس يسخن. ولا تغله في الشراب، لأنه يتفكك. وجمد دون شراب لمدة تصل إلى شهر واحد، وأذبه في الثلاجة، ودفئه في شراب طازج قبل التقديم.","mistakes":["القلي على نار عالية. يغمق الخارج بسرعة ويبقى الداخل نيئا وكثيفا.","تشكيل كرات فيها شقوق. يدخل الشراب بشكل غير متساو ويتشقق الجامن أو يصبح خشنا.","وضع الجامن في شراب مغلي. يغلق السطح ويبقى صلبا من الداخل.","المبالغة في عجن العجينة. تصبح قاسية ويفقد الجامن طراوته."],"faq":[["لماذا غلاب جامن الخاص بي صلب؟","كانت العجينة معجونة أكثر من اللازم، أو استخدم دقيق كثير، أو كان الشراب ساخنا جدا. اعجن بلطف، وقس الدقيق، وأبق الشراب دافئا، وليس مغليا."],["هل يمكنني استخدام مسحوق الحليب بدلا من الخويا؟","نعم. اخلط كوبا واحدا من مسحوق الحليب مع ملعقتين كبيرتين من السمن و3 إلى 4 ملاعق كبيرة من الحليب الدافئ حتى تصبح عجينة طرية، ثم اتبع الخطوات نفسها. والقوام قريب، وإن كانت الخويا أطرى."],["لماذا تكسر الجامن في الشراب؟","لأنه قلي قليلا جدا، أو كانت العجينة طرية جدا، أو كان الشراب مغليا. اقله حتى يصبح ذهبيا خفيفا ومتماسكا، وأبق الشراب دافئا."],["هل يمكنني جعل الشراب أقل حلاوة؟","يمكنك تقليل السكر إلى 1½ كوب، لكن يجب أن يغطي الشراب الجامن. والشراب الرقيق جدا لا يمتص بالطريقة نفسها، لذلك لا تقله أكثر من ذلك."]]},"halwapuri":{"intro":"الحلوى بوري هو فطور يوم الأحد في لاهور، وفي كثير من البيوت هو حدث كامل، وليس مجرد وجبة. ثلاثة أشياء تصل معا، بوري منتفخ، وحلوى سميد طرية، وحمص متبل مع البطاطس، والمتعة في أخذ القليل من كل منها في لقمة واحدة. وكل جزء بسيط بمفرده، لكن التوقيت مهم. اقل البوري أخيرا، حتى يصل منتفخا وساخنا، وأبق الحلوى دافئة وطرية، ودع الحمص يغلي حتى تغطيه الماسالا. واطبخه في صباح بطيء، وكله معا، ولا تستعجل.","ing":["دقيق 2 كوب","سميد 1 كوب","سكر 1 كوب","سمن 1/2 كوب","حمص (مسلوق) 2 كوب","بطاطس 1","بصل","طماطم","غارام ماسالا","كركم","فلفل أحمر حار","هيل","لوز للتزيين"],"steps":["اعجن الدقيق مع الماء ورشة ملح حتى تصبح عجينة متماسكة وناعمة. غطها واتركها ترتاح لمدة 20 دقيقة.","اسلق الحمص إذا لم يكن مسلوقا من قبل، حتى يلين دون أن يصبح عجينا، واحتفظ بكوب واحد من ماء طهيه.","حمص السميد في السمن على نار هادئة، مع التحريك المستمر، حتى يتحول إلى الذهبي وتفوح منه رائحة الجوز، حوالي 8 إلى 10 دقائق.","أضف الماء الساخن والسكر بحذر، فسيغلي، وحرك حتى تتكاثف الحلوى، ثم أضف الهيل وغطه على نار هادئة لمدة 5 دقائق.","سخن الزيت، واقل البصل حتى يلين، وأضف الطماطم والبطاطس وغارام ماسالا والكركم والفلفل الأحمر الحار، واقل الماسالا جيدا.","أضف الحمص وماء طهيه، واتركه يغلي على نار هادئة لمدة 10 دقائق، واهرس بضع حبات حمص على الجانب لتكثيف المرق.","افرد قطع بوري صغيرة، لا تزيد سماكتها عن حافة عملة، واقلها بعمق في زيت ساخن، مع الضغط بلطف حتى ينتفخ كل واحد. وصفها على ورق.","قدم البوري والحلوى والحمص معا في طبق واحد، مع تزيين الحلوى باللوز."],"tip":"لا تستخدم الكثير من الدقيق أثناء فرد البوري، وإلا لن ينتفخ. وإذا كان الزيت ساخنا جيدا، فإن البوري ينتفخ فورا، لذلك اختبر بقطعة عجين صغيرة أولا، فيجب أن ترتفع في ثوان.","notes":["العجينة المتماسكة تصنع بوريا منتفخا. والعجينة الطرية تمتص الزيت وتبقى مسطحة، لذلك اعجنها متماسكة واتركها ترتاح جيدا.","السميد الناعم يعطي حلوى ناعمة. والسميد الخشن يحتاج إلى ماء أكثر وطهي أطول.","احتفظ بماء طهي الحمص. فهو يكثف المرق طبيعيا ويحمل النكهة.","الهيل يدخل إلى الحلوى في النهاية، حتى تبقى رائحته طازجة بدلا من أن تطبخ وتختفي."],"variations":["ألو كي تاركاري بدلا من الحمص: اطبخ البطاطس في الماسالا نفسها، واهرس نصفها، وقدمها كطبق جانبي مالح.","حلوى أقل حلاوة: قلل السكر إلى 3/4 كوب وأضف قليلا إضافيا من الهيل، لحلوى تناسب الحمص الحار بشكل أفضل.","بوري القمح الكامل: استخدم نصف دقيق قمح كامل ونصف دقيق عادي، واترك العجينة ترتاح أطول قليلا، وافردها أسمك قليلا."],"serving":"يكفي 4 أشخاص، مع 2 إلى 3 قطع بوري لكل شخص، وملعقة من الحلوى، ومغرفة سخية من الحمص في طبق واحد. وقدمه مع المخلل والبصل المقطع والليمون، والشاي على الجانب. والحلوى بوري فطور يجلس له، يؤكل ساخنا، مع الجميع على الطاولة معا. واصنع بوريا إضافيا، لأنه يختفي أسرع.","storage":"كل البوري طازجا، فهو لا يبقى جيدا. والحلوى تبقى في الثلاجة لمدة تصل إلى 3 أيام في وعاء محكم الإغلاق، وتسخن في مقلاة على نار هادئة مع رشة من الحليب أو الماء. والحمص يبقى لمدة تصل إلى 3 أيام في الثلاجة، ويسخن على الموقد حتى يغلي. ولا تحفظ الأطباق المجمعة، أبق الأجزاء الثلاثة منفصلة واجمعها عند التقديم.","mistakes":["فرد البوري سميكا جدا أو بدقيق جاف كثير. يبقى مسطحا وماضغا بدلا من أن ينتفخ.","تحميص السميد على نار عالية. يتحمر في بقع ويصبح طعمه محروقا، لذلك أبق الحرارة هادئة وحرك.","إضافة ماء بارد إلى سميد ساخن. يتكتل، لذلك استخدم ماء ساخنا وحرك فورا.","قلي البوري في زيت ليس ساخنا بما يكفي. يمتص الزيت ويصبح دهنيا."],"faq":[["لماذا لا ينتفخ البوري؟","كانت العجينة طرية جدا، أو كان البوري مفروذا سميكا جدا، أو لم يكن الزيت ساخنا بما يكفي. اعجنها متماسكة، وافردها رفيعة، واختبر الزيت أولا."],["هل يمكنني استخدام حمص معلب؟","نعم. صفه واشطفه، ثم اتركه يغلي في الماسالا لمدة 10 دقائق. وأضف قليلا من الماء الساخن، لأن الحمص المعلب ليس له ماء طهي."],["كم يجب أن تكون الحلوى حلوة؟","حلوى الحلوى بوري التقليدية حلوة جدا، لتوازن الحمص الحار. وإذا فضلت أقل حلاوة، قلل السكر، لكن لا تقطعه إلى النصف، وإلا تغير القوام."],["هل يمكنني تحضير الأجزاء مسبقا؟","نعم. حضر الحلوى والحمص في اليوم السابق واحفظهما في الثلاجة. واقل البوري طازجا في الصباح، لأن البوري المعاد تسخينه ليس جيدا أبدا."]]},"hummus":{"intro":"الحمص الجيد يتعلق كله بالقوام، حريري وخفيف ومخفوق، وليس حبيبيا أو ثقيلا أبدا. وهو يأتي من الشام، حيث يخلط الحمص والطحينة والليمون والثوم مع ماء مثلج حتى يتحول الغموس إلى شاحب وهش، ثم ينهى بزيت الزيتون والبابريكا وحمص كامل. والسر هو خلط الطحينة أولا، وحدها، حتى تصبح ناعمة تماما، واستخدام حمص دافئ، أو حمص أزيلت قشوره، لأكثر نتيجة نعومة. وقدمه كجزء من طبق مزة، مع خبز بيتا دافئ وزيتون وسلطة، ودع الجميع يغمسون ويشاركون.","ing":["حمص 400 غرام (مطهو, مصفى)","طحينة 120 غراما (محركة جيدا)","عصير ليمون 3 ملاعق كبيرة","ثوم 1 فص صغير","ماء مثلج 4 إلى 6 ملاعق كبيرة","زيت زيتون 2 ملعقة كبيرة (بالإضافة إلى المزيد للتقديم)","ملح 1 ملعقة صغيرة","كمون 1/2 ملعقة صغيرة (اختياري)","بابريكا وبقدونس للتقديم","خبز بيتا دافئ للتقديم"],"steps":["إذا استخدمت حمصا معلبا، دفئه في سائله لمدة 5 دقائق، وصفه، واحتفظ بقليل من السائل. وأزل القشور السائبة إذا كان لديك وقت.","اخلط الطحينة وعصير الليمون والثوم والملح لمدة دقيقتين حتى تصبح ناعمة جدا وشاحبة وهشة قليلا.","أضف الحمص الدافئ واخلط لمدة 3 إلى 4 دقائق، مع كشط الجوانب، حتى يصبح ناعما تماما.","أضف الماء المثلج ملعقة كبيرة في كل مرة، مع الخلط بعد كل واحدة، حتى يصبح الحمص خفيفا ومخفوقا وطريا بما يكفي للغمس.","تذوق وعدل الليمون والملح والثوم. ويجب أن يكون مشرقا ومالحا، بنكهة طحينة، وليس حادا.","ضعه بالملعقة في وعاء ضحل، ودوّر الأعلى بظهر الملعقة، ورش زيت الزيتون.","غطه ببضع حبات حمص كاملة ورشة بابريكا وبقدونس مفروم.","قدمه في درجة حرارة الغرفة مع بيتا دافئة وأعواد خضار وزيتون."],"tip":"اخلط الطحينة أولا، قبل الحمص. فالطحينة المخلوطة وحدها تصبح شاحبة وكريمية، وهذا ما يجعل الحمص حريريا.","notes":["جودة الطحينة أهم شيء. استخدم طحينة سائلة ومحركة جيدا مصنوعة من بذور سمسم مقشورة. والطحينة السميكة والجافة تصنع حمصا ثقيلا.","الماء المثلج يخفق الهواء في الحمص ويرخيه دون إضافة زيت. وأضفه ببطء، وإلا أصبح الحمص سائلا.","الثوم يجب أن يكون صغيرا وطازجا. ففص نيئ كبير واحد يمكن أن يطغى على الوعاء كله، لذلك ابدأ صغيرا.","الحمص الدافئ يخلط أنعم من البارد، لأن نشاه طري. وإذا استخدمت حمصا باردا، دفئه أولا."],"variations":["حمص الفلفل الأحمر المحمص: اخلط حبة فلفل أحمر محمصة واحدة، وقلل الليمون قليلا.","حمص الشمندر: اخلط حبة شمندر مطهوة صغيرة واحدة للون والحلاوة، وهي نسخة وردية جميلة.","حمص حار: أضف ملعقة صغيرة من الهريسة أو معجون الفلفل الحار مع الطحينة، وغطه بزيت الفلفل الحار."],"serving":"يكفي 6 أشخاص، كجزء من طبق مزة، مع بيتا دافئة وزيتون ومخللات وسلطة وأغماس أخرى. وقدم الحمص في وعاء عريض ضحل، مع زيت الزيتون متجمعا في الدوامة، ودع الجميع يمزقون البيتا ويغمسون. وهو ممتاز أيضا كدهن للسندويش، وقاعدة للخضار المحمصة، أو طبق جانبي مع لحم مشوي وفلافل.","storage":"يبقى الحمص في الثلاجة لمدة تصل إلى 4 أيام في وعاء محكم الإغلاق، مع طبقة رفيعة من زيت الزيتون في الأعلى. وأعده إلى درجة حرارة الغرفة قبل التقديم، وحركه جيدا. وهو يتجمد جيدا لمدة تصل إلى 3 أشهر، ويذاب طوال الليل في الثلاجة، ثم يخفق ناعما مرة أخرى. ولا تتركه في درجة حرارة الغرفة لأكثر من ساعتين.","mistakes":["خلط كل شيء دفعة واحدة. فالطحينة لا تصبح ناعمة أبدا، لذلك اخلطها أولا وحدها.","استخدام حمص بارد وجاف. يخلط حبيبيا، لذلك دفئه وأضف الماء المثلج ببطء.","إضافة الكثير من الثوم. فالثوم النيئ يصبح أقوى عندما يجلس الحمص، لذلك استخدم قليلا وتذوق.","التقديم مباشرة من الثلاجة. فالحمص البارد قاس وباهت، لذلك دعه يدفأ أولا."],"faq":[["هل يمكنني استخدام حمص مجفف؟","نعم. انقعه طوال الليل، واطبخه حتى يصبح طريا جدا مع رشة من بيكربونات الصودا، واستخدمه دافئا. وهو يعطي أنعم حمص."],["لماذا الحمص الخاص بي حبيبي؟","لم تخلط الطحينة أولا، أو كان الحمص باردا، أو تركت القشور. واخلط أطول وأضف ماء مثلجا."],["هل يمكنني تحضير الحمص دون طحينة؟","يمكنك، مع زيت زيتون إضافي وقليل من زيت السمسم، لكنه لن يكون بطعم الحمص الكلاسيكي. فالطحينة هي قلب الطبق."],["هل الحمص صحي؟","هو مصنوع من حمص وطحينة وليمون وزيت زيتون، دون أرقام مضافة هنا. والزيت والملح هما الجزءان اللذان يجب مراقبتهما، لذلك قدمه مع خضار وبيتا."]]},"karahi":{"intro":"كراهي الدجاج هو طعام الدابا في أفضل حالاته، يطبخ بسرعة في مقلاة عميقة، دون بصل ودون قائمة طويلة من التوابل تختبئ خلفها. تتفكك الطماطم الطازجة لتصبح ماسالا، ويضاف الزنجبيل والفلفل الأخضر الحار في النهاية، ويصبح الطبق كله جاهزا في حوالي 40 دقيقة. والحيلة هي الحرارة والتوقيت. أبق اللهب عاليا، ودع الطماطم تقوم بعملها، وأنه بالزنجبيل بينما الكراهي ما زالت تصدر صوتا. وكله مباشرة من القدر مع روتي أو نان ساخن، بينما الماسالا لامعة والدجاج طري.","ing":["دجاج 750 غراما","طماطم 4 كبيرة","معجون الزنجبيل والثوم 1 ملعقة كبيرة","فلفل أخضر حار 4","زنجبيل مقطع شرائح رفيعة","سمن / زيت 1/2 كوب","ملح","فلفل أحمر مجروش","غارام ماسالا","كزبرة طازجة"],"steps":["قطع الطماطم إلى أرباع وأبق الزنجبيل والفلفل الحار والكزبرة جاهزة. فالكراهي تتحرك بسرعة، لذلك يجب أن يكون كل شيء في متناول اليد.","سخن السمن في قدر على نار عالية. أضف الدجاج واقله لمدة 4 إلى 5 دقائق، مع التقليب المتكرر، حتى يتغير لون السطح.","أضف معجون الزنجبيل والثوم واقله لمدة دقيقة واحدة. أضف الطماطم وقليلا من الملح، وغطه، واطبخه لمدة 8 إلى 10 دقائق على نار متوسطة عالية.","اكشف الغطاء واهرس الطماطم اللينة بظهر الملعقة. واستمر في القلي حتى تتكاثف الماسالا ويرتفع الزيت إلى الأعلى.","أضف الفلفل الأحمر المجروش وتذوق الملح. وإذا بدت الماسالا جافة، أضف ملعقتين كبيرتين من الماء الساخن فقط، لا أكثر.","أضف نصف شرائح الزنجبيل الرفيعة وحبتين من الفلفل الأخضر الحار المقطع. واقله لمدة دقيقتين إضافيتين حتى تدخل نكهتهما إلى الماسالا.","رش غارام ماسالا، وغطه، واتركه 5 دقائق من الدم على نار هادئة. يجب أن يكون الدجاج مطهوا تماما وما زال طريا.","غطه بباقي الزنجبيل والفلفل الحار والكزبرة الطازجة. وقدمه فورا، مباشرة من القدر، مع الروتي أو النان."],"tip":"لا تضف الماء إلى الكراهي. فماء الطماطم وحده يكفي. أبق الحرارة عالية حتى يبقى الدجاج طريا وتكون الماسالا مقلية جيدا، وأضف الزنجبيل الطازج في النهاية، وليس في البداية.","notes":["استخدم طماطم ناضجة وطرية. فالطماطم الصلبة تأخذ وقتا أطول لتتفكك وتترك الماسالا مائية.","الدجاج بالعظم يعطي نكهة أكثر ويبقى طريا. وفخذ دون عظم يعمل أيضا، لكن اطبخه لمدة 3 إلى 4 دقائق أقل.","السمن يعطي نكهة الدابا. والزيت يعمل، لكن استخدم قليلا إضافيا من الزنجبيل في النهاية لرفعه.","شرائح الزنجبيل الطازجة الرفيعة هي تزيين ونكهة. ومسحوق الزنجبيل المجفف ليس بديلا هنا."],"variations":["كراهي لحم الضأن: استخدم 750 غراما من لحم الضأن، واطبخه مغطى لمدة 40 إلى 50 دقيقة حتى يلين، ثم اقل الماسالا على نار عالية كالمعتاد.","كراهي الفلفل الأخضر الحار: تخط الفلفل الأحمر، واستخدم 8 حبات فلفل أخضر حار، نصفها في الماسالا ونصفها للتزيين، لحرارة طازجة حادة.","كراهي الزبدة: أنه بملعقة كبيرة من الزبدة وملعقتين كبيرتين من الكريمة، مع التحريك بعيدا عن النار، لنسخة أغنى وأخف."],"serving":"يكفي 4 أشخاص مع الروتي أو النان، وسلطة بسيطة من البصل والليمون، ورايتا إذا أردت. وقدمه في القدر نفسه، مع شرائح ليمون على الجانب، وكله وهو ساخن. والماسالا مخصصة لتغمس بالخبز، لذلك أبق روتيا إضافيا جاهزا. ومشروب بارد أو لاسي يساعد مع الحرارة.","storage":"برده خلال ساعة واحدة واحفظه في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى يومين. أعد تسخينه في قدر على نار متوسطة، مغطى، مع ملعقة إلى ملعقتين كبيرتين من الماء، حتى يصبح ساخنا بالبخار. وأضف زنجبيلا طازجا وكزبرة بعد إعادة التسخين. والتجميد ممكن لمدة تصل إلى شهر واحد، لكن ماسالا الطماطم تلين عند الإذابة، لذلك الطازج أفضل.","mistakes":["إضافة الماء في البداية. تتحول الماسالا إلى كاري خفيف بدلا من كراهي سميكة ولامعة.","الطبخ على نار هادئة طوال الوقت. يتبخر الدجاج، وتبقى الطماطم قطعا، ولا تقلى الماسالا جيدا أبدا.","إضافة الزنجبيل في البداية فقط. يطبخ ويختفي، وتضيع اللمسة الطازجة.","الإفراط في طهي الدجاج دون عظم. فإنه يجف بسرعة على نار عالية، لذلك تحقق منه مبكرا."],"faq":[["لماذا لا يوجد ماسالا في الكراهي؟","لأن الطماطم لم تهرس وتقل لمدة كافية، أو لأن الماء أضيف. اهرس الطماطم جيدا واقلها حتى ينفصل الزيت."],["هل يمكنني تحضير الكراهي دون قدر؟","نعم. استخدم مقلاة عميقة وثقيلة أو مقلاة قلي. والمقلاة الرقيقة تحرق الماسالا، لذلك أبق الحرارة أقل قليلا وحرك أكثر."],["هل يفترض أن تحتوي الكراهي على بصل؟","كراهي الباكستانية التقليدية لا تحتوي على بصل. فماء الطماطم يصنع الماسالا. والبصل يصنع طبقا مختلفا، أقرب إلى الكاري."],["كيف أعرف أن الدجاج مطهو؟","تخرج العصارة صافية عند قطع قطعة عند أسمك جزء، ولا يعود اللحم ورديا. وإذا لم تكن متأكدا، اقطع أكبر قطعة للتحقق."]]},"lassi":{"intro":"لاسي المانجو هو الصيف في كوب، مانجو ناضج مخلوط مع زبادي بارد، وقليل من الحليب، وهيل، حتى يصبح سميكا وناعما وباردا بما يكفي ليبردك. ويستغرق 15 دقيقة، معظمها تقشير المانجو، ولا يحتاج إلى أي طهي على الإطلاق. وجودة المانجو تقرر كل شيء، لذلك اختر فاكهة تشم رائحة حلوة عند الساق، وتعطي قليلا عند الضغط عليها، وليس فيها بقع خضراء صلبة. وقدمه فورا، في أكواب مبردة، مع قليل من المانجو المقطع في الأعلى، واشربه بينما رغوة الخلاط ما زالت في الأعلى.","ing":["مانجو ناضج 2","زبادي 1½ كوب","حليب 1/2 كوب","سكر 2 ملعقة كبيرة (حسب الذوق)","مسحوق هيل 1/4 ملعقة صغيرة","مكعبات ثلج","نعناع للتزيين"],"steps":["برد الأكواب في الثلاجة لمدة 15 دقيقة، حتى يبقى اللاسي باردا بينما تشربه.","قشر المانجو، واقطع اللحم بعيدا عن النواة، وقطعه بشكل خشن. وتذوق قطعة وقرر كمية السكر التي تحتاجها.","ضع المانجو والزبادي والحليب والسكر والهيل في الخلاط. ولا تضف الثلج بعد.","اخلط لمدة 30 ثانية، وتوقف، واكشط الجوانب، واخلط لمدة 30 ثانية إضافية، حتى يصبح ناعما تماما.","أضف حفنة من مكعبات الثلج واخلط لمدة 15 إلى 20 ثانية إضافية، فقط حتى يتكسر الثلج ويصبح اللاسي سميكا وباردا.","تذوق وعدل. أضف قليلا إضافيا من السكر إذا كان المانجو حامضا، أو رشة من الحليب إذا كان سميكا جدا للسكب.","اسكبه في الأكواب المبردة فورا، مع ترك الرغوة في الأعلى.","زينه بمانجو مقطع وورقة نعناع، وقدمه فورا مع شفاطة أو ملعقة."],"tip":"كلما كان المانجو أحلى، قل السكر الذي تحتاجه. ولا تحضر اللاسي مسبقا. فالمخلوط طازجا أفضل، لأنه ينفصل ويفقد رغوته إذا بقي، ويذوب الثلج ويرققه.","notes":["استخدم مانجو ناضجا وحلوا مثل السندهري والتشونسا والألفونسو عندما يكون في الموسم. والمانجو الليفي يصنع لاسيا خيطيا، لذلك صفه إذا لزم الأمر.","الزبادي كامل الدسم يعطي لاسيا سميكا وكريميا. والزبادي قليل الدسم يعمل، لكن اللاسي أرق ويحتاج إلى حليب أقل.","الهيل يجب أن يكون نكهة خلفية، وليس النكهة الرئيسية. فربع ملعقة صغيرة يكفي لثلاثة أكواب.","برد كل شيء أولا. فالمانجو البارد والزبادي البارد والحليب البارد تعني حاجة أقل إلى الثلج، وتبقى النكهة قوية."],"variations":["لاسي المانجو والموز: أضف موزة ناضجة واحدة للاسي أسمك وأحلى يناسب الأطفال.","لاسي المانجو والورد: أضف ملعقة صغيرة من ماء الورد ورشة من الزعفران، وزينه ببتلات الورد.","لاسي نباتي: استخدم زبادي جوز الهند وحليب الشوفان، وحله بشراب القيقب أو السكر حسب الذوق."],"serving":"يكفي 3 أشخاص، في أكواب طويلة مبردة، مع مانجو مقطع ونعناع في الأعلى. ولاسي المانجو يناسب ظهيرات حارة، ووجبات حارة، وفطور عطلة نهاية أسبوع صيفية. وقدمه كمشروب مع الباراثا والمخلل، أو كحلوى خفيفة بعد كاري حار. وأبقه باردا حتى لحظة سكبه، واشربه طازجا.","storage":"اشربه طازجا لأفضل قوام. ويبقى اللاسي في برطمان محكم في الثلاجة لمدة تصل إلى يوم واحد، لكنه ينفصل، لذلك حركه أو رجه جيدا قبل التقديم، ولا تتوقع عودة الرغوة. ولا تجمد اللاسي، لأن الزبادي يصبح حبيبيا عند الإذابة. وإذا اضطررت لتحضيره مسبقا، اخلط المانجو والزبادي دون ثلج، واحفظه في الثلاجة، وأضف الثلج واخلط مرة أخرى قبل التقديم مباشرة.","mistakes":["استخدام مانجو غير ناضج. فلا كمية من السكر تصلح النكهة الحامضة والصلبة، لذلك انتظر فاكهة ناضجة.","المبالغة في الخلط مع الثلج. يصبح اللاسي مائيا ورغويا بطريقة رقيقة، بدلا من أن يكون سميكا وكريميا.","إضافة الكثير من الحليب في البداية. يرقق اللاسي قبل أن تتمكن من الحكم عليه، لذلك أضف الحليب قليلا في كل مرة.","تحضيره قبل ساعات. ينفصل، ويبهت اللون، وتتلاشى نكهة المانجو الطازجة."],"faq":[["هل يمكنني استخدام مانجو مجمد؟","نعم. أذبه إلى النصف، حتى يكون طريا بما يكفي للخلط لكنه ما زال باردا، وقلل الثلج إلى النصف. والمانجو المجمد يصنع لاسيا سميكا جدا، لذلك أضف الحليب رشة في كل مرة."],["هل لاسي المانجو صحي؟","هو مصنوع من فاكهة وزبادي، دون أرقام مضافة هنا. والسكر هو الجزء الذي يجب مراقبته، لذلك استخدم مانجو ناضجا وأضف أقل قدر من السكر كما تحتاج الفاكهة."],["هل يمكنني تحضير اللاسي دون خلاط؟","نعم، إذا كان المانجو طريا جدا. اهرس المانجو بشوكة، واخفق الزبادي والحليب، ومرره عبر مصفاة. وهو أقل نعومة، لكنه ما زال لذيذا."],["لماذا اللاسي الخاص بي خيطي؟","كان المانجو ليفيا. اخلط أطول، أو مرر اللاسي عبر مصفاة ناعمة قبل التقديم. وفي المرة القادمة، اختر صنفا من المانجو أقل ليفية."]]},"meatpie":{"intro":"فطيرة اللحم الأسترالية أيقونة، تؤكل باليد، وذهبية وتؤكل في مباريات كرة القدم والمخابز وطاولات المطبخ في كل أنحاء أستراليا. وداخل قاعدة عجينة قصيرة مقرمشة وغطاء عجينة منتفخة قشرية حشوة لحم بقر غنية، مطبوخة ببطء مع البصل والطماطم وصلصة ورسيسترشاير وقليل من الفيجيمايت للعمق، سميكة بما يكفي لتحافظ على شكلها عند تقطيع الفطيرة، لكنها عصيرية بما يكفي لتحتاج إلى صلصة طماطم في الأعلى. وحضر الحشوة مسبقا وبردها تماما، لأن الحشوة الدافئة تذيب العجينة، ثم اخبزها حتى يصبح الغطاء ذهبيا عميقا. وقدمها ساخنة، مع صلصة طماطم، وكلها بيديك، على الطريقة الأسترالية.","ing":["لحم بقر تشاك 700 غرام (مقطع صغيرا)","بصل 1","ثوم 2 فص","معجون طماطم 2 ملعقة كبيرة","مرق لحم بقر 400 مل","صلصة ورسيسترشاير 2 ملعقة كبيرة","فيجيمايت 1 ملعقة صغيرة","دقيق 2 ملعقة كبيرة","زعتر 1 ملعقة صغيرة","عجينة قصيرة للقواعد","عجينة منتفخة للأغطية","بيضة 1 (مخفوقة, للتلميع)","صلصة طماطم للتقديم","ملح وفلفل"],"steps":["حمر لحم البقر على دفعات في قدر ساخن، ثم ضعه جانبا. وحمر البصل والثوم في القدر نفسه.","أضف معجون الطماطم والدقيق، واطبخه لمدة دقيقة واحدة، ثم اسكب المرق، مع التحريك لرفع النكهة المحمرة.","أعد لحم البقر، وأضف الورسيسترشاير والفيجيمايت والزعتر، واتركه يغلي بلطف لمدة 60 إلى 75 دقيقة حتى يلين ويتكاثف.","برد الحشوة تماما، في الثلاجة إن أمكن. فالحشوة الدافئة ستذيب العجينة وتجعلها مبللة.","بطن صواني فطائر مدهونة أو صينية مافن بعجينة قصيرة، واملأها بخليط اللحم البارد، وادهن الحواف بالبيض.","غطها بأغطية عجينة منتفخة، واضغط الحواف للإغلاق، وقصها، واقطع ثقب بخار صغيرا في كل غطاء.","ادهنها ببيض مخفوق، واخبزها على 200 درجة مئوية لمدة 25 إلى 30 دقيقة، حتى تصبح ذهبية عميقة ومقرمشة.","اتركها ترتاح لمدة 5 دقائق، وارفعها من الصواني، وقدمها ساخنة مع صلصة الطماطم."],"tip":"برد الحشوة تماما قبل ملء العجينة. فحتى الحشوة الدافئة قليلا تلين العجينة وتمنعها من أن تصبح مقرمشة في الفرن.","notes":["لحم بقر تشاك يصبح طريا وغنيا مع الطهي البطيء. ولحم البقر الخالي من الدهن للطهي يجف، واللحم المفروم يصنع فطيرة مختلفة وأطرى.","الفيجيمايت يضيف عمقا مالحا يصعب تحديده لكنه أسترالي بلا شك. واستخدم قليلا فقط، وإلا سيطغى على الحشوة.","العجينة القصيرة للقاعدة تعطي بنية، والعجينة المنتفخة للغطاء تعطي قشرة. واستخدام العجينة المنتفخة لكليهما يجعل القاعدة مبللة.","غسل البيض يعطي اللمعان الذهبي. وادهنه قبل الخبز مباشرة، ولا تدعه يتجمع في ثقب البخار."],"variations":["مع الفطر: أضف فطرا مقطعا مع البصل، لنكهة إضافية وحشوة أخف.","فطيرة الدجاج: استخدم أفخاذ دجاج بالصلصة نفسها، مطبوخة لمدة 40 دقيقة، لنسخة دجاج.","فطيرة الجبن ولحم الخنزير المقدد: أضف جبنا مبشورا ولحم خنزير مقدد مطهو إلى الحشوة المبردة قبل الخبز."],"serving":"يكفي 6 أشخاص، كفطائر فردية، ساخنة من الفرن، مع صلصة طماطم في الأعلى وسلطة بسيطة أو بازلاء على الجانب. وفطائر اللحم طعام يؤكل باليد، لذلك قدمها على أطباق مع شوكة قريبة، لكن شجع الأكل باليد وهي ساخنة. وهي مثالية للغداء وللنزهات ولمشاهدة الرياضة، مع صلصة طماطم إضافية على الطاولة.","storage":"تبقى الفطائر المطبوخة في الثلاجة لمدة تصل إلى 3 أيام، مغطاة، وتسخن في الفرن على 180 درجة مئوية حتى تصبح ساخنة ومقرمشة، حوالي 15 دقيقة. وهي تتجمد جيدا لمدة تصل إلى 3 أشهر، مخبوزة أو غير مخبوزة، وتذاب طوال الليل في الثلاجة. والحشوة وحدها تبقى لمدة 3 أيام في الثلاجة وتتجمد لمدة 3 أشهر. ولا تستخدم الميكروويف للفطائر إذا أردت قشرة مقرمشة.","mistakes":["ملء العجينة وهي دافئة. تذوب العجينة وتصبح مبللة، لذلك برد الحشوة بالكامل.","عدم خبز القاعدة بما يكفي. يبقى القاع شاحبا وطريا، لذلك اخبز حتى يصبح الغطاء ذهبيا عميقا والقاعدة متماسكة.","نسيان ثقب البخار. يتراكم البخار وينفجر الغطاء، لذلك اقطع ثقبا صغيرا في كل فطيرة.","جعل الحشوة رقيقة جدا. تسيل عند التقطيع، لذلك اتركها تغلي حتى تصبح سميكة بما يكفي لتتجمع على ملعقة."],"faq":[["هل يمكنني استخدام عجينة جاهزة من المتجر؟","نعم. عجينة قصيرة وعجينة منتفخة بجودة جيدة تعملان جيدا، وتوفران الكثير من الوقت. وأبقهما باردتين حتى تستخدمهما."],["هل يمكنني تحضير فطيرة كبيرة واحدة بدلا من ذلك؟","نعم. استخدم طبق فطيرة 20 سم، وبطنه بعجينة قصيرة، واملأه، وغطه بعجينة منتفخة، واخبزه لمدة 40 إلى 45 دقيقة."],["ما فائدة الفيجيمايت؟","هو يضيف عمقا مالحا وخميريا للحشوة. وإذا لم تجده، استخدم قليلا إضافيا من صلصة ورسيسترشاير ورشة ملح."],["هل يمكنني تجميد فطائر اللحم؟","نعم، مخبوزة أو غير مخبوزة، لمدة تصل إلى 3 أشهر. واخبزها من المجمدة، مع إضافة 10 إلى 15 دقيقة، حتى تسخن تماما."]]},"moussaka":{"intro":"الموساكا هي الخبز الطبقي العظيم في اليونان، باذنجان طري وصلصة لحم مفروم بالطماطم والضأن أو البقر معطرة بالقرفة، وطبقة بشاميل سميكة في الأعلى تصبح ذهبية في الفرن. وتستغرق قليلا من الوقت، لأن كل طبقة تطبخ بشكل منفصل قبل تجميع الطبق، لكن هذا ما يعطيها بنيتها ونكهتها، وأفضل ما تصنع مسبقا وترتاح، حتى تتماسك الطبقات وتقطع بنظافة. وقدمها دافئة، في مربعات، مع سلطة بسيطة، ولا تستعجل وقت الراحة. وهو طبق يوم أحد، سخي ومريح، ويطعم طاولة بسعادة.","ing":["باذنجان 2 كبير (مقطع)","بطاطس 3 (مقطعة, اختياري)","لحم ضأن أو بقر مفروم 600 غرام","بصل 1","ثوم 3 فصوص","طماطم 400 غرام (مفرومة)","معجون طماطم 2 ملعقة كبيرة","قرفة 1 ملعقة صغيرة","أوريغانو 1 ملعقة صغيرة","جوزة الطيب","حليب 500 مل","زبدة 50 غراما","دقيق 50 غراما","بيض 2","جبن 80 غراما (مبشور)","كيفالوتيري أو بارميزان"],"steps":["ملح شرائح الباذنجان واتركها ترتاح لمدة 30 دقيقة، ثم جففها بالتربيت واقلها أو حمصها حتى تصبح ذهبية وطرية. وضعها جانبا.","اسلق أو حمص شرائح البطاطس حتى تصبح طرية فقط، إذا استخدمتها، وضعها جانبا.","اقل البصل والثوم حتى يلينا، وأضف اللحم المفروم، وحمره جيدا، مع تفتيته.","أضف معجون الطماطم والطماطم المفرومة والقرفة والأوريغانو والتتبيل، واتركها تغلي على نار هادئة لمدة 20 دقيقة حتى تتكاثف.","حضر البشاميل بإذابة الزبدة، وتحريك الدقيق فيها، وخفق الحليب الدافئ حتى يصبح سميكا وناعما. وبرده قليلا، ثم اخفق البيض ونصف الجبن فيه.","رتب البطاطس، ثم الباذنجان، ثم صلصة اللحم المفروم في طبق خبز مدهون بالزبدة، وكرر مرة واحدة، وأنه بالبشاميل.","انثر باقي الجبن وقليلا من جوزة الطيب، واخبزه على 180 درجة مئوية لمدة 40 إلى 45 دقيقة حتى يصبح ذهبيا ويغلي.","اتركه يرتاح لمدة 20 دقيقة قبل التقطيع، حتى تتماسك الطبقات، وقدمه دافئا مع السلطة."],"tip":"اترك الموساكا ترتاح قبل التقطيع. فساخنة من الفرن تتفكك، ومرتاحة تقطع إلى طبقات نظيفة وجميلة.","notes":["تمليح الباذنجان يسحب الماء المر ويمنعه من امتصاص الكثير من الزيت. وجففه بالتربيت قبل القلي.","القرفة هي التوابل المميزة في صلصة اللحم المفروم اليونانية. استخدمها بخفة، حتى تدفئ الصلصة دون أن يكون طعمها حلوا.","البشاميل يجب أن يكون سميكا بما يكفي ليجلس في الأعلى. وإذا كان رقيقا، يغرق في اللحم المفروم، لذلك اطبخه حتى يغطي الملعقة.","ابشر الجبن ناعما حتى يذوب بالتساوي في البشاميل ويتحمر جيدا في الأعلى."],"variations":["موساكا نباتية: استبدل اللحم المفروم بالعدس والفطر، مع إبقاء التوابل والبشاميل نفسها.","مع الكوسا: أضف طبقة من شرائح الكوسا المحمصة مع الباذنجان، لخضار إضافية.","نسخة أخف: حمص الباذنجان بدلا من قليه، واستخدم حليبا شبه منزوع الدسم للبشاميل."],"serving":"يكفي 6 أشخاص، في مربعات سخية، مع سلطة يونانية بسيطة من الطماطم والخيار والبصل والزيتون، وخبز مقرمش على الجانب. وقدمها دافئة، وليست ساخنة جدا، حتى تستقر النكهات وتتماسك الطبقات. والموساكا طبق مشاركة، لذلك أحضر طبق الخبز إلى الطاولة، وقدمها مع سلطة وخبز إضافيين لمن يريد المزيد.","storage":"تبقى الموساكا في الثلاجة لمدة تصل إلى 3 أيام، مغطاة، وتسخن جيدا في الفرن على 160 درجة مئوية حتى تسخن تماما. وهي تتجمد جيدا لمدة تصل إلى 3 أشهر، في حصص، وتذاب طوال الليل في الثلاجة. أعد تسخينها مغطاة بورق قصدير حتى لا يتحمر الأعلى أكثر من اللازم. ولا تستخدم الميكروويف لطبق كامل، فالبشاميل يمكن أن ينفصل.","mistakes":["تخطي تمليح الباذنجان. يبقى مرا ويمتص الزيت، مما يجعل الخبز دهنيا.","تحضير بشاميل رقيق. يغرق ولا تتماسك الطبقة العلوية ذهبية أبدا.","التقطيع مبكرا جدا. تنزلق الطبقات، لذلك اتركها ترتاح لمدة 20 دقيقة على الأقل.","عدم طهي صلصة اللحم المفروم جيدا. فالصلصة المائية تجعل الخبز مبللا، لذلك اتركها تغلي حتى تتكاثف."],"faq":[["هل يمكنني تحضير الموساكا مسبقا؟","نعم، وأفضل أن تصنع مسبقا. اجمعها، واحفظها في الثلاجة لمدة تصل إلى يوم واحد، واخبزها عند الحاجة، مع إضافة 10 دقائق."],["هل يمكنني استخدام لحم البقر بدلا من الضأن؟","نعم. لحم البقر يصنع موساكا أخف. ولحم الضأن تقليدي وأغنى، لذلك اختر ما تفضله."],["هل الموساكا خالية من الغلوتين؟","ليست كما هي مكتوبة، بسبب الدقيق في البشاميل. استخدم خليط دقيق خال من الغلوتين للبشاميل، وتحقق من مرقك."],["لماذا البشاميل الخاص بي متكتل؟","أضيف الحليب بسرعة كبيرة، أو لم يطبخ الدقيق. اخفق باستمرار، وأضف حليبا دافئا ببطء، واطبخ حتى يصبح ناعما."]]},"nihari":{"intro":"النهاري طعام بطيء بأصدق معنى، وهو يخنة عطلة نهاية الأسبوع التي تكافئ الصبر بلحم طري جدا يترك العظم ومرق يغطي الملعقة. وفي هذه النسخة يطبخ لحم ساق البقر بلطف لمدة ساعتين تقريبا حتى تلين الأنسجة الضامة وتتعمق الماسالا في اللون والنكهة. وخليط الدقيق في النهاية هو ما يعطي النهاري قوامه السميك اللامع الشهير، لذلك يجب أن يضاف ببطء وأن يحرك جيدا. قدمه ساخنا يغلي مع خبز نان طازج والتزيين الكلاسيكي، وأبق ليمونا إضافيا على الطاولة.","ing":["لحم بقر (ساق) 1 كغ","بهارات نهاري 4 ملاعق كبيرة","دقيق 3 ملاعق كبيرة","معجون الزنجبيل والثوم 2 ملعقة كبيرة","بصل 1","سمن / زيت 1/2 كوب","زنجبيل","فلفل أخضر حار","ليمون (للتزيين)","كزبرة طازجة"],"steps":["سخن السمن، وحمر البصل المقطع تحميرا خفيفا دون أن يحترق، وأضف معجون الزنجبيل والثوم، واقله لمدة دقيقة واحدة حتى تذهب الرائحة النيئة.","أضف اللحم وبهارات النهاري واقله على نار متوسطة عالية لمدة 8 إلى 10 دقائق، حتى يتغير لون اللحم وتغطي الماسالا كل قطعة.","أضف ما يكفي من الماء الساخن لتغطية اللحم بحوالي بوصتين، واتركه يغلي، وأزل أي رغوة.","غط القدر واطبخه على نار هادئة لمدة ساعتين. وحركه بين الحين والآخر، وأضف ماء ساخنا إذا انخفض المستوى عن اللحم.","تحقق من اللحم. يجب أن يتفتت بالشوكة ويترك العظم بسهولة. وإذا كان ما زال متماسكا، اطبخه لمدة 20 إلى 30 دقيقة إضافية.","اخلط الدقيق مع كوب واحد من الماء البارد حتى يصبح ناعما تماما، دون تكتلات. واسكبه في خيط رفيع مع تحريك القدر.","اتركه يغلي على نار هادئة لمدة 10 إلى 15 دقيقة، مع التحريك المتكرر، حتى يصبح المرق سميكا ولامعا ويغطي ظهر الملعقة.","اتركه يرتاح لمدة 10 دقائق، وتذوق الملح، وقدمه مع النان، مزينا بالزنجبيل والفلفل الأخضر الحار والليمون والكزبرة."],"tip":"لا تبق المرق خفيفا. فالنهاري معروف بمرقه السميك اللامع. أضف الدقيق ببطء حتى لا تتكون تكتلات، وحرك باستمرار أثناء إضافته.","notes":["الساق، بالعظم والأنسجة الضامة، مثالية للنهاري. فهي تعطي قواما للمرق. ولحم البقر للطهي دون عظم يعمل أيضا، لكن المرق يكون أقل غنى.","بهارات النهاري تختلف في القوة باختلاف العلامة التجارية. استخدم الكمية المذكورة في المرة الأولى، وعدل في المرة القادمة.","السمن يعطي النكهة التقليدية. والزيت يعمل أيضا، ونصف سمن ونصف زيت حل وسط جيد.","الدقيق موجود للسماكة فقط. لا تضف المزيد، لأنه يضعف التوابل."],"variations":["نهاري لحم الضأن: استخدم الطريقة نفسها واطبخه لمدة ساعة و30 دقيقة تقريبا، مع التحقق مبكرا، لأن لحم الضأن يلين بسرعة أكبر.","نهاري الدجاج: استخدم دجاجا بالعظم، واطبخه لمدة 35 إلى 40 دقيقة، وأضف خليط الدقيق في وقت أبكر، وتوقع مرقا أخف.","أكثر حرارة: أضف فلفلا أخضر حارا إضافيا عند التقديم، وليس أثناء الطبخ، حتى تبقى الحرارة طازجة."],"serving":"يكفي 5 أشخاص مع النان وأوعية صغيرة من التزيين على الطاولة، حتى يتمكن كل شخص من إضافة الزنجبيل والفلفل الحار والليمون والكزبرة حسب ذوقه. والنهاري تقليديا طبق فطور أو غداء عطلة نهاية الأسبوع، يقدم في أوعية عميقة مع كثير من المرق المسكوب فوق اللحم. أبق النان دافئا وأحضر القدر إلى الطاولة وهو ما زال يغلي.","storage":"برده واحفظه في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى 3 أيام. ويصبح المرق أكثر سماكة عندما يبرد. أعد تسخينه بلطف على نار هادئة مع رشة من الماء الساخن، مع التحريك حتى يصبح ساخنا بالبخار في كل أجزائه. جمده لمدة تصل إلى شهرين، وأذبه طوال الليل في الثلاجة، وأضف التزيين طازجا عند التقديم فقط.","mistakes":["الطبخ على نار عالية. يقسو اللحم وينخفض المرق بسرعة كبيرة.","إضافة الدقيق جافا أو دفعة واحدة. تتكون تكتلات ولا يمكن تحريكها بسهولة.","التقصير في وقت الطبخ. يبقى اللحم ماضغا بدلا من أن يسقط عن العظم.","التقديم مع نان بارد ودون تزيين. تبدو النكهة باهتة بدونهما."],"faq":[["لماذا مرق النهاري خفيف؟","كان الدقيق قليلا جدا، أو كان الغليان بعد إضافته قصيرا جدا. اتركه يغلي لمدة 10 إلى 15 دقيقة مع التحريك. وإذا لزم الأمر، أضف ملعقة كبيرة إضافية من الدقيق مذابة في الماء."],["هل يمكنني استخدام قدر الضغط؟","نعم. اطبخ اللحم والماسالا لمدة 25 إلى 30 دقيقة بعد الوصول إلى الضغط، ثم أكمل في قدر مفتوح مع خليط الدقيق. اتبع تعليمات قدرك من أجل السلامة."],["هل النهاري حار جدا؟","الماسالا تعطي دفئا، وليس حرارة حارقة. والفلفل الحار الطازج عند التقديم يتيح لكل شخص اختيار مدى حرارة وعائه."],["هل يمكنني تحضيره قبل يوم؟","نعم. تتحسن النكهة طوال الليل في الثلاجة. أعد تسخينه بلطف، وأضف قليلا من الماء الساخن إذا كان سميكا جدا، وأضف التزيين طازجا."]]},"padthai":{"intro":"باد تاي هو أشهر طبق نودلز في تايلاند، وسحره هو التوازن، حلو وحامض ومالح وقليل من الحرارة، كل ذلك في مقلاة واحدة ساخنة. والصلصة تصنع من التمر الهندي وصلصة السمك وسكر النخيل والفلفل الحار، وتغطي نودلز الأرز المنقوعة، وليست المسلوقة، حتى تبقى مرنة بدلا من أن تصبح طرية. ويضاف الروبيان والبيض وبراعم الفاصوليا والثوم المعمر بسرعة، على نار عالية، وينهى الطبق بفول سوداني مجروش وليمون وبراعم إضافية على الجانب. وجهز كل شيء قبل أن تبدأ، لأنه بمجرد أن تسخن المقلاة، يستغرق الطبخ بضع دقائق فقط، وتلك السرعة هي ما يمنع النودلز من أن تصبح عجينية.","ing":["نودلز أرز مسطحة 250 غراما","روبيان 300 غرام (مقشر)","بيض 2 (مخفوق قليلا)","معجون تمر هندي 3 ملاعق كبيرة","صلصة سمك 3 ملاعق كبيرة","سكر نخيل أو سكر بني 3 ملاعق كبيرة","ثوم 3 فصوص","رقائق فلفل حار 1 ملعقة صغيرة","براعم فاصوليا 2 كوب","ثوم معمر أو بصل أخضر","فول سوداني محمص 4 ملاعق كبيرة (مجروش)","ليمون 1"],"steps":["انقع نودلز الأرز في ماء دافئ لمدة 20 إلى 30 دقيقة حتى تصبح مرنة لكنها ما زالت متماسكة، ثم صفها جيدا.","اخلط التمر الهندي وصلصة السمك والسكر ورقائق الفلفل الحار في صلصة، وتذوقها. ويجب أن تكون حلوة وحامضة ومالحة في آن واحد.","سخن الزيت في مقلاة على نار عالية، واقل الثوم لمدة 20 ثانية، ثم أضف الروبيان واطبخه لمدة دقيقتين حتى يصبح ورديا فقط.","ادفع الروبيان إلى جانب واحد، واسكب البيض، واخفقه بلطف حتى يتماسك فقط، ثم اخلطه مع الروبيان.","أضف النودلز المصفاة والصلصة، وقلب باستمرار لمدة 2 إلى 3 دقائق حتى تصبح النودلز طرية وتمتص الصلصة.","أضف نصف براعم الفاصوليا والثوم المعمر، وقلب لمدة 30 ثانية، وأبعد المقلاة عن النار.","قسم بين الأطباق، وغطها بباقي البراعم والفول السوداني المجروش والبصل الأخضر.","قدمه فورا مع شرائح الليمون ورقائق فلفل حار إضافية وصلصة سمك على الجانب، ليعدل كل شخص خاصته."],"tip":"انقع النودلز، ولا تسلقها. فالنودلز المسلوقة تطبخ أكثر من اللازم في المقلاة وتصبح طرية ولزجة.","notes":["معجون التمر الهندي يعطي النكهة الحامضة التي تميز باد تاي. وإذا كان سميكا جدا، خففه بقليل من الماء الدافئ قبل خلط الصلصة.","سكر النخيل يذوب في حلاوة تشبه الكراميل. والسكر البني يعمل جيدا، لكن السكر الأبيض أحاد، لذلك استخدم قليلا أقل.","صلصة السمك مالحة ونفاذة. أضفها إلى الصلصة، وليس مباشرة إلى المقلاة، حتى تمتزج بالتساوي.","نودلز الأرز المسطحة تختلف في السماكة. والنودلز الأرق تنقع أسرع، لذلك تحقق منها بعد 15 دقيقة وصفها وهي ما زالت متماسكة."],"variations":["باد تاي بالدجاج: استبدل الروبيان بدجاج مقطع شرائح رفيعة، يطبخ تماما قبل أن يدخل البيض.","باد تاي بالتوفو: استخدم توفو متماسكا، مقليا حتى يصبح ذهبيا أولا، لنسخة نباتية، وتأكد من أن بديل صلصة السمك يناسبك.","خضار إضافية: أضف جزرا مبشورا وملفوفا مبشورا مع النودلز، لمزيد من القرمشة واللون."],"serving":"يكفي 4 أشخاص، على أطباق دافئة، مع شرائح ليمون وفول سوداني مجروش وبراعم فاصوليا إضافية ورقائق فلفل حار على الطاولة. وباد تاي طبق طعام شارع، لذلك قدمه ساخنا وبشكل عادي، مع عصر الجميع الليمون فوق أطباقهم وإضافة المزيد من الفول السوداني أو الحرارة كما يحبون. وسلطة خيار خفيفة على الجانب منعشة، لكن أبق التركيز على النودلز.","storage":"باد تاي يؤكل طازجا أفضل، مباشرة من المقلاة. والبقايا تبقى في الثلاجة لمدة تصل إلى يوم واحد، وتسخن في مقلاة ساخنة مع رشة من الماء، مع التقليب المستمر. وتلين النودلز عند إعادة التسخين، لذلك لا تتوقع القوام نفسه. ولا تجمده. والصلصة وحدها تبقى في الثلاجة لمدة تصل إلى أسبوع واحد.","mistakes":["الإفراط في طهي النودلز. يجب أن تكون متماسكة عند تصفيتها، لأنها تكمل طهيها في الصلصة.","استخدام مقلاة ليست ساخنة بما يكفي. تتبخر النودلز وتلتصق، لذلك سخن المقلاة حتى تبدأ في التدخين فقط.","إضافة كل البراعم مبكرا جدا. تذبل وتصبح طرية، لذلك أضف نصفها في النهاية وأبق النصف الآخر نيئا للتزيين.","نسيان تذوق الصلصة. وازنها قبل الطبخ، لأنك لا تستطيع إصلاح الحلو والحامض والمالح بمجرد دخول النودلز."],"faq":[["هل يمكنني تحضير باد تاي دون صلصة سمك؟","نعم، استخدم صلصة الصويا مع رشة ملح، أو صلصة سمك نباتية. والنكهة مختلفة، لكن توازن الحلو والحامض يبقى."],["ماذا لو التصقت النودلز معا؟","لأنها نقعت طويلا جدا أو لم تكن المقلاة ساخنة بما يكفي. وصفها جيدا، وقلبها مع قليل من الزيت، واطبخها في مقلاة أسخن في المرة القادمة."],["هل يمكنني استخدام روبيان مجفف؟","نعم. انقع ملعقتين كبيرتين من الروبيان المجفف وأضفه مع الثوم. وهو يضيف عمقا مالحا تقليديا."],["هل باد تاي خال من الغلوتين؟","نودلز الأرز خالية من الغلوتين طبيعيا، لكن صلصة السمك ومعجون التمر الهندي يمكن أن يحتويان على إضافات، لذلك تحقق من الملصقات."]]},"paella":{"intro":"الباييا تأتي من فالنسيا في إسبانيا، حيث تطبخ في الهواء الطلق في مقلاة واسعة وضحلة، والأرز، وليس المأكولات البحرية، هو النجم الحقيقي. والزعفران يعطيها اللون الذهبي، ومرق جيد يعطيها النكهة، وآخر بضع دقائق من الطبخ، دون إزعاج، تصنع السوكارات، وهي طبقة الأرز المقرمشة المحمرة في القاع التي يتقاتل عليها الجميع. واستخدم أرز بومبا قصير الحبة إذا استطعت، وافرده في طبقة متساوية، وقاوم التقليب بمجرد دخول المرق. وقدمها في المقلاة، في وسط الطاولة، مع شرائح الليمون، ودع الجميع يأكلون معا.","ing":["أرز بومبا أو قصير الحبة 400 غرام","روبيان 300 غرام","بلح البحر 300 غرام (منظف)","حلقات حبار 200 غرام (اختياري)","مرق دجاج أو سمك 1 لتر (ساخن)","زعفران 1 رشة كبيرة","بصل 1","فلفل أحمر 1","ثوم 3 فصوص","طماطم 2 (مبشورة)","بابريكا مدخنة 1 ملعقة صغيرة","زيت زيتون 4 ملاعق كبيرة","ليمون 1","بازلاء 100 غرام"],"steps":["انقع الزعفران في 3 ملاعق كبيرة من المرق الساخن لمدة 10 دقائق، وأبق باقي المرق ساخنا.","سخن زيت الزيتون في مقلاة باييا واسعة، واقل البصل والفلفل لمدة 6 دقائق حتى يلينا، ثم أضف الثوم والبابريكا.","أضف الطماطم المبشورة واطبخها لمدة 4 دقائق حتى تغمق وتتكاثف.","أضف الأرز وحركه لمدة دقيقة لتغطيته بالسوفريتو، ثم افرده في طبقة متساوية.","اسكب المرق الساخن وسائل الزعفران، وتبل بالملح، واتركه يغلي غليانا هادئا. ولا تحرك من هذه النقطة.","اطبخه على نار متوسطة لمدة 15 دقيقة، ثم رتب المأكولات البحرية والبازلاء في الأعلى، مع الضغط عليها بخفة في الأرز.","خفض الحرارة، وغطه بشكل فضفاض بورق قصدير، واطبخه لمدة 10 دقائق إضافية، حتى يصبح الأرز طريا وينفتح بلح البحر.","اترك المقلاة مغطاة ترتاح لمدة 5 دقائق، ثم قدمها في المقلاة مع شرائح الليمون، واستمع لصوت طقطقة السوكارات."],"tip":"لا تحرك الأرز بعد دخول المرق. فالتقليب يطلق النشا ويجعل الأرز لزجا، ويمنع السوكارات من التكون.","notes":["أرز بومبا يمتص الكثير من السائل ويبقى منفصلا. وأرز طويل الحبة يصبح عجينيا في الباييا، لذلك استخدم أرزا قصير الحبة إذا لم يتوفر بومبا.","أبق المرق ساخنا. فالمرق البارد يبرد المقلاة ويطبخ الأرز بشكل غير متساو.","البابريكا المدخنة تعطي نكهة دافئة ومدخنة. والبابريكا الحلوة تعمل، لكن البابريكا الحارة يمكن أن تطغى على الزعفران.","الزعفران يجب أن ينقع قبل الاستخدام، حتى ينتشر لونه ورائحته بالتساوي في الأرز."],"variations":["باييا الدجاج والتشوريزو: أضف دجاجا محمرا وتشوريزو مقطعا مع السوفريتو، واستخدم مرق دجاج.","باييا الخضار: استخدم مرق خضار وخرشوفا وفاصوليا خضراء وفاصوليا زبدة، مع طريقة أرز الزعفران نفسها.","باييا مشكلة: اجمع الدجاج والروبيان وبلح البحر، مع إضافة الدجاج مبكرا والمأكولات البحرية متأخرا، كما في الطريقة الرئيسية."],"serving":"يكفي 6 أشخاص، تقدم في المقلاة في وسط الطاولة، مع شرائح ليمون وسلطة خضراء على الجانب. وكل شخص يأخذ حصة من الحافة إلى الداخل، حتى يحصل الجميع على بعض الطبقة السفلية المقرمشة. والباييا طبق مشاركة، لذلك ضع ليمونا إضافيا وخبزا مقرمشا وأيولي إذا أردت، ولا تقدمها على أطباق فردية في المطبخ.","storage":"الباييا تؤكل طازجة أفضل، مباشرة من المقلاة. والبقايا تبقى في الثلاجة لمدة تصل إلى يومين، وتسخن في مقلاة ساخنة مع رشة من المرق، مغطاة، حتى تصبح ساخنة بالبخار. ولن يكون الأرز مقرمشا كما كان، ويجب ألا تسخن المأكولات البحرية طويلا. ولا تجمد الباييا مع المحار، فالقوام يعاني. والسوكارات موجودة فقط في اليوم نفسه.","mistakes":["تقليب الأرز. يصبح لزجا ولا تتقرمش القاع أبدا.","استخدام الأرز الخطأ. فالأرز طويل الحبة وأرز الريزوتو يعطيان القوام الخطأ.","إضافة مرق بارد. يتوقف الطبخ ويبدأ، ويطبخ الأرز بشكل غير متساو.","الإفراط في تحميل المقلاة. فالكثير من المأكولات البحرية في الأعلى يبخر الأرز بدلا من تركه يتحمر، لذلك أبق الطبقة متساوية وليست عميقة جدا."],"faq":[["هل أحتاج إلى مقلاة باييا؟","مقلاة واسعة وضحلة تعمل، طالما أن طبقة الأرز رفيعة. والقدر العميق يجعل الأرز سميكا جدا ويتبخر بدلا من أن يتحمر."],["هل يمكنني تحضير الباييا دون زعفران؟","يمكنك، مع رشة من الكركم للون، لكن النكهة مختلفة. والزعفران هو النكهة المميزة للباييا."],["كيف أعرف أن الأرز ناضج؟","تذوقه. يجب أن يكون طريا مع قضمة خفيفة، ويجب أن يمتص السائل. والراحة لمدة 5 دقائق تكمله."],["لماذا الباييا الخاصة بي عجينية؟","كان الأرز مقلبا، أو كان المرق باردا، أو كانت الحرارة منخفضة جدا. أبق الأرز دون إزعاج والحرارة ثابتة."]]},"pekingduck":{"intro":"بطة بكين هي من أعظم أطباق الاحتفال في الصين، مشهورة بجلد مقرمش جدا يتكسر، ولحم يبقى طريا تحته. والسر هو تجفيف الجلد وتزجيجه قبل التحميص، حتى يذوب الدهن ويتحول الجلد إلى لون ذهبي أحمر مطلي عميق. وهذه النسخة المنزلية تستخدم راحة طوال الليل في الثلاجة لتجفيف الجلد، وتزجيجا بسيطا من المالتوز والخل، وفرنا ساخنا، يتبعه راحة قبل التقطيع. وقدمها بالطريقة التقليدية، في فطائر الماندرين الرقيقة مع صلصة الهويسن والبصل الأخضر والخيار، ودع الجميع يجمعون خاصتهم. وهو مشروع، وليس عشاء يوم عمل، ويستحق كل دقيقة.","ing":["بطة كاملة 2 إلى 2.5 كغ","مالتوز أو عسل 3 ملاعق كبيرة","خل أرز 2 ملعقة كبيرة","نبيذ شاوشينغ 2 ملعقة كبيرة","بهارات خمسة 1 ملعقة صغيرة","ملح 1 ملعقة كبيرة","ماء مغلي للسلق","فطائر ماندرين 12","صلصة هويسن 120 مل","بصل أخضر 4","خيار 1","زنجبيل وثوم للتجويف (اختياري)"],"steps":["نظف البطة، وجففها جيدا بالتربيت، واثقب الجلد بخفة في كل مكان بشوكة، مع الحرص على عدم ثقب اللحم.","اسكب الماء المغلي فوق البطة في المغسلة، مما يشد الجلد، ثم جففها بالتربيت مرة أخرى.","دفئ المالتوز والخل ونبيذ شاوشينغ والبهارات الخمسة والملح حتى يذوب المالتوز، وادهنها على البطة كلها.","اترك البطة ترتاح دون غطاء في الثلاجة طوال الليل، على رف فوق صينية، حتى يجف الجلد تماما.","حمصها والصدر لأعلى على 200 درجة مئوية لمدة 30 دقيقة، ثم خفض إلى 180 درجة مئوية وحمصها لمدة 60 إلى 75 دقيقة إضافية، حتى يصبح الجلد ذهبيا عميقا ومقرمشا.","ادهنها مرة واحدة في منتصف المدة بالتزجيج المتبقي، وغط أطراف الأجنحة بورق قصدير إذا تحمرت بسرعة كبيرة.","اترك البطة ترتاح لمدة 20 دقيقة قبل التقطيع، حتى تستقر العصارة ويبقى الجلد مقرمشا.","قطع الجلد واللحم إلى شرائح رفيعة، ودفئ الفطائر، وقدمها مع الهويسن وأعواد البصل الأخضر وأعواد الخيار."],"tip":"جفف الجلد طوال الليل. فالجلد الرطب يتبخر في الفرن ولا يصبح مقرمشا أبدا، بينما الجلد الجاف يذوب ويطلى بشكل جميل.","notes":["المالتوز يعطي اللمعان الكلاسيكي وحلاوة خفيفة. والعسل يعمل، لكنه يتحمر أسرع، لذلك راقب البطة في آخر 20 دقيقة.","البهارات الخمسة قوية. وقسها، ولا تضف المزيد، وإلا ستطغى على البطة.","البطة فيها الكثير من الدهن تحت الجلد. وثقب الجلد يسمح له بالذوبان، والتحميص على رف يبقي البطة بعيدا عن دهنها.","فطائر الماندرين رفيعة وطرية. وبخرها لمدة دقيقتين قبل التقديم مباشرة، وأبقها مغطاة حتى لا تجف."],"variations":["مع بطة جاهزة من المتجر: استخدم بطة محمصة من محل أطعمة صيني، واجعل الجلد مقرمشا في فرن ساخن، وقدمها بالطريقة نفسها مع الفطائر والهويسن.","نسخة صدر البطة: اشطب صدور البطة، واحمرها والجلد لأسفل حتى يصبح مقرمشا، وأنهها في الفرن، وقطعها شرائح رفيعة للفطائر.","مع صلصة البرقوق: استبدل الهويسن بصلصة البرقوق لنهاية أحلى وأكثر فاكهية."],"serving":"يكفي 6 أشخاص، كمركز وجبة مشتركة، مع البطة المقطعة على طبق، وفطائر دافئة وهويسن وبصل أخضر وخيار في وسط الطاولة. وكل شخص يدهن الهويسن على فطيرة، ويضيف بضع شرائح من البطة والجلد، وعود بصل أخضر وخيارا، ويلفها. وقدمها مع شوربة خفيفة أو خضار مقلية على الجانب، وأبق الفطائر تأتي بينما البطة باقية.","storage":"تبقى بقايا البطة في الثلاجة لمدة تصل إلى يومين، محفوظة في وعاء محكم الإغلاق. أعد تسخين اللحم بلطف في مقلاة مغطاة مع رشة من الماء، واجعل الجلد مقرمشا بشكل منفصل تحت شواية ساخنة أو في فرن ساخن لبضع دقائق. والفطائر تبقى في الثلاجة لمدة يومين وتسخن بالتبخير. ولا تجمد الجلد المقطع، فهو يفقد قرمشته.","mistakes":["تخطي التجفيف طوال الليل. يبقى الجلد طريا ودهنيا، مهما كانت حرارة الفرن.","التحميص على حرارة منخفضة جدا. لا يذوب الدهن، لذلك يكون الجلد دهنيا بدلا من أن يكون مقرمشا.","التقطيع مبكرا جدا. تخرج العصارة ويتبخر الجلد، لذلك اتركها ترتاح 20 دقيقة كاملة.","استخدام فطائر سميكة. تطغى على البطة، لذلك استخدم فطائر ماندرين رفيعة ودفئها جيدا."],"faq":[["هل يمكنني تحضير بطة بكين في فرن أصغر؟","نعم، إذا كانت البطة تتسع مع هواء حولها. وبطة أصغر بحوالي 2 كغ أسهل، والطريقة هي نفسها."],["ماذا لو لم أجد المالتوز؟","استخدم عسلا مخففا بقليل من الماء الساخن. وسيكون التزجيج أغمق قليلا، لذلك راقبه قرب نهاية التحميص."],["هل يمكنني استخدام أرجل البطة فقط؟","نعم. جففها وزججها بالطريقة نفسها، وحمصها لمدة 50 إلى 60 دقيقة تقريبا حتى تصبح مقرمشة. وهي أسهل في التعامل من بطة كاملة."],["لماذا جلد البط ليس مقرمشا؟","لم يكن الجلد جافا بما يكفي، أو كان الفرن باردا جدا. جففه طوال الليل، واثقبه جيدا، وحمصه ساخنا."]]},"pizza":{"intro":"بيتزا مارغريتا هي دليل على أن الطعام البسيط يمكن أن يكون استثنائيا. وقد اشتهرت في نابولي، حيث يقوم فرن ساخن وقشرة رفيعة وصلصة طماطم مشرقة وموزاريلا جيدة بكل العمل. ويقال إن الألوان تعكس العلم الإيطالي، طماطم حمراء وموزاريلا بيضاء وريحان أخضر، والنكهة نظيفة وطازجة بدلا من أن تكون ثقيلة. وهذه النسخة تستخدم عجينة ترتاح طويلا بما يكفي لتصبح خفيفة وماضغة، وصلصة تكاد لا تطبخ، وفرنا ساخنا جدا حتى تفقع القشرة في دقائق. وخذ وقتك مع العجينة والحرارة، وستكون البيتزا بطعم بيتزا محل بيتزا، حتى من فرن منزلي.","ing":["دقيق خبز قوي 500 غرام","ماء دافئ 325 مل","خميرة فورية 7 غرامات","ملح ناعم 10 غرامات","زيت زيتون 2 ملعقة كبيرة","طماطم سان مارزانو 400 غرام (مهروسة)","موزاريلا فيور دي لاتيه 250 غراما (ممزقة)","أوراق ريحان طازجة 1 حفنة","ثوم 1 فص","زيت زيتون وملح للصلصة","سميد أو دقيق للرش"],"steps":["اخلط الدقيق والماء والخميرة والملح، واعجن لمدة 8 إلى 10 دقائق حتى يصبح ناعما، ثم اترك العجينة مغطاة ترتاح لمدة ساعة واحدة، أو طوال الليل في الثلاجة لنكهة أفضل.","اهرس الطماطم مع الثوم ورشة ملح وملعقة كبيرة من زيت الزيتون. ولا تطبخ الصلصة، فهي تطبخ على البيتزا.","قسم العجينة إلى 4 كرات، واتركها ترتاح لمدة 20 دقيقة، ثم افرد كل واحدة باليد من الوسط إلى الخارج، مع ترك حافة أسمك.","سخن الفرن إلى أقصى حرارة ممكنة، 250 درجة مئوية على الأقل، مع حجر بيتزا أو صينية خبز مقلوبة في الداخل لمدة 30 دقيقة.","افرد 3 إلى 4 ملاعق كبيرة من الصلصة على كل قاعدة، مع ترك الحافة صافية، وانثر الموزاريلا الممزقة فوقها.","اخبز لمدة 6 إلى 8 دقائق حتى تفقع القشرة وتصبح ذهبية ويغلي الجبن.","أضف أوراق الريحان بمجرد خروج البيتزا، حتى تذبل بلطف دون أن تحترق.","رش قليلا من زيت الزيتون، وقطع، وقدم فورا بينما القشرة مقرمشة."],"tip":"لا تفرط في تحميل البيتزا. فطبقة رفيعة من الصلصة وكمية معتدلة من الجبن تسمح للقشرة بأن تطبخ تماما وتبقى مقرمشة.","notes":["دقيق الخبز يعطي المضغ الذي لا يستطيع الدقيق العادي إعطاءه، لذلك استخدمه إذا وجدته، وزن الدقيق لعجينة موثوقة.","فيور دي لاتيه هي الموزاريلا الطرية المباعة في الماء. وصفها ومزقها، وجففها بالتربيت، حتى لا تصبح البيتزا رطبة.","طماطم سان مارزانو حلوة وقليلة الحموضة. وإذا استخدمت علبة أخرى، اهرسها جيدا وأضف رشة سكر فقط إذا كان طعمها حادا.","السميد على المجرفة يمنع العجينة من الالتصاق ويضيف قليلا من القرمشة. والدقيق وحده يمكن أن يحترق ويصبح طعمه مرا على حرارة عالية."],"variations":["مارينارا: تخط الجبن، وأضف ثوما إضافيا وأوريغانو، وأنه بزيت الزيتون، لبيتزا دون منتجات ألبان.","أربعة أجبان: استبدل صلصة الطماطم بطبقة رفيعة من زيت الزيتون، ثم استخدم الموزاريلا والغورغونزولا والفونتينا والبارميزان.","مع طماطم كرزية: حمص أنصاف طماطم كرزية مع زيت الزيتون أولا، ثم استخدمها بدلا من صلصة الطماطم المهروسة."],"serving":"يكفي 4 أشخاص، مع بيتزا واحدة لكل شخص، أو مقطعة إلى شرائح للمشاركة مع سلطة خضراء. وقدمها مباشرة من الفرن، مع ريحان إضافي أو زيت فلفل حار أو بارميزان على الطاولة، ودع الجميع يضيفون خاصتهم. والبيتزا في أفضل حالاتها في أول 10 دقائق، عندما تكون القاعدة مقرمشة والجبن ما زال طريا وقابلا للتمدد.","storage":"تبقى شرائح البيتزا في الثلاجة لمدة تصل إلى يومين في وعاء محكم الإغلاق. أعد تسخينها في فرن ساخن أو مقلاة جافة مع غطاء، حتى تصبح القاعدة مقرمشة مرة أخرى. وتجنب الميكروويف، فهو يجعل القشرة طرية وماضغة. والعجينة النيئة تبقى في الثلاجة لمدة تصل إلى 3 أيام، وتتجمد جيدا لمدة تصل إلى شهر واحد، وتذاب طوال الليل في الثلاجة.","mistakes":["استخدام فرن بارد. تتبخر القشرة بدلا من أن تفقع، لذلك سخن الحجر أو الصينية بالكامل.","فرد العجينة بشوبك. يضغط الهواء خارجا، لذلك افردها باليد بدلا من ذلك.","إضافة الكثير من الصلصة أو الجبن. يبقى الوسط رطبا ولا تصبح القاعدة مقرمشة أبدا.","وضع الريحان قبل الخبز على حرارة عالية جدا. يسود، لذلك أضفه بعد الخبز."],"faq":[["لماذا قاعدة البيتزا مبللة في الوسط؟","لم يكن الفرن أو الحجر ساخنا بما يكفي، أو كان هناك الكثير من الصلصة والجبن. سخن بالكامل، واستخدم حشوة أقل، واخبز على الرف الأدنى."],["هل يمكنني تحضير العجينة مسبقا؟","نعم. بعد العجن، احفظها في الثلاجة لمدة تصل إلى 3 أيام. وأعدها إلى درجة حرارة الغرفة لمدة 30 إلى 45 دقيقة قبل فردها."],["هل أحتاج إلى حجر بيتزا؟","لا. صينية خبز ثقيلة مقلوبة، مسخنة مسبقا في الفرن، تعمل جيدا. ومقلاة حديد زهر تعطي أيضا قاعدة مقرمشة."],["هل يمكنني استخدام ريحان مجفف؟","الريحان الطازج أفضل بكثير هنا، لأنه النكهة الرئيسية. والريحان المجفف في الصلصة جيد، لكن أضف أوراقا طازجة للإنهاء."]]},"poutine":{"intro":"البوتين يأتي من كيبيك في كندا، وهو بسيط بشكل رائع، بطاطس مقلية ساخنة ومقرمشة، وخثارة جبن طازجة تصدر صوتا عند عضها، ومرق بني غني يسكب فوقها حتى تبدأ الخثارة في الذوبان. ويجب أن تكون البطاطس المقلية مقرمشة بما يكفي لتحمل المرق دون أن تصبح مبللة في دقيقة، لذلك القلي المزدوج يستحق، ويجب أن يكون المرق ساخنا جدا، لأنه الحرارة هي التي تلين الخثارة. وقدمها فورا، في وعاء، مع شوكة، وكلها بينما البطاطس ما زالت مقرمشة عند الحواف والمرق يتجمع في القاع.","ing":["بطاطس 1 كغ (صنف دقيقي)","خثارة جبن 250 غراما (في درجة حرارة الغرفة)","مرق لحم بقر أو خضار 500 مل","زبدة 2 ملعقة كبيرة","دقيق 2 ملعقة كبيرة","صلصة صويا 1 ملعقة صغيرة","صلصة ورسيسترشاير 1 ملعقة صغيرة","ثوم 1 فص","فلفل أسود","زيت للقلي العميق","ملح","بصل أخضر للتقديم (اختياري)"],"steps":["قطع البطاطس إلى أعواد سميكة، وانقعها في ماء بارد لمدة 30 دقيقة، ثم صفها وجففها جيدا جدا.","سخن الزيت إلى 160 درجة مئوية، واقل البطاطس على دفعات لمدة 5 إلى 6 دقائق حتى تصبح شاحبة وطرية، ثم صفها واتركها ترتاح لمدة 10 دقائق.","بينما ترتاح البطاطس، أذب الزبدة في مقلاة، وحرك الدقيق فيها، واطبخه لمدة دقيقتين حتى يصبح ذهبيا خفيفا.","اخفق المرق الساخن قليلا في كل مرة، ثم أضف الصويا والورسيسترشاير والثوم والفلفل، واتركه يغلي على نار هادئة لمدة 5 دقائق حتى يصبح ناعما ولامعا.","سخن الزيت إلى 190 درجة مئوية، واقل البطاطس مرة أخرى على دفعات لمدة 2 إلى 3 دقائق حتى تصبح ذهبية عميقة ومقرمشة جدا. وصفها وملحها فورا.","كدس البطاطس الساخنة في أوعية دافئة، وانثر خثارة الجبن فوقها، وأبق الخثارة في درجة حرارة الغرفة حتى تلين، لا أن تذوب تماما.","اسكب المرق الساخن جدا فوقها، حتى يجري في الفجوات ويبدأ في إذابة الخثارة.","قدمها فورا مع شوكة، مع بصل أخضر منثور فوقها إذا أردت، وكلها وهي ساخنة."],"tip":"استخدم خثارة جبن في درجة حرارة الغرفة. فالخثارة الباردة تبقى متماسكة ولا تلين، بينما خثارة درجة حرارة الغرفة تصبح طرية وتصدر صوتا تحت المرق الساخن.","notes":["البطاطس الدقيقية تصنع أخف البطاطس المقلية. والبطاطس الشمعية تبقى كثيفة ولا تصبح مقرمشة بالطريقة نفسها.","خثارة الجبن يجب أن تكون طازجة وتصدر صوتا. وإذا لم تجد خثارة، استخدم قطعا ممزقة من الموزاريلا الطازجة، وإن كان الصوت سيغيب.","المرق يجب أن يكون رقيقا بما يكفي ليجري، وليس سميكا مثل يخنة. وهو يتكاثف عندما يبرد، لذلك قدمه ساخنا جدا.","القلي المزدوج هو سر البطاطس المقرمشة التي تدوم. والقلي الأول يطبخ الداخل، والقلي الثاني يقرمش الخارج."],"variations":["مع لحم خنزير مسحوب: غطها بلحم خنزير مسحوب مطهو ببطء ومرق إضافي، لطبق رئيسي أكثر إشباعا.","مع الفطر: أضف فطرا مقليا وزعترا إلى المرق، واستخدم مرق خضار، لنسخة نباتية.","بوتين الفطور: أضف بيضة مقلية في الأعلى، وقدمها مع لحم خنزير مقدد على الجانب."],"serving":"يكفي 4 أشخاص، كوجبة خفيفة أو طبق جانبي أو طبق رئيسي للمشاركة، في أوعية عميقة مع شوك. وقدمها في اللحظة التي يسكب فيها المرق، بينما البطاطس مقرمشة والخثارة تلين، ولا تدعها تجلس، لأن البطاطس تلين بسرعة. والبوتين طعام عادي، لذلك قدمه في وسط الطاولة، مع مرق إضافي في إبريق لمن يريد المزيد.","storage":"البوتين يؤكل طازجا أفضل ولا يسخن جيدا بعد تجميعه، لأن البطاطس تصبح طرية. واحفظ المكونات بشكل منفصل، البطاطس والخثارة والمرق، لمدة تصل إلى يومين في الثلاجة. أعد تسخين البطاطس في فرن ساخن حتى تصبح مقرمشة، وأعد تسخين المرق حتى يغلي، واجمعها طازجة. والمرق وحده يتجمد جيدا لمدة شهر واحد.","mistakes":["استخدام خثارة جبن باردة. تبقى صلبة ولا تذوب في البطاطس المقلية.","سكب مرق فاتر. لا يلين الخثارة، لذلك سخن المرق حتى يصبح ساخنا بالبخار.","قلي البطاطس مرة واحدة فقط. تصبح طرية تحت المرق في دقائق، لذلك اقلها مرتين.","تمليح البطاطس قبل القلي الثاني. يسحب الملح الماء ويمنعها من أن تصبح مقرمشة، لذلك ملحها فقط في النهاية."],"faq":[["ما هي خثارة الجبن؟","قطع طازجة من حليب متخثر، مضغوطة بخفة، بقوام يصدر صوتا عند العض. وهي المكون المميز للبوتين."],["هل يمكنني استخدام بطاطس مجمدة؟","نعم. اطبخها حتى تصبح مقرمشة جدا في الفرن أو المقلاة الهوائية، ثم اجمعها مع مرق ساخن وخثارة. والقلي المزدوج للبطاطس الطازجة أفضل، لكن البطاطس المجمدة تعمل."],["هل البوتين نباتي؟","مع مرق خضار وصلصة ورسيسترشاير نباتية يمكن أن يكون. والمرق التقليدي يستخدم مرق لحم بقر، لذلك تحقق من المرق الذي تستخدمه."],["هل يمكنني تحضير المرق مسبقا؟","نعم. حضره قبل 3 أيام، واحفظه في الثلاجة، وأعد تسخينه حتى يغلي قبل سكبه فوق البطاطس."]]},"pozole":{"intro":"البوزولي حساء احتفال من المكسيك، مصنوع من الهوميني، حبات الذرة البيضاء الكبيرة التي تنتفخ وتلين في غليان طويل، ولحم خنزير يطبخ حتى يتفتت بالملعقة. والنسخة الحمراء تحصل على لونها وعمقها من فلفل غواخيو وأنشو المجففين، المخلوطين ناعما والمحركين في المرق، بينما تبقى الإضافات طازجة ومقرمشة، ملفوف مبشور وفجل وبصل وأوريغانو وليمون. ويستغرق وقتا، لكن معظم ذلك الوقت غير مراقب، والقدر يطعم حشدا. واطبخه في عطلة نهاية الأسبوع، وأبق المرق غنيا والإضافات منفصلة، ودع الجميع ينهون أوعيتهم على الطاولة.","ing":["كتف خنزير 1 كغ (مقطع إلى قطع كبيرة)","هوميني أبيض 800 غرام (مصفى ومشطوف)","فلفل غواخيو مجفف 4","فلفل أنشو 2","بصل 1","ثوم 6 فصوص","أوراق غار 2","أوريغانو 2 ملعقة صغيرة","كمون 1 ملعقة صغيرة","ملح","ماء أو مرق خفيف 3 لترات","ملفوف مبشور وفجل وبصل وليمون للتقديم","أوريغانو مجفف ورقائق فلفل حار للتقديم"],"steps":["انقع الفلفل المجفف في ماء ساخن لمدة 15 دقيقة، وصفه، واخلطه مع الثوم وقليل من ماء النقع حتى يصبح ناعما.","ضع لحم الخنزير والهوميني والبصل وأوراق الغار والماء في قدر كبير، واتركه يغلي، وأزل أي رغوة.","خفض إلى غليان هادئ ولطيف، وغطه جزئيا، واطبخه لمدة 90 دقيقة، مع إضافة ماء ساخن إذا انخفض المستوى كثيرا.","صف صلصة الفلفل المخلوطة عبر مصفاة إلى القدر، وحرك جيدا، وتبل بالملح والكمون والأوريغانو.","اتركه يغلي على نار هادئة لمدة 30 دقيقة إضافية حتى يصبح لحم الخنزير طريا بما يكفي ليتفتت ويصبح المرق غنيا وأحمر.","ارفع لحم الخنزير، وفتته بشوكتين، وأعده إلى القدر. وتذوق وعدل الملح والفلفل الحار.","حضر الإضافات بينما ينتهي البوزولي، ملفوف مبشور وشرائح فجل رفيعة وبصل مقطع وشرائح ليمون وأوريغانو.","اسكبه في أوعية عميقة، وأضف كمية سخية من الإضافات، وقدمه مع خبز تورتيلا دافئ على الجانب."],"tip":"صف صلصة الفلفل الحار قبل إضافتها. فالمصفاة تلتقط القشور والبذور، ويبقى المرق ناعما وحريريا بدلا من أن يكون محببا.","notes":["الهوميني ذرة معالجة بالجير، مما يجعل الحبات كبيرة وطرية وسهلة الهضم. والهوميني المعلب جاهز للاستخدام، والهوميني المجفف يحتاج إلى نقع طوال الليل وطهي أطول.","فلفل الغواخيو يعطي لونا وحرارة فاكهية خفيفة. والأنشو يضيف عمقا أغمق يشبه الزبيب. ومعا يصنعان المرق الأحمر الكلاسيكي.","كتف الخنزير فيه دهن كاف ليبقى طريا خلال غليان طويل. ولحم الخنزير الخالي من الدهن يجف، لذلك أبق القطع كبيرة والغليان هادئا.","ازل الرغوة في البداية. فهي تبقي المرق صافيا والنكهة نظيفة."],"variations":["بوزولي أخضر: استبدل الفلفل الأحمر بالطماطم الخضراء والفلفل الأخضر الحار والكزبرة، مخلوطة ومضافة بالطريقة نفسها.","بوزولي الدجاج: استخدم أفخاذ دجاج بالعظم بدلا من لحم الخنزير، وقلل وقت الغليان إلى حوالي 45 دقيقة.","بوزولي نباتي: استخدم الفطر والفاصوليا مع مرق خضار، وأضف صلصة الفلفل الحار والإضافات نفسها."],"serving":"يكفي 6 أشخاص، في أوعية عميقة، مع الإضافات في أوعية منفصلة في وسط الطاولة. وكل شخص يضيف ملفوفا للقرمشة وفجلا للعضة وبصلا وأوريغانو وعصرة جيدة من الليمون، مما يرفع المرق الغني. وقدمه مع خبز تورتيلا ذرة دافئ للغمس، وأبق رقائق فلفل حار إضافية على الجانب لمن يريد حرارة أكثر.","storage":"يبقى البوزولي في الثلاجة لمدة تصل إلى 4 أيام، وتتحسن النكهة طوال الليل. واحفظ المرق ولحم الخنزير معا، والإضافات بشكل منفصل. أعد تسخينه بلطف حتى يغلي، مع إضافة رشة من الماء إذا تكاثف. وهو يتجمد جيدا لمدة تصل إلى 3 أشهر، ويذاب طوال الليل في الثلاجة. ولا تجمد الإضافات الطازجة.","mistakes":["الغليان بقوة طوال الوقت. يقسو لحم الخنزير ويصبح المرق عكرا، لذلك أبق غليانا هادئا ولطيفا.","إضافة صلصة الفلفل الحار دون تصفية. فالقشور والبذور تجعل المرق محببا.","التقديم دون إضافات طازجة. فهي ليست زينة، بل توازن المرق الغني بالقرمشة والحموضة.","عدم تمليح المرق بما يكفي. تذوق في النهاية، لأن الهوميني ولحم الخنزير يحتاجان إلى كمية جيدة من الملح ليتألقا."],"faq":[["هل يمكنني استخدام قدر الضغط؟","نعم. اطبخ لحم الخنزير والهوميني تحت الضغط لمدة 35 إلى 40 دقيقة، ثم أكمل مع صلصة الفلفل الحار في قدر مفتوح لمدة 10 دقائق."],["هل البوزولي حار جدا؟","النسخة الحمراء دافئة، وليست حارة بشدة. أزل بذور الفلفل الحار لمرق أخف، ودع رقائق الفلفل الحار على الطاولة تضيف الحرارة."],["هل يمكنني استخدام هوميني مجفف؟","نعم، لكن انقعه طوال الليل واتركه يغلي حتى يلين قبل إضافة لحم الخنزير، مما قد يستغرق ساعة إضافية."],["ماذا أقدم مع البوزولي؟","خبز تورتيلا ذرة دافئا، والإضافات الطازجة المذكورة هنا. وسلطة بسيطة ليست ضرورية، فالإضافات هي السلطة."]]},"ramen":{"intro":"الرامن راحة في وعاء، ونسخة منزلية جيدة لا تحتاج إلى مرق يغلي طوال اليوم. فرامن الدجاج هذا يبني النكهة بسرعة، مع ثوم وزنجبيل وبصل أخضر مقلي في زيت السمسم، ومرق دجاج غني بالصويا والميسو، ونودلز مطبوخة بشكل منفصل حتى يبقى المرق صافيا والنودلز مرنة. والبيضة هي اللمسة الأخيرة، طرية في الوسط ومتبلة بالمرق وأنت تأكل. ضع الإضافات في أوعية صغيرة ودع الجميع يبنون وعاءهم الخاص، والمرق الساخن أخيرا، حتى لا تجلس النودلز وتلين. وهو سريع ودافئ ومرض بعمق، ويبدو مثل العناية، وليس مثل اختصار.","ing":["صدور أو أفخاذ دجاج 500 غرام","مرق دجاج 1.5 لتر","نودلز رامن 4 حصص","ثوم 4 فصوص","زنجبيل قطعة 3 سم","صلصة صويا 3 ملاعق كبيرة","معجون ميسو 2 ملعقة كبيرة","زيت سمسم 1 ملعقة كبيرة","بصل أخضر 4","بيض 4 (مسلوق طريا)","زيت فلفل حار وبذور سمسم ونوري للتقديم"],"steps":["اسلق البيض لمدة 6 دقائق ونصف، وبرده في ماء بارد، وقشره، وقطعه إلى نصفين قبل التقديم مباشرة.","سخن زيت السمسم في قدر كبير، واقل الثوم والزنجبيل والأجزاء البيضاء من البصل الأخضر لمدة دقيقتين حتى تفوح رائحته.","اسكب مرق الدجاج، وأضف صلصة الصويا، واتركه يغلي على نار هادئة لمدة 15 دقيقة حتى تمتزج النكهات.","اطبخ الدجاج في المرق الذي يغلي على نار هادئة لمدة 12 إلى 15 دقيقة حتى ينضج تماما، ثم ارفعه، وقطعه، وأبقه دافئا.","اخفق الميسو مع مغرفة من المرق الساخن حتى يصبح ناعما، ثم حركه وأعده إلى القدر. ولا تغله بقوة بعد إضافة الميسو.","اطبخ النودلز بشكل منفصل حسب العبوة، وصفها جيدا، وقسمها بين 4 أوعية دافئة.","اسكب المرق الساخن فوق النودلز، وغطه بالدجاج المقطع وأنصاف البيض والبصل الأخضر وبذور السمسم.","قدمه فورا مع زيت الفلفل الحار والنوري على الجانب، وكله بينما المرق ساخن بالبخار."],"tip":"اطبخ النودلز بشكل منفصل. فالنودلز المطبوخة في المرق تمتصه، وتحول المرق إلى عكر، وتصبح طرية قبل أن تقدم.","notes":["الميسو يضيف عمقا وملحا. والميسو الأبيض خفيف وحلو، والميسو الأحمر أقوى، لذلك ابدأ بأقل إذا استخدمت الأحمر.","نودلز الرامن الطازجة تطبخ في 2 إلى 3 دقائق وتبقى مرنة. والنودلز المجففة تعمل أيضا، لكن تحقق من وقت العبوة ولا تبالغ في طهيها.","الزنجبيل يجب أن يقطع شرائح، لا أن يفرم، حتى ينكه المرق دون أن يجعله عكرا أو محببا.","زيت السمسم للنكهة، وليس للقلي على حرارة عالية. أضفه في البداية على نار متوسطة، ولا تدعه يدخن."],"variations":["رامن حار: حرك ملعقة كبيرة من معجون الفلفل الحار أو الغوتشوجانغ في المرق مع الميسو.","رامن الخضار: استبدل الدجاج بالفطر والتوفو، واستخدم مرق خضار، مع إبقاء المواد العطرية نفسها.","رامن لحم الخنزير: استخدم شرائح رفيعة من لحم خنزير مطهو بدلا من الدجاج، وأضف ذرة حلوة وبراعم فاصوليا في الأعلى."],"serving":"يكفي 4 أشخاص، في أوعية عميقة، مع عيدان طعام وملعقة شوربة، والإضافات في وسط الطاولة. وقدم المرق ساخنا بالبخار، مع زيت فلفل حار إضافي وصلصة صويا وبذور سمسم في متناول اليد، حتى يتمكن كل شخص من تتبيل وعائه الخاص. والرامن يؤكل فورا، بينما النودلز مرنة والبيض ما زال دافئا، لذلك ناد الجميع إلى الطاولة قبل أن تسكب المرق.","storage":"يبقى المرق في الثلاجة لمدة تصل إلى 3 أيام، ويتجمد جيدا لمدة تصل إلى شهر واحد. والنودلز والإضافات لا تبقى جيدة بعد دمجها، لذلك احفظها بشكل منفصل واجمعها طازجة. وأعد تسخين المرق حتى يغلي، واطبخ نودلز طازجة، وأضف الإضافات قبل التقديم مباشرة. وشرائح الدجاج المتبقية تبقى لمدة يومين في الثلاجة.","mistakes":["غلي المرق بقوة بعد إضافة الميسو. يبهت النكهة ويمكن أن ينفصل، لذلك أبقه على غليان هادئ ولطيف.","المبالغة في طهي النودلز. تلين في المرق الساخن، لذلك اطبخها حتى تصبح مرنة فقط وصفها جيدا.","إضافة البيض مبكرا جدا. يطبخ أكثر من اللازم في المرق الساخن، لذلك أضف البيض المقطع إلى نصفين في النهاية تماما.","التقديم في أوعية باردة. يبرد المرق بسرعة كبيرة، لذلك دفئ الأوعية بماء ساخن أولا."],"faq":[["هل يمكنني استخدام نودلز فورية؟","نعم، لكن تخط كيس النكهة واستخدم هذا المرق بدلا منه. اطبخ قطعة النودلز بشكل منفصل وصفها جيدا."],["هل يمكنني تحضير المرق مسبقا؟","نعم. حضره قبل 3 أيام واحفظه في الثلاجة. أعد تسخينه حتى يغلي، ثم أضف الميسو طازجا واجمع الأوعية."],["كيف أحصل على بيضة طرية الصفار؟","اسلق بيضة باردة من الثلاجة لمدة 6 دقائق ونصف، وبردها فورا في ماء بارد، وقشرها بلطف. ويجب أن يكون الصفار طريا ومتماسكا فقط."],["هل الرامن مالح جدا؟","يمكن أن يكون. تذوق قبل إضافة صلصة صويا إضافية، لأن المرق والصويا والميسو كلها تضيف الملح."]]},"samosa":{"intro":"السمبوسة الجيدة يحكم عليها من اللقمة الأولى، عجينة مقرمشة تتكسر، ثم بطاطس متبلة مع البازلاء والزنجبيل والكزبرة. ويجب أن تكون العجينة متماسكة ومرتاحة، ويجب أن تكون الحشوة جافة، وليست رطبة، ويجب أن يكون القلي بطيئا، على نار هادئة، حتى يتحول القشرة إلى الذهبي في كل أجزائها بدلا من أن تتحمر في دقيقة وتبقى شاحبة من الداخل. وهذه الوصفة تصنع السمبوسة البنجابية الكلاسيكية، التي تقدم مع التشاتني الخضراء وتشاتني التمر الهندي وكوب من الشاي. واصنع ضعف الكمية، لأنها تختفي بسرعة، وجمد الباقي قبل القلي ليوم آخر.","ing":["دقيق 2 كوب","بذور أجوين 1/2 ملعقة صغيرة","بطاطس (مسلوقة) 4","بازلاء 1/2 كوب","زنجبيل","فلفل أخضر حار","غارام ماسالا","كزبرة طازجة","بذور رمان","زيت للقلي"],"steps":["افرك بذور الأجوين و3 ملاعق كبيرة من الزيت في الدقيق بأطراف أصابعك حتى يبدو مثل فتات الخبز.","أضف الماء قليلا في كل مرة واعجن عجينة متماسكة وصلبة. ويجب ألا تكون طرية. وغطها واتركها ترتاح لمدة 20 دقيقة.","اسلق البطاطس حتى تنضج تماما، وبردها، وفتتها بشكل خشن. ولا تهرسها ناعمة.","سخن ملعقة كبيرة من الزيت، واقل الزنجبيل والفلفل الأخضر الحار لمدة 30 ثانية، وأضف البازلاء وغارام ماسالا والملح وبذور الرمان، واطبخ لمدة دقيقتين.","أضف البطاطس والكزبرة، واخلط جيدا، واطبخ لمدة 2 إلى 3 دقائق حتى تصبح الحشوة جافة. وبردها تماما.","قسم العجينة إلى كرات، وافرد كل واحدة إلى شكل بيضاوي، واقطعها إلى نصفين، وشكل مخروطا، وأغلق الحافة المستقيمة بالماء.","املأ كل مخروط ثلاثة أرباعه، وأغلق الحافة العلوية بإحكام، واضغط للإغلاق. وتأكد من أن الحشوة لا تخرج.","اقلها في زيت على نار هادئة لمدة 12 إلى 15 دقيقة، مع التقليب بين الحين والآخر، حتى تصبح ذهبية غامقة ومقرمشة. وصفها وقدمها مع التشاتني."],"tip":"اقل السمبوسة دائما على نار هادئة. فعلى نار عالية ستحترق العجينة ويبقى الداخل نيئا، وستفقع القشرة بدلا من أن تصبح مقرمشة ومتساوية.","notes":["العجينة المتماسكة هي سر العجينة المقرمشة. والعجينة الطرية تصنع سمبوسة ماضغة ودهنية.","برد الحشوة تماما قبل الحشو. فالحشوة الدافئة تبخر العجينة من الداخل وتضعف الختم.","بذور الأجوين تعطي النكهة الكلاسيكية وتساعد على الهضم. ولا تتخطها إذا وجدتها.","الحشوة الجافة مهمة. فالحشوة الرطبة تتسرب، وتلين العجينة، وتجعل القلي فوضويا."],"variations":["سمبوسة الكيما: استبدل البطاطس بلحم مفروم مطهو ومتبل، مبرد تماما، واقله بالطريقة نفسها.","سمبوسة البانير: استخدم بانيرا مفتتا مع البازلاء وغارام ماسالا والكزبرة، لحشوة نباتية أغنى.","سمبوسة مخبوزة: ادهنها بالزيت واخبزها على 190 درجة مئوية لمدة 20 إلى 25 دقيقة، مع قلبها مرة واحدة. أقل قرمشة، لكنها أخف."],"serving":"يكفي 6 أشخاص، مع سمبوستين لكل شخص، وتشاتني خضراء، وتشاتني تمر هندي، وبصل مقطع وشاي ساخن. وقدمها على طبق، واقطع واحدة لتظهر الحشوة، وأبق تشاتني إضافية على الجانب. والسمبوسة أفضل وهي ساخنة، خلال 30 دقيقة من القلي، بينما العجينة ما زالت مقرمشة. وقليل من تشات ماسالا مرشوشة في الأعلى يضيف لمسة حامضة.","storage":"كلها طازجة لأفضل قرمشة. والسمبوسة المقلية المبردة تبقى في الثلاجة لمدة تصل إلى يومين وتسخن في الفرن على 180 درجة مئوية لمدة 8 إلى 10 دقائق، حتى تصبح مقرمشة مرة أخرى. ولا تستخدم الميكروويف، لأن العجينة تصبح طرية. وجمد السمبوسة غير المطبوخة والمشكلة على صينية، ثم ضعها في أكياس لمدة تصل إلى شهر واحد، واقلها من المجمدة على نار هادئة، مع إضافة 3 إلى 4 دقائق.","mistakes":["عجن عجينة طرية. تفرد بسهولة، لكنها تقلى طرية ودهنية.","الحشو بحشوة دافئة ورطبة. ينفتح الختم وتتسرب الحشوة إلى الزيت.","القلي على نار عالية. يتحمر الخارج بسرعة وتبقى العجينة من الداخل نيئة.","الإفراط في ملء المخاريط. تنفجر في الزيت، لذلك املأ ثلاثة أرباعها فقط."],"faq":[["لماذا عجينة السمبوسة طرية، وليست مقرمشة؟","كانت العجينة طرية جدا، أو كانت حرارة القلي عالية جدا. اعجنها متماسكة، واترك العجينة ترتاح، واقلها على نار هادئة وببطء."],["هل يمكنني تحضير السمبوسة في مقلاة هوائية؟","نعم. ادهنها بالزيت واقلها بالهواء على 180 درجة مئوية لمدة 12 إلى 15 دقيقة، مع قلبها مرة واحدة. والقشرة مقرمشة، وإن كانت أجف قليلا من المقلية بعمق."],["كيف أمنع السمبوسة من الانفتاح أثناء القلي؟","أغلقها بالماء واضغط بإحكام، ودع السمبوسة المشكلة ترتاح لمدة 10 دقائق قبل القلي، حتى يتماسك الختم."],["هل يمكنني استخدام عجينة جاهزة؟","يمكنك استخدام أوراق السبرينغ رول عند الحاجة، لكن النكهة والقوام مختلفان. والقرمشة الكلاسيكية تأتي من عجينة الدقيق المتماسكة في هذه الوصفة."]]},"sushi":{"intro":"السوشي يتعلق بالأرز أولا والسمك ثانيا. ففي اليابان، يتبل الأرز بالخل والسكر والملح، ويبرد بالمروحة، ويعامل بلطف حتى تبقى كل حبة منفصلة ولامعة. وهذه النسخة المنزلية تصنع لفائف السلمون والخيار، وهي الأسهل في التعلم، مع النوري في الخارج والأرز في الوسط وخط مرتب من الحشوة. استخدم سلمونا بدرجة السوشي، وأبق يديك مبللتين، ولف بإحكام لكن بلطف. وقد تبدو اللفة الأولى غير متساوية، وهذا طبيعي. وبحلول اللفة الثالثة، يجتمع الشكل والقطع والثقة معا، وتكون النتيجة طازجة ونظيفة وأفضل بكثير من سوشي متجر جلس في الثلاجة.","ing":["أرز سوشي 2 كوب (غير مطهو)","خل أرز 4 ملاعق كبيرة","سكر 2 ملعقة كبيرة","ملح 1 ملعقة صغيرة","أوراق نوري 4","سلمون بدرجة السوشي 300 غرام (مقطع إلى شرائح)","خيار 1 (مقطع إلى أعواد رفيعة)","مايونيز 3 ملاعق كبيرة","سريراتشا 1 ملعقة صغيرة (لمايونيز حار)","صلصة صويا وزنجبيل مخلل وواسابي للتقديم","بذور سمسم 1 ملعقة كبيرة (اختياري)"],"steps":["اغسل الأرز حتى يصبح الماء صافيا، واطبخه، ثم اتركه مغطى يرتاح لمدة 10 دقائق.","دفئ الخل والسكر والملح حتى يذوب، واطوه في الأرز الساخن بحركة تقطيع، وهوه الأرز حتى يصبح دافئا فقط ولامعا.","ضع ورقة نوري بالجانب اللامع لأسفل على حصيرة خيزران، وبلل يديك، وافرد طبقة رفيعة متساوية من الأرز، مع ترك 2 سم فارغة عند الحافة البعيدة.","افرد خطا رفيعا من المايونيز الحار عبر الوسط، وأضف شرائح السلمون والخيار في صف مرتب، ورش بذور السمسم.","ارفع الحافة القريبة من الحصيرة ولف بإحكام بعيدا عنك، مع إدخال الحشوة، واضغط بلطف لإغلاق الحافة الفارغة بقليل من الماء.","اترك اللفة ترتاح لمدة دقيقتين، ثم اقطعها بسكين حاد مبلل إلى 8 قطع، مع مسح الشفرة بين القطع.","كرر مع الأرز والحشوة المتبقيين، مع إبقاء يديك مبللتين طوال الوقت.","رتب القطع بجانب القطع لأعلى، وقدمها مع صلصة الصويا والزنجبيل المخلل وكمية صغيرة من الواسابي."],"tip":"أبق وعاء ماء قريبا وبلل يديك وسكينك كثيرا. فالأيدي المبللة تمنع الأرز من الالتصاق، والشفرة المبللة تقطع بنظافة دون سحق اللفة.","notes":["أرز السوشي أرز قصير الحبة. والأرز طويل الحبة لا يلتصق بالطريقة نفسها، لذلك لا تستبدله إذا أردت لفائف مرتبة.","درجة السوشي تعني سمكا يباع للأكل النيئ، محفوظا باردا من الصيد إلى البيع. واسأل بائع السمك، ولا تستخدم سمكا عاديا مخصصا للطبخ.","خل الأرز خفيف وحلو. ولا تستبدله بخل شعير قوي، لأنه سيطغى على الأرز.","النوري يجب أن يكون مقرمشا وغامقا. واحفظه محكم الإغلاق وجافا، لأن النوري الرطب يتمزق ولن يلف بشكل مرتب."],"variations":["لفائف التونة: استبدل السلمون بتونة بدرجة السوشي، وأضف الأفوكادو بدلا من الخيار.","لفائف الروبيان المطهو: استخدم روبيانا مطهوا وخيارا وقليلا من المايونيز، وهو خيار جيد إذا فضلت عدم تناول سمك نيئ.","لفائف الخضار: استخدم الخيار والأفوكادو وأعواد الجزر والفجل المخلل، مع بذور السمسم، للفة نباتية بالكامل."],"serving":"يكفي 4 أشخاص كوجبة خفيفة، مع لفافتين لكل شخص، أو كجزء من وجبة يابانية أكبر مع شوربة ميسو وسلطة. وقدمه في درجة حرارة الغرفة، بعد فترة قصيرة من التقطيع، مع صلصة الصويا للتغميس، والزنجبيل المخلل لتنظيف الحنك بين القطع، والواسابي يستخدم باعتدال. والسوشي طعام أصابع، لذلك ضع عيدان الطعام وأطباقا صغيرة، ودع الجميع يخدمون أنفسهم.","storage":"السوشي يؤكل أفضل في اليوم الذي يصنع فيه، خلال بضع ساعات من اللف. فالتبريد يجفف الأرز ويبهت السمك، لذلك لا تحضره قبل يوم. وإذا اضطررت للاحتفاظ به، غطه بإحكام واحفظه في الثلاجة لمدة تصل إلى 6 ساعات، ثم أعده إلى درجة حرارة الغرفة لمدة 20 دقيقة قبل التقديم. ولا تجمد السوشي. وأرز السوشي المطهو وحده يبقى لمدة يوم واحد في الثلاجة.","mistakes":["استخدام أرز ساخن. يبخر النوري طريا ويجعل اللفة تتفكك، لذلك برد الأرز حتى يصبح دافئا فقط.","الإفراط في ملء اللفة. فالحشوة الكثيرة تمنع اللفة من الإغلاق، لذلك أبق الحشوة في صف مرتب واحد.","القطع بسكين جاف. يلتصق الأرز ويسحب، لذلك بلل الشفرة قبل كل قطع.","الضغط بقوة أثناء اللف. يسحق الأرز وتخرج الحشوة، لذلك لف بإحكام لكن بلطف."],"faq":[["هل السلمون النيئ آمن للأكل في البيت؟","فقط إذا كان سلمونا بدرجة السوشي من بائع موثوق، محفوظا باردا، ويؤكل في اليوم نفسه. وعند الشك، استخدم روبيانا مطهوا أو خضارا بدلا منه."],["هل يمكنني تحضير السوشي دون حصيرة خيزران؟","نعم. استخدم منشفة شاي تحت غلاف بلاستيكي، أو ورقة من ورق الخبز. والحصيرة تجعله أسهل، لكنها ليست أساسية."],["لماذا أرزي لزج وطري؟","لأنه لم يغسل بما يكفي، أو حرك بقوة أثناء التتبيل. اغسله جيدا واطو التتبيلة بلطف."],["هل يمكنني تحضير الأرز مسبقا؟","نعم، قبل بضع ساعات. أبقه مغطى في درجة حرارة الغرفة، وليس في الثلاجة، ولف قبل التقديم مباشرة."]]},"tacos":{"intro":"بدأت التاكو أل باستور مع الشاورما اللبنانية التي تطبخ في مكسيكو سيتي، وأصبحت شيئا مكسيكيا تماما، لحم خنزير متبل في فلفل حار مجفف وأتشيوتي، يطبخ حتى يحمر عند الحواف، ويقدم في خبز تورتيلا ذرة دافئ مع أناناس وبصل وكزبرة. والتتبيلة تقوم بالعمل الثقيل، لذلك أعطها وقتا، فحتى 30 دقيقة تحدث فرقا، وطوال الليل أفضل. واطبخ لحم الخنزير ساخنا وسريعا حتى يحمر دون أن يجف، ودفئ التورتيلا فوق لهب مفتوح أو في مقلاة جافة، وأبق الإضافات بسيطة. والأناناس الحلو مقابل لحم الخنزير المدخن والمتبل هو النقطة كلها، لذلك لا تتخطه، وقدمه مع الليمون والصلصة على الجانب.","ing":["كتف خنزير 700 غرام (مقطع شرائح رفيعة)","فلفل غواخيو مجفف 3","فلفل أنشو 1","معجون أتشيوتي 2 ملعقة كبيرة","ثوم 3 فصوص","خل أبيض 3 ملاعق كبيرة","عصير برتقال 60 مل","كمون 1 ملعقة صغيرة","أوريغانو 1 ملعقة صغيرة","ملح","أناناس 300 غرام (مقطع إلى قطع)","خبز تورتيلا ذرة 12","بصل أبيض 1","كزبرة","ليمون 2","صلصة من اختيارك"],"steps":["انقع الفلفل المجفف في ماء ساخن لمدة 15 دقيقة حتى يلين، ثم صفه، مع الاحتفاظ بقليل من ماء النقع.","اخلط الفلفل والأتشيوتي والثوم والخل وعصير البرتقال والكمون والأوريغانو والملح حتى تصبح تتبيلة ناعمة، مع إضافة ماء النقع حسب الحاجة.","غط لحم الخنزير بالتتبيلة، وغطه، واحفظه في الثلاجة لمدة 30 دقيقة على الأقل، أو طوال الليل لأفضل نكهة.","سخن مقلاة كبيرة أو صاجا على نار عالية مع قليل من الزيت، واطبخ لحم الخنزير على دفعات لمدة 3 إلى 4 دقائق لكل جانب حتى يحمر وينضج تماما.","في المقلاة الساخنة نفسها، احمر قطع الأناناس لمدة دقيقة إلى دقيقتين لكل جانب حتى تصبح ذهبية عند الحواف.","قطع لحم الخنزير إلى قطع صغيرة وقلبه مع الأناناس وملعقة من عصارة المقلاة.","دفئ التورتيلا في مقلاة جافة أو فوق لهب حتى تصبح طرية ومبقعة قليلا، وأبقها ملفوفة في قطعة قماش.","املأ كل تورتيلا بلحم الخنزير والأناناس، وغطها ببصل مقطع وكزبرة، وقدمها مع شرائح الليمون والصلصة."],"tip":"اطبخ على دفعات ولا تزدحم المقلاة. فاللحم المزدحم يتبخر بدلا من أن يحمر، وتفقد الحواف المقرمشة التي تجعل أل باستور مميزا.","notes":["معجون الأتشيوتي يعطي اللون الأحمر والنكهة الترابية. وجده في متاجر مكسيكية أو عبر الإنترنت، ولا تستبدله بلون الطعام وحده.","فلفل الغواخيو خفيف وفاكهي. والأنشو يضيف عمقا. وأزل البذور إذا أردت حرارة أقل، والبس قفازات عند التعامل مع الفلفل المجفف.","كتف الخنزير يبقى طريا عند طهيه ساخنا وسريعا. ولحم الخنزير الخالي من الدهن يجف بسهولة أكبر، لذلك قطعه أرق واطبخه لمدة أقل.","تورتيلا الذرة تقليدية. وتورتيلا الدقيق تعمل، لكنها أطرى وأقل قدرة على حمل الحشوة العصيرية."],"variations":["تاكو أل باستور بالدجاج: استخدم أفخاذ دجاج بالتتبيلة نفسها، واطبخها حتى تحمر، لنسخة أخف.","مع الأفوكادو: أضف شرائح أفوكادو وعصرة ليمون للكريمية، مع إبقاء الأناناس أيضا.","نسخة أكثر حرارة: أضف حبة تشيبوتلي في أدوبو إلى التتبيلة، وقدمها مع صلصة حارة على الجانب."],"serving":"يكفي 4 أشخاص، مع 3 تاكو لكل شخص، بالإضافة إلى الليمون والصلصة والبصل الإضافي والكزبرة على الطاولة. وقدم التاكو بمجرد ملئها، بينما التورتيلا دافئة ولحم الخنزير ما زال يصدر صوتا، ودع الجميع يضيفون الليمون والصلصة الخاصين بهم. وطبق جانبي بسيط من الأرز والفاصوليا، أو سلطة ملفوف مقرمشة، يحول التاكو إلى وجبة كاملة دون أن يأخذ الانتباه منها.","storage":"لحم الخنزير المتبل النيئ يبقى في الثلاجة لمدة تصل إلى يوم واحد. ولحم الخنزير المطهو يبقى لمدة تصل إلى 3 أيام في الثلاجة، ويسخن أفضل في مقلاة ساخنة مع رشة من الماء، حتى يصبح مقرمشا مرة أخرى. والتورتيلا تبقى ملفوفة في درجة حرارة الغرفة لمدة يوم واحد، أو في الثلاجة لمدة 3 أيام، وتدفأ في مقلاة جافة. ولا تحفظ التاكو المجمعة، فهي تصبح مبللة. والأناناس يبقى بشكل منفصل لمدة يومين.","mistakes":["استخدام مقلاة باردة. يغلي لحم الخنزير في تتبيلته بدلا من أن يحمر، لذلك اجعل المقلاة ساخنة تدخن أولا.","تخطي وقت التتبيل. فحتى 30 دقيقة مهمة، ولحم الخنزير المتبل لمدة 5 دقائق فقط يكون طعمه باهتا.","الإفراط في ملء التورتيلا. تنشق وتسقط الحشوة، لذلك استخدم ملعقتين إلى 3 ملاعق كبيرة من لحم الخنزير لكل تاكو.","نسيان الليمون. فالحموضة ترفع لحم الخنزير الغني، لذلك قدم شرائح الليمون دائما."],"faq":[["هل يمكنني شواء لحم الخنزير بدلا من ذلك؟","نعم. اشوه على نار عالية لمدة 3 إلى 4 دقائق لكل جانب، ثم قطعه وقلبه مع الأناناس. ومقلاة الشواء تعطي أقرب نتيجة في الداخل."],["ماذا لو لم أجد معجون الأتشيوتي؟","استخدم ملعقة كبيرة من البابريكا المدخنة وملعقة صغيرة من الكمون المطحون ورشة من الكركم للون. والنكهة مختلفة، لكنها ما زالت تعمل."],["هل تورتيلا الذرة خالية من الغلوتين؟","تورتيلا الذرة النقية المصنوعة فقط من الذرة والماء والجير خالية من الغلوتين طبيعيا، لكن تحقق من العبوة من التلوث المتبادل إذا كان ذلك مهما لك."],["هل يمكنني تحضير التتبيلة مسبقا؟","نعم. اخلطها واحفظها في الثلاجة لمدة تصل إلى 3 أيام، أو جمدها لمدة شهر واحد. وتبل لحم الخنزير في اليوم الذي تطبخه فيه."]]},"tikka":{"intro":"تيكا الدجاج هو الطبق الذي يعلم الصبر بطريقة جيدة. فالتتبيلة تقوم بالعمل، والزبادي والتوابل تعمل في اللحم لمدة ساعة على الأقل، والشواية تحتاج فقط إلى حرارة عالية وبضع دقائق لكل جانب. وإذا أعدت بشكل صحيح، فإن الخارج محمر قليلا ومدخن، والداخل يبقى طريا، والليمون وتشات ماسالا في النهاية يوقظان كل شيء. وهي تعمل كمقبلات، وكطبق رئيسي مع النان، ومقطعة في لفائف وسلطات في اليوم التالي. والوصفة أدناه تستخدم شواية فرن أو شواية، ومقلاة ساخنة تعمل أيضا إذا كان هذا ما لديك.","ing":["دجاج (فخذ / دون عظم) 750 غراما","زبادي 1/2 كوب","فلفل أحمر حار 1 ملعقة كبيرة","كركم","غارام ماسالا","مسحوق كمون","معجون الزنجبيل والثوم 1 ملعقة كبيرة","ليمون 1","زيت / زبدة للدهن"],"steps":["قطع الدجاج إلى قطع متساوية واشطب كل قطعة بشقين سطحيين، حتى تصل التتبيلة إلى الداخل.","اخلط الزبادي والفلفل الأحمر الحار والكركم وغارام ماسالا ومسحوق الكمون ومعجون الزنجبيل والثوم وعصير الليمون والملح حتى تصبح عجينة ناعمة.","غط الدجاج جيدا، وغطه، واحفظه في الثلاجة لمدة ساعة على الأقل. وطوال الليل جيد ويعطي نكهة أعمق.","أخرج الدجاج قبل 20 دقيقة من الطبخ، حتى لا يكون باردا من الثلاجة عندما يلامس الحرارة.","سخن الشواية أو الشواء إلى حرارة عالية. ادهن الشبكة بخفة بالزيت وضع الدجاج في طبقة واحدة، مع ترك مسافة بين القطع.","اشوه لمدة 6 إلى 8 دقائق على الجانب الأول، مع الدهن بالزبدة أو الزيت مرة واحدة، حتى تحمر الحواف قليلا.","اقلب واشوه لمدة 6 إلى 8 دقائق إضافية، حتى ينضج تماما وتخرج العصارة صافية.","اتركه يرتاح لمدة 5 دقائق، ورش عصير الليمون وتشات ماسالا، وقدمه ساخنا مع البصل والتشاتني والنان."],"tip":"كلما طالت مدة التتبيل، كان التيكا أطرى. وإذا كان الوقت قصيرا، أعطه 30 دقيقة على الأقل، ولا تتخط التشطيب أبدا، لأن هذه هي الطريقة التي تدخل بها التتبيلة إلى القطع السميكة.","notes":["لحم الفخذ يبقى أطرى من الصدر على حرارة عالية. والصدر يعمل، لكن تحقق منه قبل دقيقة.","علق الزبادي أو استخدم زباديا سميكا. فالزبادي المائي ينزلق عن الدجاج ويحترق على الشواية.","الليمون الطازج في التتبيلة يساعد على التليين، لكن الكثير من الليمون لمدة طويلة جدا يمكن أن يجعل السطح عجينيا، لذلك أبق تتبيلات طوال الليل خفيفة الليمون.","تشات ماسالا تضاف في النهاية، وليس في التتبيلة، حتى تبقى نكهتها الحامضة مشرقة."],"variations":["مالاي تيكا: استبدل الفلفل الأحمر الحار بالفلفل الأبيض، وأضف ملعقتين كبيرتين من الكريمة وملعقة كبيرة من الجبن إلى التتبيلة، لنسخة خفيفة وكريمية.","هاريالي تيكا: اخلط الكزبرة والنعناع والفلفل الأخضر الحار والزبادي في تتبيلة خضراء، واشوه بالطريقة نفسها.","لفائف التيكا: قطع بقايا التيكا، ولفها في باراثا أو روتي مع البصل والتشاتني والسلطة، لغداء اليوم التالي."],"serving":"يكفي 4 أشخاص مع النان أو الروتي، والبصل المقطع، وشرائح الليمون، والتشاتني الخضراء وسلطة. وقدمه على طبق دافئ، مباشرة من الشواية، مع عصر الليمون فوقه على الطاولة. والتيكا تجلس جيدا أيضا على الأرز، وفي لفافة، أو فوق سلطة. وأبق تشاتني إضافية على الجانب، لأن الناس يطلبون المزيد دائما.","storage":"برده واحفظه في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى يومين. أعد تسخينه في فرن ساخن على 180 درجة مئوية لمدة 8 دقائق، أو في مقلاة على نار متوسطة، حتى يصبح ساخنا بالبخار. ولا تستخدم الميكروويف لمدة طويلة، لأنه يجفف الدجاج ويلين التحمير. والدجاج المتبل وغير المطهو يبقى في الثلاجة لمدة تصل إلى يوم واحد. وجمد التيكا المطهو لمدة تصل إلى شهر واحد وأذبه في الثلاجة.","mistakes":["شواء دجاج بارد من الثلاجة. يحمر الخارج قبل أن ينضج الداخل، لذلك اتركه يصل إلى درجة حرارة الغرفة أولا.","ازدحام الشواية. تتبخر القطع بدلا من أن تحمر، لذلك اترك مسافة واطبخ على دفعات إذا لزم الأمر.","تخطي الراحة. فالقطع فورا يترك العصارة تخرج ويجف التيكا.","استخدام تتبيلة رقيقة. تتقطر وتحترق، وتترك الدجاج بلا طعم."],"faq":[["هل يمكنني طهي التيكا في مقلاة؟","نعم. استخدم مقلاة ثقيلة على نار عالية مع قليل من الزيت، لمدة 6 إلى 7 دقائق لكل جانب. ولن يكون لها نفس التحمير المدخن، لكن النكهة قريبة."],["كيف أحصل على النكهة المدخنة في البيت؟","بعد الشواء، ضع وعاء فولاذيا صغيرا فيه قطعة فحم ساخنة في القدر، ورش بضع قطرات من الزيت عليها، وغطه لمدة دقيقتين، وأزل الوعاء. وأبق المطبخ مهوى."],["هل يمكنني استخدام دجاج الصدر؟","نعم، لكن لا تبالغ في طهيه. تحقق بعد 5 إلى 6 دقائق لكل جانب، واتركه يرتاح جيدا. والفخذ أكثر تسامحا."],["هل التيكا حارة؟","هي دافئة ومتبلة، وليست حارة بشدة. قلل الفلفل الأحمر الحار إلى ملعقة صغيرة لنسخة خفيفة، ودع التشاتني تضيف الحرارة على الطاولة."]]},"haleem":{"intro":"الحليم هو الطبخ البطيء بأصدق معنى، طبق الصبر الذي يكافئ ساعات الطبخ بعصيدة سميكة حريرية وقوام ليفي مشهور يسمى ريستا. القمح والشعير وأربعة أنواع من العدس تُنقع طوال الليل ثم تُطهى حتى تصبح طرية تماما، بينما يُطهى لحم البقر بشكل منفصل حتى يتفتت إلى ألياف دقيقة. ثم يُجمع الاثنان ويُهرسان في الغوتا التقليدي حتى تصبح الحبوب واللحم شيئا واحدا. تعود جذور الحليم إلى الطبق العربي الهريس، الذي وصل إلى حيدر آباد في العصر المغولي وتحول عبر القرون إلى الطبق الغني المحبوب في كل باكستان اليوم. إنه طبق ليالي رمضان وتجمعات محرم وعطلات نهاية الأسبوع العائلية الكبيرة، ويُقدم ساخنا مع البصل المقلي والزنجبيل والفلفل الأخضر والليمون وتشاات ماسالا.","ing":["قمح كامل (غندم) 1 كوب (منقوع طوال الليل)","شعير (جو) ½ كوب (منقوع طوال الليل)","عدس تشانا ½ كوب","عدس ماسور ¼ كوب","عدس مونغ ¼ كوب","عدس ماش ¼ كوب","لحم بقري 1 كغ","عظام لحم بقري 250 غ","سمن أو زيت 1 كوب","بصل 2 كبيرتان (مقطع شرائح رفيعة)","معجون زنجبيل 2 ملعقة كبيرة","معجون ثوم 2 ملعقة كبيرة","زبادي 1 كوب (مخفوقة)","مسحوق فلفل أحمر 2 ملعقة كبيرة","مسحوق فلفل كشميري 1 ملعقة كبيرة","مسحوق كزبرة 1½ ملعقة كبيرة","مسحوق كركم 1 ملعقة صغيرة","ماسالا الحليم 2 ملعقة كبيرة","ملح 2 ملعقة كبيرة","بذور كمون 1 ملعقة كبيرة","حبوب فلفل أسود 1 ملعقة صغيرة","قرنفل 6 إلى 8","هيل أخضر 5","هيل أسود 2","عيدان قرفة 2","صولجان 2","جوزة الطيب ¼ قطعة","يانسون نجمي 1","سمن ½ كوب","بصل 1 متوسطة (مقطعة شرائح رفيعة للتاركا)","زنجبيل 2 ملعقة كبيرة (مقطع شرائح رفيعة)","كزبرة طازجة ½ كوب (مفرومة)","نعناع طازج ½ كوب (مفروم)","فلفل أخضر 4","ليمون 3 (للتزيين)","تشاات ماسالا (للرش)"],"steps":["اغسل القمح والشعير وجميع أنواع العدس حتى يصبح الماء صافيا، ثم غطها بكمية كبيرة من الماء البارد وانقعها طوال الليل أو لمدة 8 ساعات على الأقل. انقع عدس الماسور والمونغ والماش لمدة ساعتين على الأقل.","صف الحبوب والعدس المنقوعة وضعها في قدر كبير ثقيل مع 12 كوب ماء و1 ملعقة صغيرة كركم و1 ملعقة صغيرة ملح، واتركها على نار هادئة مغطاة لمدة ساعتين إلى ساعتين ونصف حتى تصبح طرية تماما وهريسة.","حمص بذور الكمون وحبوب الفلفل الأسود والقرنفل والهيل الأخضر والأسود والقرفة والصولجان وجوزة الطيب واليانسون النجمي في مقلاة جافة لمدة دقيقة، ثم اتركها تبرد واطحنها حتى تصبح مسحوقا ناعما.","سخن 1 كوب سمن أو زيت في قدر كبير ثقيل، واقلي البصل المقطع حتى يصبح ذهبيا غامقا، وأخرج نصفه للتزيين. أضف معجون الزنجبيل والثوم واقليه لمدة دقيقة.","أضف اللحم والعظام وحمرهما على نار قوية لمدة 5 إلى 7 دقائق، ثم أضف مسحوق الفلفل الأحمر ومسحوق الفلفل الكشميري ومسحوق الكزبرة والكركم وماسالا الحليم والملح ونصف مسحوق البهارات المطحون، وحرك لمدة دقيقتين. اسكب الزبادي المخفوق واطه حتى ينفصل الزيت، ثم أضف 6 أكواب ماء.","غط القدر واطه حتى يصبح اللحم طريا تماما ويتفتت، 45 دقيقة في قدر الضغط أو ساعتين ونصف في القدر العادي. أخرج اللحم وتخلص من العظام الفارغة، وفتت اللحم البقري إلى ألياف دقيقة باليد باستخدام مدقة أو شوكتين. احتفظ بمرق الكورما.","اهرس الحبوب والعدس المطبوخة قليلا بالخلاط اليدوي مع ترك بعض القوام، وأضف اللحم المفتت مع المرق المحفوظ. اهرس وحرك بقوة على نار هادئة لمدة 30 إلى 45 دقيقة، مع إضافة بقية مسحوق البهارات، حتى يصبح الخليط سميكا ولزجا وليفيا.","سخن ½ كوب سمن في مقلاة صغيرة، واقلي البصل المقطع حتى يصبح مقرمشا وذهبيا، واسكب السمن الساخن مع البصل فوق الحليم. غط القدر لمدة 5 دقائق، ثم قدم ساخنا في أوعية مع البصل المقلي والزنجبيل والكزبرة والنعناع والفلفل الأخضر وشرائح الليمون وتشاات ماسالا، مع خبز نان ساخن بجانبه."],"tip":"انقع القمح والشعير لمدة 12 ساعة على الأقل، واهرس اللحم باليد. محضر الطعام يقطع ألياف اللحم قصيرة جدا ويفسد قوام الريستا الليفي. استخدم قدرا سميك القاع وحرك كثيرا، لأن الحليم السميك يلتصق ويحترق بسهولة.","notes":["القمح الكامل والشعير يحتاجان إلى نقع طويل، 8 ساعات على الأقل ويفضل طوال الليل، وإلا يبقيان رمليين ويحتاجان وقتا أطول بكثير للتفتت.","لحم البقر من الساق أو الكتف، في قطع كبيرة، يعطي الألياف الطويلة التي تصنع قوام الريستا الليفي. العظام تعطي القدر جسما وغنى.","ماسالا الحليم تختلف قوتها حسب العلامة التجارية. استخدم الكمية المذكورة في المرة الأولى وعدلها في المرة التالية.","السمن يعطي النكهة التقليدية. الزيت يعمل أيضا، ونصف سمن ونصف زيت حل وسط جيد."],"variations":["حليم الدجاج: استبدل اللحم بنفس وزن الدجاج بالعظم، الذي يطهى أسرع بكثير ويعطي نكهة أخف.","حليم لحم الضأن: استخدم لحم الماعز أو كتف الضأن لنكهة أغنى، تقليدية في مطابخ المغول الملكية.","حليم الشوفان النباتي: اترك اللحم، وضاعف العدس، وأضف رقائق الشوفان، واستخدم مرق الخضار مع بصل مقلي إضافي لعمق مالح."],"serving":"قدم ساخنا في أوعية واسعة ضحلة، مع الزينة على صينية على الطاولة حتى يتمكن كل شخص من إضافة البصل المقلي والزنجبيل والكزبرة والنعناع والفلفل الأخضر والليمون وتشاات ماسالا حسب ذوقه. يُقدم الحليم تقليديا مع خبز نان تندوري ساخن، أو يؤكل وحده بالملعقة. أحضر القدر إلى الطاولة وهو ما زال يغلي.","storage":"برده وضعه في الثلاجة في وعاء محكم لمدة تصل إلى 3 أيام. الحليم يثخن عندما يبرد. أعد تسخينه بلطف على نار هادئة إلى متوسطة مع رشة ماء أو مرق لحم، مع التحريك المستمر حتى لا يلتصق. جمده لمدة تصل إلى 3 أشهر، وذوبه طوال الليل في الثلاجة، وأضف الزينة الطازجة فقط عند التقديم.","mistakes":["استخدام محضر الطعام على اللحم. يقطع الألياف قصيرة ويعطي حساء رمليا بدلا من حليم ليفي.","تخطي النقع طوال الليل. تبقى الحبوب رملية وتحتاج وقتا أطول بكثير للتفتت.","الطبخ على نار قوية وعدم التحريك. الحليم السميك يلتصق بالقاع ويحترق.","تقديمه رقيقا جدا. استمر في الغلي والهرس على نار هادئة حتى يثخنه النشا إلى عصيدة تتكوم على الملعقة."],"faq":[["هل يمكنني تجميد الحليم؟","نعم. الحليم يتجمد بشكل ممتاز. اتركه يبرد تماما، وقسمه في أوعية محكمة وجمده لمدة تصل إلى 3 أشهر. ذوبه طوال الليل في الثلاجة قبل إعادة تسخينه."],["كيف أعيد تسخين الحليم؟","الحليم يثخن كثيرا عندما يبرد. ضعه في قدر مع رشة ماء أو مرق لحم وسخنه على نار هادئة إلى متوسطة، مع التحريك المستمر حتى لا يلتصق بالقاع."],["هل يمكنني صنع حليم خال من الغلوتين؟","الحليم التقليدي يعتمد على القمح والشعير، اللذين يحتويان على الغلوتين. لصنعه خاليا من الغلوتين، استبدل القمح والشعير برقائق الشوفان والأرز البني."],["ماذا أفعل إذا كان الحليم رقيقا جدا؟","استمر في غليه دون غطاء على نار هادئة مع هرسه بملعقة خشبية. نشا العدس والقمح يثخن الخليط مع تبخر الرطوبة الزائدة."]]}};
